--
-- Name: refresh_all_views(); Type: FUNCTION; Schema: analytics; Owner: -
--

CREATE FUNCTION analytics.refresh_all_views() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    RAISE NOTICE 'Refreshing analytics.team_season_summary...';
    REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.team_season_summary;

    RAISE NOTICE 'Refreshing analytics.player_career_stats...';
    REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.player_career_stats;

    RAISE NOTICE 'Refreshing analytics.conference_standings...';
    REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.conference_standings;

    RAISE NOTICE 'Refreshing analytics.team_recruiting_trend...';
    REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.team_recruiting_trend;

    RAISE NOTICE 'Refreshing analytics.game_results...';
    REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.game_results;

    RAISE NOTICE 'All analytics views refreshed.';
END;
$$;


--
-- Name: refresh_all(); Type: FUNCTION; Schema: marts; Owner: -
--

CREATE FUNCTION marts.refresh_all() RETURNS TABLE(view_name text, duration_ms bigint, status text)
    LANGUAGE plpgsql
    SET statement_timeout TO '0'
    SET search_path TO ''
    AS $$
DECLARE
    v_views text[];
    v_name text;
    v_start timestamptz;
    v_elapsed bigint;
    v_layer int;
BEGIN
    -- Layer 1: No dependencies on other marts
    v_views := ARRAY[
        '_game_epa_calc',
        'play_epa',
        'player_comparison',
        'conference_head_to_head',
        'team_wepa_season',
        'player_wepa_season',
        'returning_production',
        'player_usage',
        'team_ats_records',
        'core_ratings',
        -- penalty_log/team_penalty_box were in scripts/refresh_marts.py but
        -- missing here (drift); repaired alongside the core_ratings addition.
        'penalty_log',
        'team_penalty_box',
        -- 2026-08-30 expansion_views unit: passing charting (stats.passing_*)
        -- and coach_tenures (ref.coach_tenures) -- all read base tables only,
        -- no mart dependencies. Registered in the same Layer-1 slot as
        -- scripts/refresh_marts.py.
        'passing_charting_player_season',
        'passing_charting_target_season',
        'passing_charting_team_season',
        'coach_tenures',
        -- 2026-09-03 rushing_charting unit: rushing charting (stats.rushing_*)
        -- -- all read base tables only, no mart dependencies. Registered in
        -- the same Layer-1 slot as scripts/refresh_marts.py.
        'rushing_charting_player_season',
        'rushing_charting_team_season',
        'rushing_charting_direction_season'
    ];
    v_layer := 1;

    FOREACH v_name IN ARRAY v_views LOOP
        v_start := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW marts.%I', v_name);
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('OK (layer %s)', v_layer);
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('ERROR (layer %s): %s', v_layer, SQLERRM);
            RETURN NEXT;
        END;
    END LOOP;

    -- Layer 2: Depends on Layer 1
    v_views := ARRAY[
        'team_epa_season',
        'team_season_summary',
        'player_game_epa',
        'defensive_havoc',
        'scoring_opportunities',
        'team_playcalling_tendencies',
        'team_situational_success'
    ];
    v_layer := 2;

    FOREACH v_name IN ARRAY v_views LOOP
        v_start := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW marts.%I', v_name);
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('OK (layer %s)', v_layer);
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('ERROR (layer %s): %s', v_layer, SQLERRM);
            RETURN NEXT;
        END;
    END LOOP;

    -- Layer 3: Depends on Layer 2
    v_views := ARRAY[
        'situational_splits',
        'player_season_epa',
        'coach_record',
        'matchup_history',
        'recruiting_class',
        'team_talent_composite',
        'team_tempo_metrics',
        'transfer_portal_impact'
    ];
    v_layer := 3;

    FOREACH v_name IN ARRAY v_views LOOP
        v_start := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW marts.%I', v_name);
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('OK (layer %s)', v_layer);
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('ERROR (layer %s): %s', v_layer, SQLERRM);
            RETURN NEXT;
        END;
    END LOOP;

    -- Layer 4: Depends on Layer 3
    v_views := ARRAY[
        'team_season_trajectory',
        'conference_era_summary',
        'team_style_profile',
        'coaching_tenure',
        'recruiting_roi',
        'conference_comparison'
    ];
    v_layer := 4;

    FOREACH v_name IN ARRAY v_views LOOP
        v_start := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW marts.%I', v_name);
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('OK (layer %s)', v_layer);
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('ERROR (layer %s): %s', v_layer, SQLERRM);
            RETURN NEXT;
        END;
    END LOOP;

    -- Layer 5: Depends on Layer 4 + standalone
    v_views := ARRAY[
        'matchup_edges',
        'data_freshness'
    ];
    v_layer := 5;

    FOREACH v_name IN ARRAY v_views LOOP
        v_start := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW marts.%I', v_name);
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('OK (layer %s)', v_layer);
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('ERROR (layer %s): %s', v_layer, SQLERRM);
            RETURN NEXT;
        END;
    END LOOP;

    -- Layer 6: Tier 2 analytics (read from analytics.* staging + predictions)
    v_views := ARRAY[
        'house_elo',
        'house_elo_game',
        'team_adjusted_epa',
        'scored_matchup_edges',
        'prediction_accuracy'
    ];
    v_layer := 6;

    FOREACH v_name IN ARRAY v_views LOOP
        v_start := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW marts.%I', v_name);
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('OK (layer %s)', v_layer);
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('ERROR (layer %s): %s', v_layer, SQLERRM);
            RETURN NEXT;
        END;
    END LOOP;

    -- Layer 7: Tier 3 analytics (computed from play/feature builds, depends on Layer 6)
    v_views := ARRAY[
        'team_week_features',
        'adjusted_epa_week',
        -- Refresh-campaign plausibility harness: reads team_adjusted_epa
        -- (layer 6) and team_epa_season (layer 2) against the external
        -- ratings tables. Legitimately empty until an external anchor loads.
        'epa_crossvalidation'
    ];
    v_layer := 7;

    FOREACH v_name IN ARRAY v_views LOOP
        v_start := clock_timestamp();
        BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW marts.%I', v_name);
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('OK (layer %s)', v_layer);
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            v_elapsed := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::bigint;
            view_name := v_name;
            duration_ms := v_elapsed;
            status := format('ERROR (layer %s): %s', v_layer, SQLERRM);
            RETURN NEXT;
        END;
    END LOOP;
END;
$$;


