COMMENT ON FUNCTION marts.refresh_all() IS 'Refreshes all 50 materialized views in the marts schema in dependency order (7 layers). Returns timing and status for each view. Errors are caught per-view so one failure does not abort the rest.';


--
-- Name: reject_snapshot_update(); Type: FUNCTION; Schema: predictions; Owner: -
--

CREATE FUNCTION predictions.reject_snapshot_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    RAISE EXCEPTION 'Prediction and model artifact snapshots are immutable; append a new snapshot';
END
$$;


--
-- Name: stamp_prediction_provenance(); Type: FUNCTION; Schema: predictions; Owner: -
--

CREATE FUNCTION predictions.stamp_prediction_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.evaluation_mode IS NULL OR NEW.evaluation_mode = 'legacy_unknown' THEN
        RAISE EXCEPTION 'New predictions require explicit non-legacy provenance';
    END IF;
    -- statement_timestamp, unlike now(), is not the start of a transaction
    -- which may have spent minutes loading/scoring. Never trust a supplied time.
    NEW.created_at := statement_timestamp();
    NEW.published_at := CASE WHEN NEW.evaluation_mode = 'published_forecast'
        THEN NEW.created_at ELSE NULL END;
    RETURN NEW;
END
$$;


--
-- Name: get_available_seasons(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_seasons() RETURNS integer[]
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT ARRAY_AGG(DISTINCT season ORDER BY season DESC)
    FROM core.games
    WHERE completed = true;
$$;


--
-- Name: get_available_weeks(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_weeks(p_season integer) RETURNS integer[]
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT ARRAY_AGG(DISTINCT week ORDER BY week)
    FROM core.games
    WHERE season = p_season AND completed = true;
$$;


--
-- Name: get_conference_head_to_head(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conference_head_to_head(p_conf1 text, p_conf2 text, p_season_start integer DEFAULT NULL::integer, p_season_end integer DEFAULT NULL::integer) RETURNS TABLE(conference_1 text, conference_2 text, season bigint, total_games integer, conf1_wins integer, conf2_wins integer, ties integer, conf1_win_pct numeric, avg_point_diff numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT
        h.conference_1,
        h.conference_2,
        h.season,
        h.total_games,
        CASE WHEN LEAST(p_conf1, p_conf2) = p_conf1
            THEN h.conf1_wins ELSE h.conf2_wins END AS conf1_wins,
        CASE WHEN LEAST(p_conf1, p_conf2) = p_conf1
            THEN h.conf2_wins ELSE h.conf1_wins END AS conf2_wins,
        h.ties,
        CASE WHEN LEAST(p_conf1, p_conf2) = p_conf1
            THEN h.conf1_win_pct
            ELSE ROUND(1.0 - COALESCE(h.conf1_win_pct, 0), 4)
        END AS conf1_win_pct,
        CASE WHEN LEAST(p_conf1, p_conf2) = p_conf1
            THEN h.avg_point_diff
            ELSE -h.avg_point_diff
        END AS avg_point_diff
    FROM marts.conference_head_to_head h
    WHERE h.conference_1 = LEAST(p_conf1, p_conf2)
      AND h.conference_2 = GREATEST(p_conf1, p_conf2)
      AND (p_season_start IS NULL OR h.season >= p_season_start)
      AND (p_season_end IS NULL OR h.season <= p_season_end)
    ORDER BY h.season DESC;
$$;


--
-- Name: FUNCTION get_conference_head_to_head(p_conf1 text, p_conf2 text, p_season_start integer, p_season_end integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_conference_head_to_head(p_conf1 text, p_conf2 text, p_season_start integer, p_season_end integer) IS 'Conference vs conference head-to-head records by season. Results are always oriented so p_conf1 wins/pct are shown first, regardless of alphabetical order. Optional season range filtering.';


--
-- Name: get_conference_splits(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conference_splits(p_team text, p_season integer) RETURNS TABLE(opponent_type text, games bigint, wins bigint, win_pct numeric, points_per_game numeric, points_allowed_per_game numeric, epa_per_play numeric, success_rate numeric, margin_per_game numeric)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_team_conference TEXT;
BEGIN
    SELECT conference INTO v_team_conference
    FROM public.teams
    WHERE school = p_team;

    RETURN QUERY
    WITH game_results AS (
        SELECT
            CASE
                WHEN opp.conference = v_team_conference THEN 'conference'
                ELSE 'non_conference'
            END AS opponent_type,
            g.id AS game_id,
            CASE WHEN g.home_team = p_team THEN g.home_points ELSE g.away_points END AS points_for,
            CASE WHEN g.home_team = p_team THEN g.away_points ELSE g.home_points END AS points_against,
            CASE
                WHEN (g.home_team = p_team AND g.home_points > g.away_points) OR
                     (g.away_team = p_team AND g.away_points > g.home_points)
                THEN 1 ELSE 0
            END AS won
        FROM core.games g
        JOIN public.teams opp ON opp.school = CASE WHEN g.home_team = p_team THEN g.away_team ELSE g.home_team END
        WHERE g.season = p_season
          AND (g.home_team = p_team OR g.away_team = p_team)
          AND g.home_points IS NOT NULL
    ),
    play_stats AS (
        SELECT
            CASE
                WHEN opp.conference = v_team_conference THEN 'conference'
                ELSE 'non_conference'
            END AS opponent_type,
            p.ppa,
            CASE WHEN p.ppa > 0 THEN 1 ELSE 0 END AS successful
        FROM core.plays p
        JOIN core.games g ON p.game_id = g.id
        JOIN public.teams opp ON opp.school = CASE WHEN g.home_team = p_team THEN g.away_team ELSE g.home_team END
        WHERE g.season = p_season
          AND p.offense = p_team
          AND NOT public.is_garbage_time(p.period::integer, p.score_diff::integer)
    )
    SELECT
        gr.opponent_type::TEXT,
        COUNT(DISTINCT gr.game_id)::BIGINT AS games,
        SUM(gr.won)::BIGINT AS wins,
        ROUND(SUM(gr.won)::NUMERIC / NULLIF(COUNT(DISTINCT gr.game_id), 0), 3) AS win_pct,
        ROUND(AVG(gr.points_for)::NUMERIC, 1) AS points_per_game,
        ROUND(AVG(gr.points_against)::NUMERIC, 1) AS points_allowed_per_game,
        ROUND((SELECT AVG(ps.ppa) FROM play_stats ps WHERE ps.opponent_type = gr.opponent_type)::NUMERIC, 3) AS epa_per_play,
        ROUND((SELECT AVG(ps.successful) FROM play_stats ps WHERE ps.opponent_type = gr.opponent_type)::NUMERIC, 3) AS success_rate,
        ROUND(AVG(gr.points_for - gr.points_against)::NUMERIC, 1) AS margin_per_game
    FROM game_results gr
    GROUP BY gr.opponent_type
    ORDER BY gr.opponent_type;
END;
$$;


--
-- Name: get_data_freshness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_data_freshness() RETURNS TABLE(schema_name text, table_name text, row_count bigint, expected_refresh_frequency text, days_since_activity numeric, is_stale boolean)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT
        f.schema_name,
        f.table_name,
        f.row_count,
        f.expected_refresh_frequency,
        f.days_since_activity,
        f.is_stale
    FROM marts.data_freshness f
    ORDER BY f.is_stale DESC, f.schema_name, f.table_name;
$$;


