CREATE FUNCTION public.get_down_distance_splits(p_team text, p_season integer) RETURNS TABLE(down integer, distance_bucket text, side text, play_count bigint, success_rate numeric, epa_per_play numeric, conversion_rate numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    WITH bucketed_plays AS (
        SELECT
            pe.down,
            -- Recompute 4-bucket distance scheme for frontend compatibility
            -- (matview uses short/medium/long; frontend expects 1-3/4-6/7-10/11+)
            CASE
                WHEN pe.distance BETWEEN 1 AND 3 THEN '1-3'
                WHEN pe.distance BETWEEN 4 AND 6 THEN '4-6'
                WHEN pe.distance BETWEEN 7 AND 10 THEN '7-10'
                ELSE '11+'
            END AS distance_bucket,
            CASE
                WHEN pe.offense = p_team THEN 'offense'
                ELSE 'defense'
            END AS side,
            pe.epa,
            pe.success,
            CASE
                WHEN pe.down IN (3, 4) AND pe.yards_gained >= pe.distance THEN 1
                ELSE 0
            END AS converted
        FROM marts.play_epa pe
        WHERE pe.season = p_season
          AND (pe.offense = p_team OR pe.defense = p_team)
          AND pe.down IS NOT NULL
          AND pe.down BETWEEN 1 AND 4
          AND pe.distance IS NOT NULL
          AND pe.distance > 0
          AND NOT pe.is_garbage_time
    )
    SELECT
        bp.down::INT,
        bp.distance_bucket::TEXT,
        bp.side::TEXT,
        COUNT(*)::BIGINT AS play_count,
        ROUND(AVG(bp.success)::NUMERIC, 3) AS success_rate,
        ROUND(AVG(bp.epa)::NUMERIC, 3) AS epa_per_play,
        CASE
            WHEN bp.down IN (3, 4) THEN ROUND(AVG(bp.converted)::NUMERIC, 3)
            ELSE NULL
        END AS conversion_rate
    FROM bucketed_plays bp
    GROUP BY bp.down, bp.distance_bucket, bp.side
    ORDER BY bp.side, bp.down, bp.distance_bucket;
END;
$$;


--
-- Name: get_drive_patterns(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_drive_patterns(p_team text, p_season integer, p_side text DEFAULT 'offense'::text) RETURNS TABLE(start_yard integer, end_yard integer, outcome text, count bigint, avg_plays numeric, avg_yards numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH drive_outcomes AS (
    SELECT
      (100 - d.start_yards_to_goal)::INT AS start_yard,
      LEAST(100, (100 - d.start_yards_to_goal + d.yards))::INT AS end_yard,
      CASE
        WHEN d.drive_result IN ('TD', 'TOUCHDOWN', 'Touchdown') THEN 'touchdown'
        WHEN d.drive_result IN ('FG', 'FIELD GOAL', 'FG GOOD', 'Field Goal') THEN 'field_goal'
        WHEN d.drive_result IN ('PUNT', 'Punt') THEN 'punt'
        WHEN d.drive_result IN ('INT', 'INTERCEPTION', 'FUMBLE', 'FUMBLE LOST', 'INT TD', 'FUMBLE TD', 'Interception', 'Fumble', 'Fumble Lost', 'Interception Return') THEN 'turnover'
        WHEN d.drive_result IN ('END OF HALF', 'END OF GAME', 'END OF 4TH QUARTER', 'End of Half', 'End of Game') THEN 'end_of_half'
        WHEN d.drive_result IN ('DOWNS', 'TURNOVER ON DOWNS', 'Downs', 'Turnover on Downs') THEN 'downs'
        ELSE 'other'
      END AS outcome,
      d.plays,
      d.yards
    FROM core.drives d
    WHERE CASE
        WHEN p_side = 'defense' THEN d.defense = p_team
        ELSE d.offense = p_team
      END
      AND d.season = p_season
      AND d.start_yards_to_goal IS NOT NULL
  )
  SELECT
    (FLOOR(drv.start_yard / 10.0) * 10)::INT AS start_yard,
    (FLOOR(drv.end_yard / 10.0) * 10)::INT AS end_yard,
    drv.outcome,
    COUNT(*)::BIGINT AS count,
    ROUND(AVG(drv.plays), 1) AS avg_plays,
    ROUND(AVG(drv.yards), 1) AS avg_yards
  FROM drive_outcomes drv
  WHERE drv.outcome != 'other'
  GROUP BY 1, 2, drv.outcome
  ORDER BY drv.outcome, 1, 2;
END;
$$;


--
-- Name: get_field_position_splits(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_field_position_splits(p_team text, p_season integer) RETURNS TABLE(zone text, zone_label text, side text, play_count bigint, success_rate numeric, epa_per_play numeric, yards_per_play numeric, scoring_rate numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    WITH zoned_plays AS (
        SELECT
            CASE
                WHEN pe.offense = p_team THEN 'offense'
                ELSE 'defense'
            END AS side,
            -- Recompute 4-zone field position from yards_to_goal
            -- yards_to_goal is from offense perspective; zones flip for defense
            -- yards_to_goal == yardline in CFBD data; use same boundaries as original
            CASE
                WHEN pe.offense = p_team THEN
                    CASE
                        WHEN pe.yards_to_goal >= 80 THEN 'own_1_20'
                        WHEN pe.yards_to_goal >= 50 THEN 'own_21_50'
                        WHEN pe.yards_to_goal >= 20 THEN 'opp_49_21'
                        ELSE 'opp_20_1'
                    END
                ELSE
                    CASE
                        WHEN pe.yards_to_goal <= 20 THEN 'own_1_20'
                        WHEN pe.yards_to_goal <= 50 THEN 'own_21_50'
                        WHEN pe.yards_to_goal <= 80 THEN 'opp_49_21'
                        ELSE 'opp_20_1'
                    END
            END AS zone,
            pe.epa,
            pe.yards_gained,
            CASE WHEN pe.scoring = true THEN 1 ELSE 0 END AS scored,
            pe.success AS successful
        FROM marts.play_epa pe
        WHERE pe.season = p_season
          AND (pe.offense = p_team OR pe.defense = p_team)
          AND pe.yards_to_goal IS NOT NULL
          AND NOT pe.is_garbage_time
    )
    SELECT
        zp.zone::TEXT,
        CASE zp.zone
            WHEN 'own_1_20' THEN 'Own 1-20'
            WHEN 'own_21_50' THEN 'Own 21-50'
            WHEN 'opp_49_21' THEN 'Opp 49-21'
            WHEN 'opp_20_1' THEN 'Red Zone'
        END::TEXT AS zone_label,
        zp.side::TEXT,
        COUNT(*)::BIGINT AS play_count,
        ROUND(AVG(zp.successful)::NUMERIC, 3) AS success_rate,
        ROUND(AVG(zp.epa)::NUMERIC, 3) AS epa_per_play,
        ROUND(AVG(zp.yards_gained)::NUMERIC, 1) AS yards_per_play,
        ROUND(AVG(zp.scored)::NUMERIC, 3) AS scoring_rate
    FROM zoned_plays zp
    GROUP BY zp.zone, zp.side
    ORDER BY zp.side,
        CASE zp.zone
            WHEN 'own_1_20' THEN 1
            WHEN 'own_21_50' THEN 2
            WHEN 'opp_49_21' THEN 3
            WHEN 'opp_20_1' THEN 4
        END;
END;
$$;


--
-- Name: get_home_away_splits(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_home_away_splits(p_team text, p_season integer) RETURNS TABLE(location text, games bigint, wins bigint, win_pct numeric, points_per_game numeric, points_allowed_per_game numeric, epa_per_play numeric, success_rate numeric, yards_per_play numeric)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    WITH game_results AS (
        SELECT
            CASE WHEN g.home_team = p_team THEN 'home' ELSE 'away' END AS location,
            g.id AS game_id,
            CASE WHEN g.home_team = p_team THEN g.home_points ELSE g.away_points END AS points_for,
            CASE WHEN g.home_team = p_team THEN g.away_points ELSE g.home_points END AS points_against,
            CASE
                WHEN (g.home_team = p_team AND g.home_points > g.away_points) OR
                     (g.away_team = p_team AND g.away_points > g.home_points)
                THEN 1 ELSE 0
            END AS won
        FROM core.games g
        WHERE g.season = p_season
          AND (g.home_team = p_team OR g.away_team = p_team)
          AND g.home_points IS NOT NULL
    ),
    play_stats AS (
        SELECT
            CASE WHEN g.home_team = p_team THEN 'home' ELSE 'away' END AS location,
            p.ppa,
            CASE WHEN p.ppa > 0 THEN 1 ELSE 0 END AS successful,
            p.yards_gained
        FROM core.plays p
        JOIN core.games g ON p.game_id = g.id
        WHERE g.season = p_season
          AND p.offense = p_team
          AND NOT public.is_garbage_time(p.period::integer, p.score_diff::integer)
    )
    SELECT
        gr.location::TEXT,
        COUNT(DISTINCT gr.game_id)::BIGINT AS games,
        SUM(gr.won)::BIGINT AS wins,
        ROUND(SUM(gr.won)::NUMERIC / NULLIF(COUNT(DISTINCT gr.game_id), 0), 3) AS win_pct,
        ROUND(AVG(gr.points_for)::NUMERIC, 1) AS points_per_game,
        ROUND(AVG(gr.points_against)::NUMERIC, 1) AS points_allowed_per_game,
        ROUND((SELECT AVG(ps.ppa) FROM play_stats ps WHERE ps.location = gr.location)::NUMERIC, 3) AS epa_per_play,
        ROUND((SELECT AVG(ps.successful) FROM play_stats ps WHERE ps.location = gr.location)::NUMERIC, 3) AS success_rate,
        ROUND((SELECT AVG(ps.yards_gained) FROM play_stats ps WHERE ps.location = gr.location)::NUMERIC, 1) AS yards_per_play
    FROM game_results gr
    GROUP BY gr.location
    ORDER BY gr.location DESC;
END;
$$;


--
-- Name: get_player_detail(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_detail(p_player_id text, p_season integer DEFAULT NULL::integer) RETURNS TABLE(player_id character varying, name text, team character varying, "position" character varying, jersey bigint, height bigint, weight bigint, year bigint, home_city character varying, home_state character varying, season bigint, stars bigint, recruit_rating double precision, national_ranking bigint, recruit_class bigint, pass_att numeric, pass_cmp numeric, pass_yds numeric, pass_td numeric, pass_int numeric, pass_pct numeric, rush_car numeric, rush_yds numeric, rush_td numeric, rush_ypc numeric, rec numeric, rec_yds numeric, rec_td numeric, rec_ypr numeric, tackles numeric, solo numeric, sacks numeric, tfl numeric, pass_def numeric, def_int numeric, fg_made numeric, fg_att numeric, xp_made numeric, xp_att numeric, punt_yds numeric, wepa_passing double precision, wepa_rushing double precision, paar double precision, rushing_charting jsonb)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    pc.player_id::varchar,
    pc.name::text,
    pc.team::varchar,
    pc.position::varchar,
    pc.jersey::bigint,
    pc.height::bigint,
    pc.weight::bigint,
    pc.season::bigint AS year,
    pc.home_city::varchar,
    pc.home_state::varchar,
    pc.season::bigint,
    pc.stars::bigint,
    pc.recruit_rating::double precision,
    pc.national_ranking::bigint,
    pc.recruit_class::bigint,
    pc.pass_att::numeric,
    pc.pass_cmp::numeric,
    pc.pass_yds::numeric,
    pc.pass_td::numeric,
    pc.pass_int::numeric,
    pc.pass_pct::numeric,
    pc.rush_car::numeric,
    pc.rush_yds::numeric,
    pc.rush_td::numeric,
    pc.rush_ypc::numeric,
    pc.rec::numeric,
    pc.rec_yds::numeric,
    pc.rec_td::numeric,
    pc.rec_ypr::numeric,
    pc.tackles::numeric,
    NULL::numeric AS solo,
    pc.sacks::numeric,
    pc.tfl::numeric,
    pc.pass_def::numeric,
    NULL::numeric AS def_int,
    NULL::numeric AS fg_made,
    NULL::numeric AS fg_att,
    NULL::numeric AS xp_made,
    NULL::numeric AS xp_att,
    NULL::numeric AS punt_yds,
    wp_pass.wepa::double precision AS wepa_passing,
    wp_rush.wepa::double precision AS wepa_rushing,
    wp_kick.paar::double precision AS paar,
    CASE WHEN rcps.player_id IS NULL THEN NULL ELSE
      jsonb_build_object(
        'attempts', rcps.attempts,
        'individual_attempts', rcps.individual_attempts,
        'unattributed_attempts', rcps.unattributed_attempts,
        'sacks', rcps.sacks,
        'kneels', rcps.kneels,
        'team_rushes', rcps.team_rushes,
        'multi_carrier_attempts', rcps.multi_carrier_attempts,
        'total_rushing_yards', rcps.total_rushing_yards,
        'yards_per_carry', rcps.yards_per_carry,
        'success_rate', rcps.success_rate,
        'ppa', rcps.ppa,
        'total_ppa', rcps.total_ppa,
        'line_yards', rcps.line_yards,
        'line_yards_total', rcps.line_yards_total,
        'second_level_yards', rcps.second_level_yards,
        'second_level_yards_total', rcps.second_level_yards_total,
        'open_field_yards', rcps.open_field_yards,
        'open_field_yards_total', rcps.open_field_yards_total,
        'stuff_rate', rcps.stuff_rate,
        'power_success', rcps.power_success,
        'explosiveness', rcps.explosiveness,
        'rushing_yards_available', rcps.rushing_yards_available,
        'direction_eligible_attempts', rcps.direction_eligible_attempts,
        'direction_available_attempts', rcps.direction_available_attempts,
        'directions', (
          SELECT jsonb_object_agg(d.direction, jsonb_build_object(
            'carries', d.carries,
            'yards', d.yards,
            'yards_per_carry', d.yards_per_carry,
            'success_rate', d.success_rate,
            'ppa', d.ppa,
            'total_ppa', d.total_ppa,
            'line_yards', d.line_yards,
            'line_yards_total', d.line_yards_total,
            'second_level_yards', d.second_level_yards,
            'second_level_yards_total', d.second_level_yards_total,
            'open_field_yards', d.open_field_yards,
            'open_field_yards_total', d.open_field_yards_total,
            'stuff_rate', d.stuff_rate,
            'power_success', d.power_success,
            'explosiveness', d.explosiveness
          ))
          FROM marts.rushing_charting_direction_season d
          WHERE d.entity_type = 'player'
            AND d.entity_id = rcps.player_id
            AND d.season = rcps.season
            AND d.team = rcps.team
            AND d.side = 'offense'
        )
      )
    END AS rushing_charting
  FROM marts.player_comparison pc
  LEFT JOIN marts.player_wepa_season wp_pass
    ON wp_pass.athlete_id::text = pc.player_id::text
    AND wp_pass.season = pc.season
    AND wp_pass.category = 'passing'
  LEFT JOIN marts.player_wepa_season wp_rush
    ON wp_rush.athlete_id::text = pc.player_id::text
    AND wp_rush.season = pc.season
    AND wp_rush.category = 'rushing'
  LEFT JOIN marts.player_wepa_season wp_kick
    ON wp_kick.athlete_id::text = pc.player_id::text
    AND wp_kick.season = pc.season
    AND wp_kick.category = 'kicking'
  LEFT JOIN marts.rushing_charting_player_season rcps
    ON rcps.player_id = pc.player_id::text
    AND rcps.season = pc.season
    AND rcps.team = pc.team
  WHERE pc.player_id = p_player_id
    AND (p_season IS NULL OR pc.season = p_season)
  ORDER BY pc.season DESC
  LIMIT 1;
$$;


--
-- Name: get_player_game_log(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_game_log(p_player_id text, p_season integer) RETURNS TABLE(game_id bigint, season integer, team text, player_name text, play_category text, plays bigint, total_epa numeric, epa_per_play numeric, success_rate numeric, explosive_plays bigint, total_yards numeric, week integer, opponent text, home_away text, result text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH player_info AS (
    SELECT
      r.first_name || ' ' || r.last_name AS full_name,
      r.team
    FROM core.roster r
    WHERE r.id = p_player_id
      AND r.year = p_season
    LIMIT 1
  )
  SELECT
    e.game_id::bigint,
    e.season::integer,
    e.team::text,
    e.player_name::text,
    e.play_category::text,
    e.plays::bigint,
    e.total_epa::numeric,
    e.epa_per_play::numeric,
    e.success_rate::numeric,
    e.explosive_plays::bigint,
    e.total_yards::numeric,
    g.week::integer,
    CASE WHEN g.home_team = e.team THEN g.away_team ELSE g.home_team END::text AS opponent,
    CASE WHEN g.home_team = e.team THEN 'home' ELSE 'away' END::text AS home_away,
    CASE
      WHEN g.home_team = e.team AND g.home_points > g.away_points THEN 'W'
      WHEN g.home_team = e.team AND g.home_points < g.away_points THEN 'L'
      WHEN g.away_team = e.team AND g.away_points > g.home_points THEN 'W'
      WHEN g.away_team = e.team AND g.away_points < g.home_points THEN 'L'
      WHEN g.home_points = g.away_points THEN 'T'
      ELSE NULL
    END::text AS result
  FROM marts.player_game_epa e
  JOIN core.games g ON g.id = e.game_id
  LEFT JOIN player_info pi ON true
  WHERE e.season = p_season
    AND (
      e.athlete_id::text = p_player_id
      OR (e.athlete_id IS NULL AND e.player_name = pi.full_name AND e.team = pi.team)
    )
  ORDER BY g.week;
$$;


--
-- Name: get_player_percentiles(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_percentiles(p_player_id text, p_season integer) RETURNS TABLE(player_id character varying, name character varying, team character varying, "position" character varying, position_group text, season integer, pass_yds numeric, pass_td numeric, pass_pct numeric, rush_yds numeric, rush_td numeric, rush_ypc numeric, rec_yds numeric, rec_td numeric, tackles numeric, sacks numeric, tfl numeric, ppa_avg double precision, pass_yds_pctl double precision, pass_td_pctl double precision, pass_pct_pctl double precision, rush_yds_pctl double precision, rush_td_pctl double precision, rush_ypc_pctl double precision, rec_yds_pctl double precision, rec_td_pctl double precision, tackles_pctl double precision, sacks_pctl double precision, tfl_pctl double precision, ppa_avg_pctl double precision)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    pc.player_id::varchar,
    pc.name::varchar,
    pc.team::varchar,
    pc.position::varchar,
    pc.position_group::text,
    pc.season::integer,
    pc.pass_yds::numeric,
    pc.pass_td::numeric,
    pc.pass_pct::numeric,
    pc.rush_yds::numeric,
    pc.rush_td::numeric,
    pc.rush_ypc::numeric,
    pc.rec_yds::numeric,
    pc.rec_td::numeric,
    pc.tackles::numeric,
    pc.sacks::numeric,
    pc.tfl::numeric,
    pc.ppa_avg::float,
    pc.pass_yds_pctl::float,
    pc.pass_td_pctl::float,
    pc.pass_pct_pctl::float,
    pc.rush_yds_pctl::float,
    pc.rush_td_pctl::float,
    pc.rush_ypc_pctl::float,
    pc.rec_yds_pctl::float,
    pc.rec_td_pctl::float,
    pc.tackles_pctl::float,
    pc.sacks_pctl::float,
    pc.tfl_pctl::float,
    pc.ppa_avg_pctl::float
  FROM marts.player_comparison pc
  WHERE pc.player_id = p_player_id
    AND pc.season = p_season
  LIMIT 1;
$$;


--
-- Name: get_player_search(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_search(p_query text, p_position text DEFAULT NULL::text, p_team text DEFAULT NULL::text, p_season integer DEFAULT NULL::integer, p_limit integer DEFAULT 25) RETURNS TABLE(player_id text, name text, team text, "position" text, season bigint, height bigint, weight bigint, jersey bigint, stars bigint, recruit_rating double precision, similarity_score real)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        r.id::text AS player_id,
        (r.first_name || ' ' || r.last_name)::text AS "name",
        r.team::text,
        r.position::text AS "position",
        r.year AS season,
        r.height,
        r.weight,
        r.jersey,
        rec.stars,
        rec.rating AS recruit_rating,
        public.similarity(lower(r.first_name || ' ' || r.last_name), lower(p_query)) AS similarity_score
    FROM core.roster r
    LEFT JOIN LATERAL (
        SELECT rr.stars, rr.rating
        FROM recruiting.recruits rr
        WHERE rr.athlete_id = r.id
        ORDER BY rr.rating DESC NULLS LAST
        LIMIT 1
    ) rec ON true
    WHERE lower(r.first_name || ' ' || r.last_name) OPERATOR(public.%) lower(p_query)
      AND (p_position IS NULL OR r.position = p_position)
      AND (p_team IS NULL OR r.team = p_team)
      AND (p_season IS NULL OR r.year = p_season)
    ORDER BY similarity_score DESC
    LIMIT p_limit;
END;
$$;


--
-- Name: FUNCTION get_player_search(p_query text, p_position text, p_team text, p_season integer, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_player_search(p_query text, p_position text, p_team text, p_season integer, p_limit integer) IS 'Fuzzy player search using pg_trgm trigram matching. Supports optional filters for position, team, and season. Returns recruit star rating when available.';


--
-- Name: get_player_season_leaders(integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_season_leaders(p_season integer, p_category text DEFAULT 'passing'::text, p_conference text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS TABLE(player_id character varying, player_name character varying, team character varying, conference character varying, "position" character varying, yards numeric, touchdowns numeric, interceptions numeric, pct numeric, attempts numeric, completions numeric, carries numeric, yards_per_carry numeric, receptions numeric, yards_per_reception numeric, longest numeric, total_tackles numeric, solo_tackles numeric, sacks numeric, tackles_for_loss numeric, passes_defended numeric, yards_rank bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    pc.player_id::varchar,
    pc.name::varchar AS player_name,
    pc.team::varchar,
    t.conference::varchar,
    pc.position::varchar,
    CASE p_category
      WHEN 'passing'   THEN pc.pass_yds::numeric
      WHEN 'rushing'   THEN pc.rush_yds::numeric
      WHEN 'receiving' THEN pc.rec_yds::numeric
      WHEN 'defense'   THEN NULL
    END AS yards,
    CASE p_category
      WHEN 'passing'   THEN pc.pass_td::numeric
      WHEN 'rushing'   THEN pc.rush_td::numeric
      WHEN 'receiving' THEN pc.rec_td::numeric
      WHEN 'defense'   THEN NULL
    END AS touchdowns,
    CASE p_category
      WHEN 'passing'  THEN pc.pass_int::numeric
      WHEN 'defense'  THEN NULL
      ELSE NULL
    END AS interceptions,
    CASE WHEN p_category = 'passing' THEN pc.pass_pct::numeric ELSE NULL END AS pct,
    CASE WHEN p_category = 'passing' THEN pc.pass_att::numeric ELSE NULL END AS attempts,
    CASE WHEN p_category = 'passing' THEN pc.pass_cmp::numeric ELSE NULL END AS completions,
    CASE WHEN p_category = 'rushing' THEN pc.rush_car::numeric ELSE NULL END AS carries,
    CASE WHEN p_category = 'rushing' THEN pc.rush_ypc::numeric ELSE NULL END AS yards_per_carry,
    CASE WHEN p_category = 'receiving' THEN pc.rec::numeric ELSE NULL END AS receptions,
    CASE WHEN p_category = 'receiving' THEN pc.rec_ypr::numeric ELSE NULL END AS yards_per_reception,
    NULL::numeric AS longest,
    CASE WHEN p_category = 'defense' THEN pc.tackles::numeric ELSE NULL END AS total_tackles,
    NULL::numeric AS solo_tackles,
    CASE WHEN p_category = 'defense' THEN pc.sacks::numeric ELSE NULL END AS sacks,
    CASE WHEN p_category = 'defense' THEN pc.tfl::numeric ELSE NULL END AS tackles_for_loss,
    CASE WHEN p_category = 'defense' THEN pc.pass_def::numeric ELSE NULL END AS passes_defended,
    RANK() OVER (
      ORDER BY
        CASE p_category
          WHEN 'passing'   THEN pc.pass_yds::numeric
          WHEN 'rushing'   THEN pc.rush_yds::numeric
          WHEN 'receiving' THEN pc.rec_yds::numeric
          WHEN 'defense'   THEN pc.tackles::numeric
        END DESC NULLS LAST
    ) AS yards_rank
  FROM marts.player_comparison pc
  LEFT JOIN public.teams_with_logos t ON t.school = pc.team
  WHERE pc.season = p_season
    AND (p_conference IS NULL OR t.conference = p_conference)
    AND CASE p_category
      WHEN 'passing'   THEN pc.pass_att::numeric > 0
      WHEN 'rushing'   THEN pc.rush_car::numeric > 0
      WHEN 'receiving' THEN pc.rec::numeric > 0
      WHEN 'defense'   THEN pc.tackles::numeric > 0
      ELSE true
    END
  ORDER BY
    CASE p_category
      WHEN 'passing'   THEN pc.pass_yds::numeric
      WHEN 'rushing'   THEN pc.rush_yds::numeric
      WHEN 'receiving' THEN pc.rec_yds::numeric
      WHEN 'defense'   THEN pc.tackles::numeric
    END DESC NULLS LAST
  LIMIT p_limit;
$$;


--
-- Name: get_player_season_stats_pivoted(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_season_stats_pivoted(p_team text, p_season integer) RETURNS TABLE(player_id character varying, player character varying, "position" character varying, pass_att integer, pass_comp integer, pass_yds integer, pass_td integer, pass_int integer, rush_car integer, rush_yds integer, rush_td integer, rec integer, rec_yds integer, rec_td integer, tackles integer, solo integer, tfl numeric, sacks numeric, interceptions integer, pd integer, fg_made integer, fg_att integer, xp_made integer, xp_att integer, points integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    WITH pivoted AS (
        SELECT
            s.player_id,
            s.player,
            s.position,
            MAX(CASE WHEN s.category = 'passing' AND s.stat_type = 'ATT' THEN s.stat::INT END) AS pass_att,
            MAX(CASE WHEN s.category = 'passing' AND s.stat_type = 'COMPLETIONS' THEN s.stat::INT END) AS pass_comp,
            MAX(CASE WHEN s.category = 'passing' AND s.stat_type = 'YDS' THEN s.stat::INT END) AS pass_yds,
            MAX(CASE WHEN s.category = 'passing' AND s.stat_type = 'TD' THEN s.stat::INT END) AS pass_td,
            MAX(CASE WHEN s.category = 'passing' AND s.stat_type = 'INT' THEN s.stat::INT END) AS pass_int,
            MAX(CASE WHEN s.category = 'rushing' AND s.stat_type = 'CAR' THEN s.stat::INT END) AS rush_car,
            MAX(CASE WHEN s.category = 'rushing' AND s.stat_type = 'YDS' THEN s.stat::INT END) AS rush_yds,
            MAX(CASE WHEN s.category = 'rushing' AND s.stat_type = 'TD' THEN s.stat::INT END) AS rush_td,
            MAX(CASE WHEN s.category = 'receiving' AND s.stat_type = 'REC' THEN s.stat::INT END) AS rec,
            MAX(CASE WHEN s.category = 'receiving' AND s.stat_type = 'YDS' THEN s.stat::INT END) AS rec_yds,
            MAX(CASE WHEN s.category = 'receiving' AND s.stat_type = 'TD' THEN s.stat::INT END) AS rec_td,
            MAX(CASE WHEN s.category = 'defensive' AND s.stat_type = 'TOT' THEN s.stat::INT END) AS tackles,
            MAX(CASE WHEN s.category = 'defensive' AND s.stat_type = 'SOLO' THEN s.stat::INT END) AS solo,
            MAX(CASE WHEN s.category = 'defensive' AND s.stat_type = 'TFL' THEN s.stat::NUMERIC END) AS tfl,
            MAX(CASE WHEN s.category = 'defensive' AND s.stat_type = 'SACKS' THEN s.stat::NUMERIC END) AS sacks,
            MAX(CASE WHEN s.category = 'interceptions' AND s.stat_type = 'INT' THEN s.stat::INT END) AS interceptions,
            MAX(CASE WHEN s.category = 'defensive' AND s.stat_type = 'PD' THEN s.stat::INT END) AS pd,
            MAX(CASE WHEN s.category = 'kicking' AND s.stat_type = 'FGM' THEN s.stat::INT END) AS fg_made,
            MAX(CASE WHEN s.category = 'kicking' AND s.stat_type = 'FGA' THEN s.stat::INT END) AS fg_att,
            MAX(CASE WHEN s.category = 'kicking' AND s.stat_type = 'XPM' THEN s.stat::INT END) AS xp_made,
            MAX(CASE WHEN s.category = 'kicking' AND s.stat_type = 'XPA' THEN s.stat::INT END) AS xp_att,
            MAX(CASE WHEN s.category = 'kicking' AND s.stat_type = 'PTS' THEN s.stat::INT END) AS points
        FROM stats.player_season_stats s
        WHERE s.team = p_team AND s.season = p_season
        GROUP BY s.player_id, s.player, s.position
    )
    SELECT * FROM pivoted;
END;
$$;


--
-- Name: get_recruiting_class_history(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recruiting_class_history(p_team text) RETURNS TABLE(year integer, rank integer, points numeric, five_stars integer, four_stars integer, three_stars integer, two_stars integer, total_commits integer)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    tr.year::int,
    tr.rank::int,
    tr.points::numeric,
    COALESCE(SUM(CASE WHEN rl.stars = 5 THEN 1 ELSE 0 END), 0)::int AS five_stars,
    COALESCE(SUM(CASE WHEN rl.stars = 4 THEN 1 ELSE 0 END), 0)::int AS four_stars,
    COALESCE(SUM(CASE WHEN rl.stars = 3 THEN 1 ELSE 0 END), 0)::int AS three_stars,
    COALESCE(SUM(CASE WHEN rl.stars = 2 THEN 1 ELSE 0 END), 0)::int AS two_stars,
    COUNT(rl.id)::int AS total_commits
  FROM recruiting.team_recruiting tr
  LEFT JOIN api.recruit_lookup rl
    ON rl.committed_to = tr.team AND rl.year = tr.year
  WHERE tr.team = p_team
  GROUP BY tr.year, tr.rank, tr.points
  ORDER BY tr.year;
$$;


--
-- Name: get_recruiting_roi(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recruiting_roi(p_team text, p_season integer) RETURNS TABLE(season integer, avg_class_rank_4yr numeric, avg_class_points_4yr numeric, total_blue_chips_4yr integer, blue_chip_ratio numeric, wins integer, losses integer, win_pct numeric, sp_rating double precision, sp_rank integer, epa_per_play numeric, wins_over_expected numeric, epa_over_expected numeric, recruiting_efficiency numeric, win_pct_pctl double precision, epa_pctl double precision, recruiting_efficiency_pctl double precision)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    r.season::int,
    r.avg_class_rank_4yr,
    r.avg_class_points_4yr::numeric,
    r.total_blue_chips_4yr::int,
    r.blue_chip_ratio,
    r.wins,
    r.losses,
    r.win_pct,
    r.sp_rating,
    r.sp_rank::int,
    r.epa_per_play,
    r.wins_over_expected,
    r.epa_over_expected,
    r.recruiting_efficiency,
    r.win_pct_pctl,
    r.epa_pctl,
    r.recruiting_efficiency_pctl
  FROM api.recruiting_roi r
  WHERE r.team = p_team AND r.season = p_season;
$$;


--
-- Name: get_red_zone_splits(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_red_zone_splits(p_team text, p_season integer) RETURNS TABLE(side text, trips bigint, touchdowns bigint, field_goals bigint, turnovers bigint, td_rate numeric, fg_rate numeric, scoring_rate numeric, points_per_trip numeric, epa_per_play numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    -- Fixed 2026-07-23: the previous version filtered core.drives on
    -- start_yardline >= 80 -- the ABSOLUTE yardline column (direction-
    -- dependent, the only start_yardline reference in the repo) and a
    -- drive-START condition, when a red-zone trip is a drive that REACHES
    -- yards_to_goal <= 20. It undercounted both sides and reported ~0
    -- defensive TDs allowed. Trips are now play-derived (any snap at
    -- yards_to_goal <= 20), with outcomes taken from the drive row joined
    -- on (game_id, drive_number) -- verified against api.game_plays ground
    -- truth (Oklahoma 2025: offense 38 trips/26 TD, defense 32/13). The
    -- EPA sub-CTE had the same absolute-yardline bug (yardline >= 80) and
    -- now uses yards_to_goal <= 20. drive_result matching mirrors
    -- marts/006_scoring_opportunities.sql's casing-tolerant sets.
    WITH red_zone_trips AS (
        -- Garbage-time exclusion is intentionally NOT applied here:
        -- trips/scores are drive-level facts and stay unfiltered per the
        -- Phase 1 garbage-time centralization plan.
        SELECT DISTINCT
            CASE WHEN p.offense = p_team THEN 'offense' ELSE 'defense' END AS side,
            p.game_id,
            p.drive_number
        FROM core.plays p
        JOIN core.games g ON p.game_id = g.id
        -- p.season predicate enables partition pruning on core.plays
        -- (season-partitioned); g.season alone cannot prune.
        WHERE p.season = p_season
          AND g.season = p_season
          AND (p.offense = p_team OR p.defense = p_team)
          AND p.yards_to_goal <= 20
          AND p.drive_number IS NOT NULL
    ),
    red_zone_drives AS (
        SELECT
            t.side,
            t.game_id,
            t.drive_number,
            d.drive_result
        FROM red_zone_trips t
        -- LEFT JOIN: a trip observed in plays still counts even if its
        -- drive row is absent (it then contributes no outcome).
        LEFT JOIN core.drives d
          ON d.game_id = t.game_id AND d.drive_number = t.drive_number
    ),
    red_zone_plays AS (
        SELECT
            CASE WHEN p.offense = p_team THEN 'offense' ELSE 'defense' END AS side,
            p.ppa
        FROM core.plays p
        JOIN core.games g ON p.game_id = g.id
        WHERE p.season = p_season
          AND g.season = p_season
          AND (p.offense = p_team OR p.defense = p_team)
          AND p.yards_to_goal <= 20
          AND NOT public.is_garbage_time(p.period::integer, p.score_diff::integer)
    )
    SELECT
        rzd.side::TEXT,
        COUNT(*)::BIGINT AS trips,
        COUNT(*) FILTER (WHERE rzd.drive_result IN ('TD', 'Touchdown'))::BIGINT AS touchdowns,
        COUNT(*) FILTER (WHERE rzd.drive_result IN ('FG', 'Field Goal'))::BIGINT AS field_goals,
        COUNT(*) FILTER (WHERE rzd.drive_result IN ('INT', 'FUMBLE', 'INT TD', 'FUMBLE RETURN TD', 'Interception', 'Fumble', 'Fumble Lost', 'Interception Return'))::BIGINT AS turnovers,
        ROUND(COUNT(*) FILTER (WHERE rzd.drive_result IN ('TD', 'Touchdown'))::NUMERIC / NULLIF(COUNT(*), 0), 3) AS td_rate,
        ROUND(COUNT(*) FILTER (WHERE rzd.drive_result IN ('FG', 'Field Goal'))::NUMERIC / NULLIF(COUNT(*), 0), 3) AS fg_rate,
        ROUND(COUNT(*) FILTER (WHERE rzd.drive_result IN ('TD', 'FG', 'Touchdown', 'Field Goal'))::NUMERIC / NULLIF(COUNT(*), 0), 3) AS scoring_rate,
        ROUND((COUNT(*) FILTER (WHERE rzd.drive_result IN ('TD', 'Touchdown')) * 7 + COUNT(*) FILTER (WHERE rzd.drive_result IN ('FG', 'Field Goal')) * 3)::NUMERIC / NULLIF(COUNT(*), 0), 2) AS points_per_trip,
        ROUND((SELECT AVG(rzp.ppa) FROM red_zone_plays rzp WHERE rzp.side = rzd.side)::NUMERIC, 3) AS epa_per_play
    FROM red_zone_drives rzd
    GROUP BY rzd.side;
END;
$$;


--
-- Name: get_team_portal_activity(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_team_portal_activity(p_team text, p_season integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_object(
    'summary', (
      SELECT to_jsonb(sub) FROM (
        SELECT
          t.team::text,
          t.season::int,
          t.transfers_in,
          t.transfers_out,
          t.net_transfers,
          t.avg_incoming_stars,
          t.avg_incoming_rating,
          t.incoming_high_stars,
          t.win_delta,
          t.portal_dependency,
          t.net_transfers_pctl,
          t.win_delta_pctl,
          t.portal_dependency_pctl
        FROM api.transfer_portal_impact t
        WHERE t.team = p_team AND t.season = p_season
      ) sub
    ),
    'transfers_in', COALESCE((
      SELECT jsonb_agg(to_jsonb(sub) ORDER BY sub.transfer_date DESC)
      FROM (
        SELECT
          tp.season::int,
          tp.first_name::text,
          tp.last_name::text,
          tp.position::text,
          tp.origin::text,
          tp.destination::text,
          tp.transfer_date::text,
          tp.stars::int,
          tp.rating::numeric,
          tp.eligibility::text
        FROM recruiting.transfer_portal tp
        WHERE tp.destination = p_team AND tp.season = p_season
      ) sub
    ), '[]'::jsonb),
    'transfers_out', COALESCE((
      SELECT jsonb_agg(to_jsonb(sub) ORDER BY sub.transfer_date DESC)
      FROM (
        SELECT
          tp.season::int,
          tp.first_name::text,
          tp.last_name::text,
          tp.position::text,
          tp.origin::text,
          tp.destination::text,
          tp.transfer_date::text,
          tp.stars::int,
          tp.rating::numeric,
          tp.eligibility::text
        FROM recruiting.transfer_portal tp
        WHERE tp.origin = p_team AND tp.season = p_season
      ) sub
    ), '[]'::jsonb)
  );
$$;


--
-- Name: get_team_signees(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_team_signees(p_team text, p_year integer) RETURNS TABLE(ranking integer, name text, "position" text, stars integer, rating numeric, city text, state_province text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    rl.ranking::int,
    rl.name::text,
    rl.position::text,
    rl.stars::int,
    rl.rating::numeric,
    rl.city::text,
    rl.state_province::text
  FROM api.recruit_lookup rl
  WHERE rl.committed_to = p_team AND rl.year = p_year
  ORDER BY rl.ranking NULLS LAST;
