--
-- Name: get_trajectory_averages(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trajectory_averages(p_conference text, p_season_start integer DEFAULT 2020, p_season_end integer DEFAULT 2025) RETURNS TABLE(season bigint, conf_wins numeric, conf_win_pct numeric, conf_epa_per_play numeric, conf_success_rate numeric, conf_off_epa_rank numeric, conf_def_epa_rank numeric, conf_recruiting_rank numeric, fbs_wins numeric, fbs_win_pct numeric, fbs_epa_per_play numeric, fbs_success_rate numeric, fbs_off_epa_rank numeric, fbs_def_epa_rank numeric, fbs_recruiting_rank numeric)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        t.season,
        AVG(t.wins) FILTER (WHERE tm.conference = p_conference)::NUMERIC AS conf_wins,
        AVG(t.win_pct) FILTER (WHERE tm.conference = p_conference)::NUMERIC AS conf_win_pct,
        AVG(t.epa_per_play) FILTER (WHERE tm.conference = p_conference)::NUMERIC AS conf_epa_per_play,
        AVG(t.success_rate) FILTER (WHERE tm.conference = p_conference)::NUMERIC AS conf_success_rate,
        AVG(t.off_epa_rank) FILTER (WHERE tm.conference = p_conference)::NUMERIC AS conf_off_epa_rank,
        AVG(t.def_epa_rank) FILTER (WHERE tm.conference = p_conference)::NUMERIC AS conf_def_epa_rank,
        AVG(t.recruiting_rank) FILTER (WHERE tm.conference = p_conference)::NUMERIC AS conf_recruiting_rank,
        AVG(t.wins)::NUMERIC AS fbs_wins,
        AVG(t.win_pct)::NUMERIC AS fbs_win_pct,
        AVG(t.epa_per_play)::NUMERIC AS fbs_epa_per_play,
        AVG(t.success_rate)::NUMERIC AS fbs_success_rate,
        AVG(t.off_epa_rank)::NUMERIC AS fbs_off_epa_rank,
        AVG(t.def_epa_rank)::NUMERIC AS fbs_def_epa_rank,
        AVG(t.recruiting_rank)::NUMERIC AS fbs_recruiting_rank
    FROM public.team_season_trajectory t
    JOIN public.teams tm ON t.team = tm.school
    WHERE tm.classification = 'fbs'
      AND t.season BETWEEN p_season_start AND p_season_end
    GROUP BY t.season
    ORDER BY t.season;
END;
$$;


--
-- Name: is_garbage_time(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_garbage_time(period integer, score_diff integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
    RETURN (
        (period = 4 AND ABS(COALESCE(score_diff, 0)) > 28) OR
        (period >= 3 AND ABS(COALESCE(score_diff, 0)) > 35)
    );
END;
$$;


--
-- Name: FUNCTION is_garbage_time(period integer, score_diff integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_garbage_time(period integer, score_diff integer) IS 'Returns true if play occurred in garbage time (blowout situations where score diff > 28 in Q4 or > 35 in Q3+)';


--
-- Name: run_analyst_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_analyst_query(query_sql text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'api', 'public'
    AS $_$
DECLARE
    cleaned text := btrim(query_sql);
    result jsonb;
BEGIN
    -- Fail-fast checks; the analyst_ro grants are the real boundary.
    IF cleaned !~* '^(select|with)\M' THEN
        RAISE EXCEPTION 'only SELECT/WITH statements are allowed';
    END IF;
    cleaned := regexp_replace(cleaned, ';\s*$', '');
    IF position(';' IN cleaned) > 0 THEN
        RAISE EXCEPTION 'multiple statements are not allowed';
    END IF;

    SET LOCAL ROLE analyst_ro;
    SET LOCAL transaction_read_only = on;

    -- Hard row cap on an outer wrapper, so an inner LIMIT/OFFSET still
    -- parses; the smaller of the two limits wins.
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(q), ''[]''::jsonb) '
        'FROM (SELECT * FROM (%s) analyst_q LIMIT 200) q',
        cleaned
    ) INTO result;

    RETURN result;
END;
$_$;


--
-- Name: get_era(integer); Type: FUNCTION; Schema: ref; Owner: -
--

CREATE FUNCTION ref.get_era(p_year integer) RETURNS TABLE(era_code character varying, era_name character varying)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
BEGIN
    RETURN QUERY
    SELECT e.era_code, e.era_name
    FROM ref.eras e
    WHERE p_year >= e.start_year
      AND (e.end_year IS NULL OR p_year <= e.end_year);
END;
$$;


--
-- Name: refresh_fct_player_movements(); Type: FUNCTION; Schema: rp; Owner: -
--

CREATE FUNCTION rp.refresh_fct_player_movements() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  TRUNCATE rp.fct_player_movements;
  TRUNCATE rp.unmatched_portal_log;

  INSERT INTO rp.fct_player_movements (
    player_id, transition_season, movement_type,
    source_team, source_conference, destination_team, destination_conference,
    match_confidence, match_method,
    source_first_name, source_last_name, source_url, source_date
  )
  WITH
  -- Team -> conference + classification lookup. ref.teams has duplicate `school`
  -- rows (memory 2026-02-05); DISTINCT ON dedupes, preferring populated classification.
  team_meta AS (
    SELECT DISTINCT ON (school)
      school AS team,
      conference,
      classification
    FROM ref.teams
    ORDER BY school, classification NULLS LAST, conference NULLS LAST
  ),
  -- HC for (team, season): expand each coaching_tenure span via generate_series so
  -- the join becomes a simple equality match. tenure_end IS NULL means active --
  -- treat as ongoing through 2026 (the upper bound of our scope).
  hc_lookup AS (
    SELECT
      ct.team,
      gs::int AS season,
      ct.coach_name AS hc
    FROM marts.coaching_tenure ct,
         LATERAL generate_series(
           ct.tenure_start::int,
           COALESCE(ct.tenure_end, 2026)::int
         ) AS gs
    WHERE COALESCE(ct.tenure_end, 2026) >= 2020
  ),
  -- Returners: same player, same team, consecutive seasons. HC change drives
  -- the 2-tier continuity (returning_same_hc / returning_new_hc).
  returners AS (
    SELECT
      curr.player_id,
      curr.season AS transition_season,
      prior.team AS source_team,
      prior.conference AS source_conference,
      curr.team AS destination_team,
      curr.conference AS destination_conference,
      CASE
        -- IS NOT DISTINCT FROM treats NULL=NULL as match (defensive default
        -- when coaching_tenure is missing for either side)
        WHEN hc_curr.hc IS NOT DISTINCT FROM hc_prior.hc THEN 'returning_same_hc'
        ELSE 'returning_new_hc'
      END AS movement_type,
      1.00::numeric(3,2) AS match_confidence,
      'roster_continuity'::varchar AS match_method,
      NULL::varchar AS source_first_name,
      NULL::varchar AS source_last_name,
      NULL::varchar AS source_url,
      NULL::date AS source_date
    FROM rp.fct_player_seasons curr
    JOIN rp.fct_player_seasons prior
      ON prior.player_id = curr.player_id
      AND prior.season = curr.season - 1
      AND prior.team = curr.team
    LEFT JOIN hc_lookup hc_curr
      ON hc_curr.team = curr.team AND hc_curr.season = curr.season
    LEFT JOIN hc_lookup hc_prior
      ON hc_prior.team = prior.team AND hc_prior.season = prior.season
    WHERE curr.season BETWEEN 2021 AND 2026
  ),
  -- Portal exact-match: case-insensitive (first_name, last_name) + origin team
  -- + prior season's roster row. DISTINCT ON dedupes ambiguous matches
  -- (same name on roster, rare) by smallest roster.id.
  portal_exact AS (
    SELECT DISTINCT ON (p.first_name, p.last_name, p.origin, p.season)
      p.first_name, p.last_name,
      p.origin, p.destination,
      p.season::int AS transition_season,
      p.stars, p.rating, p.position, p.transfer_date::date AS transfer_date,
      r.id::text AS player_id
    FROM recruiting.transfer_portal p
    JOIN core.roster r
      ON lower(r.first_name) = lower(p.first_name)
      AND lower(r.last_name) = lower(p.last_name)
      AND r.team = p.origin
      AND r.year = p.season - 1
    WHERE p.season BETWEEN 2021 AND 2026
    ORDER BY p.first_name, p.last_name, p.origin, p.season, r.id
  ),
  -- Portal fuzzy-match: levenshtein(full_name) <= 2 against same (origin, prior year).
  -- Excludes entries already matched exactly. fuzzystrmatch.levenshtein is in public schema.
  portal_fuzzy AS (
    SELECT DISTINCT ON (p.first_name, p.last_name, p.origin, p.season)
      p.first_name, p.last_name,
      p.origin, p.destination,
      p.season::int AS transition_season,
      p.stars, p.rating, p.position, p.transfer_date::date AS transfer_date,
      r.id::text AS player_id
    FROM recruiting.transfer_portal p
    JOIN core.roster r
      ON r.team = p.origin
      AND r.year = p.season - 1
      -- levenshtein_less_equal short-circuits at distance > max, bounding the
      -- O(m*n) scan against pathological CFBD payloads.
      AND public.levenshtein_less_equal(
        lower(coalesce(p.first_name, '') || coalesce(p.last_name, '')),
        lower(coalesce(r.first_name, '') || coalesce(r.last_name, '')),
        2
      ) <= 2
    WHERE p.season BETWEEN 2021 AND 2026
      AND NOT EXISTS (
        SELECT 1 FROM portal_exact pe
        WHERE pe.first_name = p.first_name
          AND pe.last_name = p.last_name
          AND pe.origin = p.origin
          AND pe.transition_season = p.season::int
      )
    ORDER BY p.first_name, p.last_name, p.origin, p.season,
      public.levenshtein_less_equal(
        lower(coalesce(p.first_name, '') || coalesce(p.last_name, '')),
        lower(coalesce(r.first_name, '') || coalesce(r.last_name, '')),
        2
      ),
      r.id
  ),
  -- Portal unmatched: synthetic player_id derived from md5 of all available
  -- distinguishing fields. Including destination + transfer_date avoids collision
  -- when (first, last, origin, season) collapse to a single bucket -- e.g. two
  -- NULL-name CFBD rows in the same season, or two same-name players from the
  -- same school going to different destinations. Stable across reruns; logged
  -- separately in unmatched_portal_log for audit.
  portal_unmatched AS (
    SELECT
      p.first_name, p.last_name,
      p.origin, p.destination,
      p.season::int AS transition_season,
      p.stars, p.rating, p.position, p.transfer_date::date AS transfer_date,
      'portal:' || md5(
        coalesce(p.first_name, '')   || '|' ||
        coalesce(p.last_name, '')    || '|' ||
        coalesce(p.origin, '')       || '|' ||
        coalesce(p.destination, '')  || '|' ||
        coalesce(p.transfer_date::text, '') || '|' ||
        p.season::text
      ) AS player_id
    FROM recruiting.transfer_portal p
    WHERE p.season BETWEEN 2021 AND 2026
      AND NOT EXISTS (
        SELECT 1 FROM portal_exact pe
        WHERE pe.first_name = p.first_name AND pe.last_name = p.last_name
          AND pe.origin = p.origin AND pe.transition_season = p.season::int
      )
      AND NOT EXISTS (
        SELECT 1 FROM portal_fuzzy pf
        WHERE pf.first_name = p.first_name AND pf.last_name = p.last_name
          AND pf.origin = p.origin AND pf.transition_season = p.season::int
      )
  ),
  -- Combined portal entries with conference/classification lookups for movement_type
  portal_combined AS (
    SELECT *, 1.00::numeric(3,2) AS match_confidence, 'portal_exact'::varchar AS match_method FROM portal_exact
    UNION ALL
    SELECT *, 0.80::numeric(3,2), 'portal_fuzzy'::varchar FROM portal_fuzzy
    UNION ALL
    SELECT *, 0.00::numeric(3,2), 'unmatched'::varchar FROM portal_unmatched
  ),
  portal_classified AS (
    SELECT
      pc.player_id,
      pc.transition_season,
      pc.first_name AS source_first_name,
      pc.last_name AS source_last_name,
      pc.origin AS source_team,
      src.conference AS source_conference,
      pc.destination AS destination_team,
      dst.conference AS destination_conference,
      pc.match_confidence,
      pc.match_method,
      NULL::varchar AS source_url,
      pc.transfer_date AS source_date,
      CASE
        -- FCS or non-NCAA-D1 origin -> FBS dest: portal_fcs_to_fbs (translation discount)
        WHEN COALESCE(src.classification, 'unknown') IN ('fcs', 'ii', 'iii', 'unknown')
             AND dst.classification = 'fbs'
          THEN 'portal_fcs_to_fbs'
        -- Both FBS: classify by P5/G5 of source and destination conferences
        WHEN src.classification = 'fbs' AND dst.classification = 'fbs' THEN
          CASE
            WHEN src.conference IN ('SEC', 'Big Ten', 'ACC', 'Big 12', 'Pac-12')
              AND dst.conference IN ('SEC', 'Big Ten', 'ACC', 'Big 12', 'Pac-12')
              THEN 'portal_p5_to_p5'
            WHEN src.conference IN ('SEC', 'Big Ten', 'ACC', 'Big 12', 'Pac-12')
              THEN 'portal_p5_to_g5'
            WHEN dst.conference IN ('SEC', 'Big Ten', 'ACC', 'Big 12', 'Pac-12')
              THEN 'portal_g5_to_p5'
            ELSE 'portal_g5_to_g5'
          END
        -- FBS -> non-FBS or both non-FBS: bucket as portal_g5_to_g5 (low-fidelity catchall)
        ELSE 'portal_g5_to_g5'
      END AS movement_type
    FROM portal_combined pc
    LEFT JOIN team_meta src ON src.team = pc.origin
    LEFT JOIN team_meta dst ON dst.team = pc.destination
  ),
  -- Recruits: dedupe on (athlete_id, year). Reclassifiers can have multiple rows;
  -- prefer highest stars per athlete-year tuple.
  recruits_dedup AS (
    SELECT DISTINCT ON (athlete_id, year)
      athlete_id::text AS player_id,
      year::int AS transition_season,
      committed_to AS destination_team,
      stars,
      name
    FROM recruiting.recruits
    WHERE year BETWEEN 2021 AND 2026
      AND athlete_id IS NOT NULL
      AND committed_to IS NOT NULL
    ORDER BY athlete_id, year, stars DESC NULLS LAST
  ),
  recruits AS (
    SELECT
      rd.player_id,
      rd.transition_season,
      NULL::varchar AS source_team,
      NULL::varchar AS source_conference,
      rd.destination_team,
      tm.conference AS destination_conference,
      CASE
        WHEN rd.stars >= 5 THEN 'recruit_5star'
        WHEN rd.stars = 4 THEN 'recruit_4star'
        WHEN rd.stars = 3 THEN 'recruit_3star'
        ELSE 'recruit_unrated'
      END AS movement_type,
      1.00::numeric(3,2) AS match_confidence,
      'recruit'::varchar AS match_method,
      -- Recruits store full name in 'name'; split is best-effort
      split_part(rd.name, ' ', 1) AS source_first_name,
      NULLIF(regexp_replace(rd.name, '^\S+\s+', ''), rd.name) AS source_last_name,
      NULL::varchar AS source_url,
      NULL::date AS source_date
    FROM recruits_dedup rd
    LEFT JOIN team_meta tm ON tm.team = rd.destination_team
  ),
  -- Combine all three sources with a priority ranking. PK is (player_id, transition_season);
  -- if a player_id appears in multiple sources for the same transition (rare but possible
  -- e.g., portal-matched player who's also in returners due to multi-team season quirk),
  -- prefer portal > returner > recruit. Lower priority value = higher precedence.
  all_movements AS (
    SELECT
      player_id, transition_season, movement_type,
      source_team, source_conference, destination_team, destination_conference,
      match_confidence, match_method,
      source_first_name, source_last_name, source_url, source_date,
      1 AS priority
    FROM portal_classified
    UNION ALL
    SELECT
      player_id, transition_season, movement_type,
      source_team, source_conference, destination_team, destination_conference,
      match_confidence, match_method,
      source_first_name, source_last_name, source_url, source_date,
      2 AS priority
    FROM returners
    UNION ALL
    SELECT
      player_id, transition_season, movement_type,
      source_team, source_conference, destination_team, destination_conference,
      match_confidence, match_method,
      source_first_name, source_last_name, source_url, source_date,
      3 AS priority
    FROM recruits
  )
  SELECT DISTINCT ON (player_id, transition_season)
    player_id, transition_season, movement_type,
    source_team, source_conference, destination_team, destination_conference,
    match_confidence, match_method,
    source_first_name, source_last_name, source_url, source_date
  FROM all_movements
  ORDER BY player_id, transition_season, priority;

  -- Audit log: every portal entry that did not exact- or fuzzy-match a prior-season
  -- roster row. The match conditions duplicate the portal_unmatched CTE above; if
  -- the levenshtein threshold or join keys change, update both in lockstep.
  INSERT INTO rp.unmatched_portal_log (
    transition_season, first_name, last_name, origin, destination,
    stars, rating, position, transfer_date, reason
  )
  SELECT
    p.season::int AS transition_season,
    p.first_name, p.last_name, p.origin, p.destination,
    p.stars::int, p.rating::numeric(5,4),
    p.position, p.transfer_date::date,
    CASE
      WHEN NOT EXISTS (
        SELECT 1 FROM core.roster r
        WHERE r.team = p.origin AND r.year = p.season - 1
      ) THEN 'no_roster_for_origin_season'
      ELSE 'no_name_match'
    END AS reason
  FROM recruiting.transfer_portal p
  WHERE p.season BETWEEN 2021 AND 2026
    AND NOT EXISTS (
      SELECT 1 FROM core.roster r
      WHERE lower(r.first_name) = lower(p.first_name)
        AND lower(r.last_name) = lower(p.last_name)
        AND r.team = p.origin
        AND r.year = p.season - 1
    )
    AND NOT EXISTS (
      SELECT 1 FROM core.roster r
      WHERE r.team = p.origin
        AND r.year = p.season - 1
        AND public.levenshtein_less_equal(
          lower(coalesce(p.first_name, '') || coalesce(p.last_name, '')),
          lower(coalesce(r.first_name, '') || coalesce(r.last_name, '')),
          2
        ) <= 2
    );

  ANALYZE rp.fct_player_movements;
  ANALYZE rp.unmatched_portal_log;
END;
$$;


--
-- Name: FUNCTION refresh_fct_player_movements(); Type: COMMENT; Schema: rp; Owner: -
--

COMMENT ON FUNCTION rp.refresh_fct_player_movements() IS 'U3 loader. Populates rp.fct_player_movements with three movement sources: roster continuity (returners), portal events (3-tier name match), recruit class. Idempotent (TRUNCATE + INSERT). Also writes audit rows for unmatched portal entries to rp.unmatched_portal_log.';


--
-- Name: refresh_fct_player_seasons(); Type: FUNCTION; Schema: rp; Owner: -
--

CREATE FUNCTION rp.refresh_fct_player_seasons() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
  TRUNCATE rp.fct_player_seasons;

  INSERT INTO rp.fct_player_seasons (
    player_id, season, team, conference,
    position_detail, position, position_group,
    class, height_in, weight_lb,
    games_played, games_started, snaps_estimated,
    stat_pass_attempts, stat_pass_yards, stat_pass_tds, stat_pass_ints,
    stat_rush_attempts, stat_rush_yards, stat_rush_tds,
    stat_rec_targets, stat_rec_catches, stat_rec_yards, stat_rec_tds,
    stat_tackles_solo, stat_tackles_ast,
    stat_tfl, stat_sacks, stat_int, stat_pbu, stat_ff, stat_fr,
    recruiting_composite, recruiting_stars
  )
  WITH
  -- Pivot stats from long format (category, stat_type, stat) into wide-per-season.
  -- SUM aggregates across teams when a player switched mid-season (RP-002 -- stats follow
  -- the player; team attribution is handled separately via roster_dedup below).
  -- The `stat` column is VARCHAR; regex-guard the cast to handle any future non-numeric values.
  pivoted_stats AS (
    SELECT
      ps.player_id,
      ps.season::int                                                   AS season,
      MAX(ps.conference)                                               AS conference,
      SUM(CASE WHEN ps.category = 'passing'   AND ps.stat_type = 'ATT'         AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_pass_attempts,
      SUM(CASE WHEN ps.category = 'passing'   AND ps.stat_type = 'YDS'         AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_pass_yards,
      SUM(CASE WHEN ps.category = 'passing'   AND ps.stat_type = 'TD'          AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_pass_tds,
      SUM(CASE WHEN ps.category = 'passing'   AND ps.stat_type = 'INT'         AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_pass_ints,
      SUM(CASE WHEN ps.category = 'rushing'   AND ps.stat_type = 'CAR'         AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_rush_attempts,
      SUM(CASE WHEN ps.category = 'rushing'   AND ps.stat_type = 'YDS'         AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_rush_yards,
      SUM(CASE WHEN ps.category = 'rushing'   AND ps.stat_type = 'TD'          AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_rush_tds,
      SUM(CASE WHEN ps.category = 'receiving' AND ps.stat_type = 'REC'         AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_rec_catches,
      SUM(CASE WHEN ps.category = 'receiving' AND ps.stat_type = 'YDS'         AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_rec_yards,
      SUM(CASE WHEN ps.category = 'receiving' AND ps.stat_type = 'TD'          AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_rec_tds,
      SUM(CASE WHEN ps.category = 'defensive' AND ps.stat_type = 'SOLO'        AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int AS stat_tackles_solo,
      -- AST = TOT - SOLO (CFBD reports total tackles, solo tackles; assists is the difference)
      SUM(
        CASE WHEN ps.category = 'defensive' AND ps.stat_type = 'TOT'  AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END
        - CASE WHEN ps.category = 'defensive' AND ps.stat_type = 'SOLO' AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END
      )::int                                                                                                                                              AS stat_tackles_ast,
      SUM(CASE WHEN ps.category = 'defensive'     AND ps.stat_type = 'TFL'   AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::numeric(5,1) AS stat_tfl,
      SUM(CASE WHEN ps.category = 'defensive'     AND ps.stat_type = 'SACKS' AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::numeric(5,1) AS stat_sacks,
      SUM(CASE WHEN ps.category = 'interceptions' AND ps.stat_type = 'INT'   AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int          AS stat_int,
      SUM(CASE WHEN ps.category = 'defensive'     AND ps.stat_type = 'PD'    AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int          AS stat_pbu,
      SUM(CASE WHEN ps.category = 'fumbles'       AND ps.stat_type = 'REC'   AND ps.stat ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ps.stat::numeric ELSE 0 END)::int          AS stat_fr
    FROM stats.player_season_stats ps
    WHERE ps.season BETWEEN 2020 AND 2026
    GROUP BY ps.player_id, ps.season
  ),
  -- Dedupe roster to one row per (player_id, season). For mid-season transfers, pick the
  -- alphabetically-last team -- deterministic and matches RP-002's "attribute to last team"
  -- in absence of within-season ordering. Stats are aggregated across teams above.
  roster_dedup AS (
    SELECT DISTINCT ON (r.id, r.year)
      r.id, r.year, r.team, r.position, r.height, r.weight,
      r.first_name, r.last_name
    FROM core.roster r
    WHERE r.id IS NOT NULL
      AND r.year BETWEEN 2020 AND 2026
    ORDER BY r.id, r.year, r.team DESC
  ),
  -- Recruits can have multiple rows per athlete_id (reclassifiers per memory 2026-02-05).
  -- Keep the latest record by year so we have one composite/stars value per player.
  recruits_dedup AS (
    SELECT DISTINCT ON (rec.athlete_id)
      rec.athlete_id, rec.stars, rec.rating
    FROM recruiting.recruits rec
    WHERE rec.athlete_id IS NOT NULL
    ORDER BY rec.athlete_id, rec.year DESC
  )
  SELECT
    r.id::text                                               AS player_id,
    r.year::int                                              AS season,
    r.team,
    ps.conference,
    r.position                                               AS position_detail,
    -- 11-canonical position (per requirements doc data contract)
    CASE
      WHEN r.position = 'QB'                              THEN 'QB'
      WHEN r.position IN ('RB', 'FB')                     THEN 'RB'
      WHEN r.position = 'WR'                              THEN 'WR'
      WHEN r.position = 'TE'                              THEN 'TE'
      WHEN r.position IN ('OL', 'OT', 'G', 'OG', 'C')     THEN 'OL'
      WHEN r.position IN ('DE', 'EDGE')                   THEN 'EDGE'
      WHEN r.position IN ('DT', 'NT', 'DL')               THEN 'DT'
      WHEN r.position IN ('LB', 'OLB', 'ILB')             THEN 'LB'
      WHEN r.position = 'CB'                              THEN 'CB'
      WHEN r.position IN ('S', 'FS', 'SS', 'DB')          THEN 'S'
      WHEN r.position IN ('PK', 'K', 'P', 'LS', 'KR', 'PR') THEN 'ST'
      ELSE 'ST'  -- ATH, '?', NULL, anything else -- bucketed to ST (weight 0 in dim_position_weights)
    END                                                      AS position,
    -- 8-group rollup (per plan U2 -- drives base_production formulas in U10)
    CASE
      WHEN r.position = 'QB'                                                THEN 'QB'
      WHEN r.position IN ('RB', 'FB')                                       THEN 'RB'
      WHEN r.position IN ('WR', 'TE')                                       THEN 'WR_TE'
      WHEN r.position IN ('OL', 'OT', 'G', 'OG', 'C')                       THEN 'OL'
      WHEN r.position IN ('DE', 'EDGE', 'DT', 'NT', 'DL')                   THEN 'DL'
      WHEN r.position IN ('LB', 'OLB', 'ILB')                               THEN 'LB'
      WHEN r.position IN ('CB', 'S', 'FS', 'SS', 'DB')                      THEN 'DB'
      ELSE 'ST'  -- PK, K, P, LS, KR, PR, ATH, '?', NULL
    END                                                      AS position_group,
    NULL::varchar                                            AS class,           -- not in CFBD roster; deferred
    r.height::int                                            AS height_in,
    r.weight::int                                            AS weight_lb,
    NULL::int                                                AS games_played,    -- not in CFBD roster; U10 may derive
    NULL::int                                                AS games_started,   -- not in CFBD roster; U10 may derive
    NULL::int                                                AS snaps_estimated, -- CFBD has no reliable snap data
    ps.stat_pass_attempts,
    ps.stat_pass_yards,
    ps.stat_pass_tds,
    ps.stat_pass_ints,
    ps.stat_rush_attempts,
    ps.stat_rush_yards,
    ps.stat_rush_tds,
    NULL::int                                                AS stat_rec_targets, -- CFBD does not return targets; deferred
    ps.stat_rec_catches,
    ps.stat_rec_yards,
    ps.stat_rec_tds,
    ps.stat_tackles_solo,
    ps.stat_tackles_ast,
    ps.stat_tfl,
    ps.stat_sacks,
    ps.stat_int,
    ps.stat_pbu,
    NULL::int                                                AS stat_ff,        -- not in CFBD player_season_stats fumbles category
    ps.stat_fr,
    rd.rating::numeric(5,4)                                  AS recruiting_composite,
    rd.stars::int                                            AS recruiting_stars
  FROM roster_dedup r
  LEFT JOIN pivoted_stats ps
    ON  ps.player_id = r.id::text
    AND ps.season    = r.year::int
  LEFT JOIN recruits_dedup rd
    ON rd.athlete_id = r.id::text
  WHERE r.year BETWEEN 2020 AND 2026;

  -- Refresh planner stats for downstream U3/U5 joins
  ANALYZE rp.fct_player_seasons;
END;
$_$;


--
-- Name: FUNCTION refresh_fct_player_seasons(); Type: COMMENT; Schema: rp; Owner: -
--

COMMENT ON FUNCTION rp.refresh_fct_player_seasons() IS 'U2 loader. Populates rp.fct_player_seasons for seasons 2020-2026 from core.roster + stats.player_season_stats + recruiting.recruits. Idempotent (TRUNCATE + INSERT). Multi-team-season players: stats SUM-aggregated across teams; team attribution is alphabetically-last per RP-002.';


--
-- Name: fn_evaluate_portal_value(); Type: FUNCTION; Schema: scouting; Owner: -
--

CREATE FUNCTION scouting.fn_evaluate_portal_value() RETURNS TABLE(player_id integer, player_name text, value_score numeric, alert_fired boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    entry record;
    v_score decimal;
    v_alert_id int;
    v_history_id int;
    v_threshold decimal := 80.0;
BEGIN
    -- Iterate through portal entries in the last 24h -- one row per transfer
    -- event (not per player), so a re-entry keeps its own identity/context.
    FOR entry IN
        SELECT p.id, p.name, p.composite_grade, te.from_team,
               te.id AS transfer_event_id
        FROM scouting.players p
        JOIN scouting.transfer_events te ON p.id = te.player_id
        WHERE te.event_type = 'entered'
          AND te.created_at >= now() - interval '24 hours'
    LOOP
        -- Score: (composite grade * 50%) + (PFF grade * 50%).
        -- week DESC NULLS FIRST is intentional: a NULL-week pff_grades row is the
        -- season-aggregate grade, preferred over any mid-season weekly grade;
        -- weekly rows are the fallback when no season row exists.
        SELECT
            round(
                (coalesce(entry.composite_grade, 0) * 0.5) +
                (coalesce(
                    (SELECT overall_grade
                     FROM scouting.pff_grades
                     WHERE pff_grades.player_id = entry.id
                     ORDER BY season DESC, week DESC NULLS FIRST LIMIT 1
                    ), 0) * 0.5),
            1) INTO v_score;

        IF v_score >= v_threshold THEN
            INSERT INTO scouting.alerts (user_id, name, alert_type, player_id, threshold)
            VALUES ('system', 'portal-value-' || entry.id, 'portal_entry', entry.id,
                    jsonb_build_object('min_score', v_threshold))
            ON CONFLICT (user_id, name) DO UPDATE SET last_checked_at = now()
            RETURNING id INTO v_alert_id;

            -- Idempotency, keyed on the transfer event itself and enforced by
            -- idx_alert_history_alert_event: a retry or CONCURRENT invocation
            -- never double-fires (the conflict makes the insert a no-op), while
            -- a genuinely new portal entry by the same player (enter ->
            -- withdraw -> re-enter) still fires with its own from_team context
            -- (PR #68 review). v_history_id is NULL when the insert was a
            -- conflict no-op, so only the winning invocation reports the fire.
            INSERT INTO scouting.alert_history (alert_id, trigger_data, message)
            VALUES (
                v_alert_id,
                jsonb_build_object(
                    'transfer_event_id', entry.transfer_event_id,
                    'score', v_score,
                    'composite', entry.composite_grade,
                    'from_team', entry.from_team
                ),
                'High-value portal entrant: ' || entry.name || ' (Score: ' || v_score || ')'
            )
            ON CONFLICT (alert_id, ((trigger_data->>'transfer_event_id')::int)) DO NOTHING
            RETURNING id INTO v_history_id;

            IF v_history_id IS NOT NULL THEN
                player_id := entry.id;
                player_name := entry.name;
                value_score := v_score;
                alert_fired := true;
                RETURN NEXT;
            END IF;
        END IF;
    END LOOP;
END;
$$;


--
-- Name: FUNCTION fn_evaluate_portal_value(); Type: COMMENT; Schema: scouting; Owner: -
--

COMMENT ON FUNCTION scouting.fn_evaluate_portal_value() IS 'Automated scouter that identifies high-value portal entrants and fires system alerts.';


--
-- Name: refresh_player_mart(); Type: FUNCTION; Schema: scouting; Owner: -
--

CREATE FUNCTION scouting.refresh_player_mart() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY scouting.player_mart;
END;
$$;


--
-- Name: FUNCTION refresh_player_mart(); Type: COMMENT; Schema: scouting; Owner: -
--

COMMENT ON FUNCTION scouting.refresh_player_mart() IS 'Refreshes player_mart materialized view. Uses CONCURRENTLY to avoid locking reads.';


SET LOCAL default_tablespace = '';

SET LOCAL default_table_access_method = heap;

--
-- Name: adjusted_epa_build; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.adjusted_epa_build (
    team character varying NOT NULL,
    season bigint NOT NULL,
    off_coef numeric(8,5),
    def_coef numeric(8,5),
    hfa_coef numeric(8,5),
    mu numeric(8,5),
    plays bigint,
    lambda numeric(8,1),
    n_teams bigint
);


--
-- Name: TABLE adjusted_epa_build; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON TABLE analytics.adjusted_epa_build IS 'Ridge-regressed opponent-adjusted EPA per (team, season). Sign convention: off_coef higher = better offense; def_coef LOWER/more negative = better defense (EPA allowed above average). lambda is the ridge penalty recorded per row for auditability across tunable-ledger changes.';


--
-- Name: adjusted_epa_week_build; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.adjusted_epa_week_build (
    team character varying NOT NULL,
    season bigint NOT NULL,
    week_index integer NOT NULL,
    off_coef numeric(8,5),
    def_coef numeric(8,5),
    hfa_coef numeric(8,5),
    mu numeric(8,5),
    plays bigint,
    lambda numeric(8,1),
    n_teams bigint
);


--
-- Name: TABLE adjusted_epa_week_build; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON TABLE analytics.adjusted_epa_week_build IS 'Walk-forward ridge-regressed opponent-adjusted EPA per (team, season, week_index): coefficients ENTERING that week, fit on plays with week_index < WI only (week_index = week for regular season, 100 + week for postseason) (as-of rating, no leakage of week W or later). Sign convention: off_coef higher = better offense; def_coef LOWER/more negative = better defense (EPA allowed above average). lambda is the ridge penalty recorded per row for auditability across tunable-ledger changes.';


