--
-- Name: team_season_summary; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.team_season_summary AS
 WITH home_games AS (
         SELECT games.season,
            games.home_team AS team,
            games.home_conference AS conference,
            games.home_points AS points_for,
            games.away_points AS points_against,
                CASE
                    WHEN (games.home_points > games.away_points) THEN 1
                    ELSE 0
                END AS win,
                CASE
                    WHEN (games.home_points < games.away_points) THEN 1
                    ELSE 0
                END AS loss,
            1 AS home_game,
            0 AS away_game,
                CASE
                    WHEN ((games.home_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text)) THEN 1
                    ELSE 0
                END AS is_conference_game,
                CASE
                    WHEN ((games.home_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.home_points > games.away_points)) THEN 1
                    ELSE 0
                END AS conf_win,
                CASE
                    WHEN ((games.home_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.home_points < games.away_points)) THEN 1
                    ELSE 0
                END AS conf_loss,
            games.excitement_index
           FROM core.games
          WHERE (games.completed = true)
        ), away_games AS (
         SELECT games.season,
            games.away_team AS team,
            games.away_conference AS conference,
            games.away_points AS points_for,
            games.home_points AS points_against,
                CASE
                    WHEN (games.away_points > games.home_points) THEN 1
                    ELSE 0
                END AS win,
                CASE
                    WHEN (games.away_points < games.home_points) THEN 1
                    ELSE 0
                END AS loss,
            0 AS home_game,
            1 AS away_game,
                CASE
                    WHEN ((games.away_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text)) THEN 1
                    ELSE 0
                END AS is_conference_game,
                CASE
                    WHEN ((games.away_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.away_points > games.home_points)) THEN 1
                    ELSE 0
                END AS conf_win,
                CASE
                    WHEN ((games.away_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.away_points < games.home_points)) THEN 1
                    ELSE 0
                END AS conf_loss,
            games.excitement_index
           FROM core.games
          WHERE (games.completed = true)
        ), all_games AS (
         SELECT home_games.season,
            home_games.team,
            home_games.conference,
            home_games.points_for,
            home_games.points_against,
            home_games.win,
            home_games.loss,
            home_games.home_game,
            home_games.away_game,
            home_games.is_conference_game,
            home_games.conf_win,
            home_games.conf_loss,
            home_games.excitement_index
           FROM home_games
        UNION ALL
         SELECT away_games.season,
            away_games.team,
            away_games.conference,
            away_games.points_for,
            away_games.points_against,
            away_games.win,
            away_games.loss,
            away_games.home_game,
            away_games.away_game,
            away_games.is_conference_game,
            away_games.conf_win,
            away_games.conf_loss,
            away_games.excitement_index
           FROM away_games
        )
 SELECT season,
    team,
    max((conference)::text) AS conference,
    (sum(win))::integer AS wins,
    (sum(loss))::integer AS losses,
    (count(*))::integer AS total_games,
    (sum(points_for))::integer AS points_for,
    (sum(points_against))::integer AS points_against,
    ((sum(points_for) - sum(points_against)))::integer AS point_margin,
    (sum(
        CASE
            WHEN (home_game = 1) THEN win
            ELSE 0
        END))::integer AS home_wins,
    (sum(
        CASE
            WHEN (home_game = 1) THEN loss
            ELSE 0
        END))::integer AS home_losses,
    (sum(
        CASE
            WHEN (away_game = 1) THEN win
            ELSE 0
        END))::integer AS away_wins,
    (sum(
        CASE
            WHEN (away_game = 1) THEN loss
            ELSE 0
        END))::integer AS away_losses,
    (sum(conf_win))::integer AS conference_wins,
    (sum(conf_loss))::integer AS conference_losses,
    round((avg(excitement_index))::numeric, 4) AS avg_excitement_index
   FROM all_games
  GROUP BY season, team
  WITH NO DATA;


