--
-- Name: conference_standings; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.conference_standings AS
 SELECT tss.season,
    tss.conference,
    tss.team,
    tss.conference_wins AS conf_wins,
    tss.conference_losses AS conf_losses,
    tss.wins AS overall_wins,
    tss.losses AS overall_losses,
    round(((tss.conference_wins)::numeric / (NULLIF((tss.conference_wins + tss.conference_losses), 0))::numeric), 4) AS conf_win_pct,
    sp.rating AS sp_rating,
    elo.elo AS elo_rating,
    tr.rank AS recruiting_rank
   FROM (((analytics.team_season_summary tss
     LEFT JOIN ratings.sp_ratings sp ON (((sp.year = tss.season) AND ((sp.team)::text = (tss.team)::text))))
     LEFT JOIN ratings.elo_ratings elo ON (((elo.year = tss.season) AND ((elo.team)::text = (tss.team)::text))))
     LEFT JOIN recruiting.team_recruiting tr ON (((tr.year = tss.season) AND ((tr.team)::text = (tss.team)::text))))
  WHERE (tss.conference IS NOT NULL)
  WITH NO DATA;


