--
-- Name: data_quality_dashboard; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.data_quality_dashboard AS
 WITH coverage AS (
         SELECT 'games'::text AS metric,
            (min(games.season))::integer AS min_year,
            (max(games.season))::integer AS max_year,
            count(*) AS row_count
           FROM core.games
        UNION ALL
         SELECT 'plays'::text AS text,
            min(plays.season) AS min,
            max(plays.season) AS max,
            count(*) AS count
           FROM core.plays
        UNION ALL
         SELECT 'drives'::text AS text,
            min(drives.season) AS min,
            max(drives.season) AS max,
            count(*) AS count
           FROM core.drives
        UNION ALL
         SELECT 'team_season_stats'::text AS text,
            min(team_season_stats.season) AS min,
            max(team_season_stats.season) AS max,
            count(*) AS count
           FROM stats.team_season_stats
        UNION ALL
         SELECT 'player_season_stats'::text AS text,
            min(player_season_stats.season) AS min,
            max(player_season_stats.season) AS max,
            count(*) AS count
           FROM stats.player_season_stats
        UNION ALL
         SELECT 'sp_ratings'::text AS text,
            min(sp_ratings.year) AS min,
            max(sp_ratings.year) AS max,
            count(*) AS count
           FROM ratings.sp_ratings
        UNION ALL
         SELECT 'recruits'::text AS text,
            min(recruits.year) AS min,
            max(recruits.year) AS max,
            count(*) AS count
           FROM recruiting.recruits
        UNION ALL
         SELECT 'rosters'::text AS text,
            min(roster.year) AS min,
            max(roster.year) AS max,
            count(*) AS count
           FROM core.roster
        ), orphan_plays AS (
         SELECT count(*) FILTER (WHERE (NOT (EXISTS ( SELECT 1
                   FROM core.games g
                  WHERE (g.id = p.game_id))))) AS orphan_count,
            count(*) AS total_count
           FROM core.plays p
        ), orphan_drives AS (
         SELECT count(*) FILTER (WHERE (NOT (EXISTS ( SELECT 1
                   FROM core.games g
                  WHERE (g.id = d.game_id))))) AS orphan_count,
            count(*) AS total_count
           FROM core.drives d
        ), freshness AS (
         SELECT (((pg_stat_user_tables.schemaname)::text || '.'::text) || (pg_stat_user_tables.relname)::text) AS table_name,
            pg_stat_user_tables.n_live_tup AS row_count,
            pg_stat_user_tables.last_analyze,
            pg_stat_user_tables.last_autoanalyze
           FROM pg_stat_user_tables
          WHERE (pg_stat_user_tables.schemaname = ANY (ARRAY['core'::name, 'stats'::name, 'ratings'::name, 'recruiting'::name, 'betting'::name, 'draft'::name, 'metrics'::name, 'ref'::name]))
          ORDER BY pg_stat_user_tables.n_live_tup DESC
         LIMIT 20
        )
 SELECT 'coverage'::text AS check_type,
    coverage.metric,
    (coverage.min_year)::text AS value_1,
    (coverage.max_year)::text AS value_2,
    (coverage.row_count)::text AS value_3,
    NULL::text AS notes
   FROM coverage
UNION ALL
 SELECT 'integrity'::text AS check_type,
    'plays_without_games'::text AS metric,
    (orphan_plays.orphan_count)::text AS value_1,
    (orphan_plays.total_count)::text AS value_2,
        CASE
            WHEN (orphan_plays.total_count > 0) THEN ((round(((100.0 * (orphan_plays.orphan_count)::numeric) / (orphan_plays.total_count)::numeric), 2))::text || '%'::text)
            ELSE '0%'::text
        END AS value_3,
        CASE
            WHEN (orphan_plays.orphan_count > 0) THEN 'WARNING: Orphan plays detected'::text
            ELSE 'OK'::text
        END AS notes
   FROM orphan_plays
UNION ALL
 SELECT 'integrity'::text AS check_type,
    'drives_without_games'::text AS metric,
    (orphan_drives.orphan_count)::text AS value_1,
    (orphan_drives.total_count)::text AS value_2,
        CASE
            WHEN (orphan_drives.total_count > 0) THEN ((round(((100.0 * (orphan_drives.orphan_count)::numeric) / (orphan_drives.total_count)::numeric), 2))::text || '%'::text)
            ELSE '0%'::text
        END AS value_3,
        CASE
            WHEN (orphan_drives.orphan_count > 0) THEN 'WARNING: Orphan drives detected'::text
            ELSE 'OK'::text
        END AS notes
   FROM orphan_drives
UNION ALL
 SELECT 'table_size'::text AS check_type,
    freshness.table_name AS metric,
    (freshness.row_count)::text AS value_1,
    COALESCE((freshness.last_analyze)::text, 'never'::text) AS value_2,
    COALESCE((freshness.last_autoanalyze)::text, 'never'::text) AS value_3,
    NULL::text AS notes
   FROM freshness;


--
-- Name: VIEW data_quality_dashboard; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON VIEW analytics.data_quality_dashboard IS 'Data quality monitoring: coverage by year, orphan record detection, table freshness';


