--
-- Name: game_results; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.game_results AS
 WITH consensus_lines AS (
         SELECT DISTINCT ON (lines.game_id) lines.game_id,
            lines.spread,
            lines.over_under
           FROM betting.lines
          ORDER BY lines.game_id,
                CASE
                    WHEN ((lines.provider)::text = 'consensus'::text) THEN 0
                    ELSE 1
                END, lines.provider
        )
 SELECT g.id AS game_id,
    g.season,
    g.week,
    g.season_type,
    g.start_date AS game_date,
    g.home_team,
    g.home_conference,
    g.away_team,
    g.away_conference,
    g.home_points,
    g.away_points,
        CASE
            WHEN (g.home_points > g.away_points) THEN g.home_team
            WHEN (g.away_points > g.home_points) THEN g.away_team
            ELSE NULL::character varying
        END AS winner,
        CASE
            WHEN (g.home_points > g.away_points) THEN g.away_team
            WHEN (g.away_points > g.home_points) THEN g.home_team
            ELSE NULL::character varying
        END AS loser,
    (abs((g.home_points - g.away_points)))::integer AS point_diff,
    cl.spread AS home_spread,
    cl.over_under,
    wp.home_win_probability AS home_win_prob,
    g.home_pregame_elo AS home_elo,
    g.away_pregame_elo AS away_elo,
    g.excitement_index,
    g.venue,
    g.attendance
   FROM ((core.games g
     LEFT JOIN consensus_lines cl ON ((cl.game_id = g.id)))
     LEFT JOIN metrics.pregame_win_probability wp ON ((wp.game_id = g.id)))
  WHERE (g.completed = true)
  WITH NO DATA;


