--
-- Name: player_career_stats; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.player_career_stats AS
 WITH ranked AS (
         SELECT player_season_stats.player_id,
            player_season_stats.player,
            player_season_stats."position",
            player_season_stats.team,
            player_season_stats.conference,
            player_season_stats.season,
            player_season_stats.category,
            player_season_stats.stat_type,
            player_season_stats.stat,
            row_number() OVER (PARTITION BY player_season_stats.player_id, player_season_stats.category, player_season_stats.stat_type ORDER BY player_season_stats.season DESC) AS rn
           FROM stats.player_season_stats
        )
 SELECT player_id,
    max((
        CASE
            WHEN (rn = 1) THEN player
            ELSE NULL::character varying
        END)::text) AS player,
    max((
        CASE
            WHEN (rn = 1) THEN "position"
            ELSE NULL::character varying
        END)::text) AS "position",
    max((
        CASE
            WHEN (rn = 1) THEN team
            ELSE NULL::character varying
        END)::text) AS team,
    max((
        CASE
            WHEN (rn = 1) THEN conference
            ELSE NULL::character varying
        END)::text) AS conference,
    (count(DISTINCT season))::integer AS seasons_played,
    (min(season))::integer AS first_season,
    (max(season))::integer AS last_season,
    category,
    stat_type,
    sum((stat)::numeric) AS total_stat,
    round((sum((stat)::numeric) / (NULLIF(count(DISTINCT season), 0))::numeric), 2) AS avg_stat_per_season
   FROM ranked r
  GROUP BY player_id, category, stat_type
  WITH NO DATA;


