--
-- Name: team_recruiting_trend; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.team_recruiting_trend AS
 WITH commit_stats AS (
         SELECT recruits.year,
            recruits.committed_to AS team,
            (count(*))::integer AS num_commits,
            round((avg(recruits.rating))::numeric, 4) AS avg_rating,
            (count(*) FILTER (WHERE (recruits.stars = 5)))::integer AS five_stars,
            (count(*) FILTER (WHERE (recruits.stars = 4)))::integer AS four_stars,
            (count(*) FILTER (WHERE (recruits.stars = 3)))::integer AS three_stars
           FROM recruiting.recruits
          WHERE (recruits.committed_to IS NOT NULL)
          GROUP BY recruits.year, recruits.committed_to
        ), top_positions AS (
         SELECT DISTINCT ON (pos_counts.year, pos_counts.committed_to) pos_counts.year,
            pos_counts.committed_to AS team,
            pos_counts."position" AS top_position
           FROM ( SELECT recruits.year,
                    recruits.committed_to,
                    recruits."position",
                    count(*) AS pos_count
                   FROM recruiting.recruits
                  WHERE ((recruits.committed_to IS NOT NULL) AND (recruits."position" IS NOT NULL))
                  GROUP BY recruits.year, recruits.committed_to, recruits."position") pos_counts
          ORDER BY pos_counts.year, pos_counts.committed_to, pos_counts.pos_count DESC
        )
 SELECT tr.year,
    tr.team,
    tr.rank AS recruiting_rank,
    tr.points AS recruiting_points,
    COALESCE(cs.num_commits, 0) AS num_commits,
    cs.avg_rating,
    COALESCE(cs.five_stars, 0) AS five_stars,
    COALESCE(cs.four_stars, 0) AS four_stars,
    COALESCE(cs.three_stars, 0) AS three_stars,
    tp.top_position,
    round(avg((tr.rank)::numeric) OVER (PARTITION BY tr.team ORDER BY tr.year ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS recruiting_rank_3yr_avg
   FROM ((recruiting.team_recruiting tr
     LEFT JOIN commit_stats cs ON (((cs.year = tr.year) AND ((cs.team)::text = (tr.team)::text))))
     LEFT JOIN top_positions tp ON (((tp.year = tr.year) AND ((tp.team)::text = (tr.team)::text))))
  WITH NO DATA;


