--
-- Name: coach_records; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.coach_records AS
 WITH coach_seasons AS (
         SELECT c.first_name,
            c.last_name,
            COALESCE(NULLIF(TRIM(BOTH FROM (((c.first_name)::text || ' '::text) || (c.last_name)::text)), ''::text), (c.last_name)::text, (c.first_name)::text) AS coach_name,
            cs.school AS team,
            cs.year AS season,
            cs.games,
            cs.wins,
            cs.losses,
            cs.ties,
            match.coach_id AS season_coach_id,
            match.ambiguous AS season_match_ambiguous
           FROM ((ref.coaches c
             JOIN ref.coaches__seasons cs ON (((cs._dlt_parent_id)::text = (c._dlt_id)::text)))
             LEFT JOIN LATERAL ( SELECT
                        CASE
                            WHEN (count(DISTINCT rcs.coach__id) = 1) THEN min(rcs.coach__id)
                            ELSE NULL::bigint
                        END AS coach_id,
                    (count(DISTINCT rcs.coach__id) > 1) AS ambiguous
                   FROM ref.coach_seasons rcs
                  WHERE (((rcs.coach__first_name)::text = (c.first_name)::text) AND ((rcs.coach__last_name)::text = (c.last_name)::text) AND ((rcs.team__school)::text = (cs.school)::text) AND (rcs.year = cs.year))) match ON (true))
          WHERE ((cs.school IS NOT NULL) AND (cs.year IS NOT NULL))
        ), coach_seasons_ats AS (
         SELECT cse.first_name,
            cse.last_name,
            cse.coach_name,
            cse.team,
            cse.season,
            cse.games,
            cse.wins,
            cse.losses,
            cse.ties,
            cse.season_coach_id,
            cse.season_match_ambiguous,
            tar.ats_wins,
            tar.ats_losses,
            tar.ats_pushes,
            (tar.team IS NOT NULL) AS has_ats_data
           FROM (coach_seasons cse
             LEFT JOIN marts.team_ats_records tar ON ((((tar.team)::text = (cse.team)::text) AND (tar.season = cse.season))))
        )
 SELECT
        CASE
            WHEN ((count(DISTINCT season_coach_id) FILTER (WHERE (season_coach_id IS NOT NULL)) = 1) AND (NOT bool_or(season_match_ambiguous))) THEN min(season_coach_id)
            ELSE NULL::bigint
        END AS coach_id,
    coach_name,
    first_name,
    last_name,
    team,
    min(season) AS first_season,
    max(season) AS last_season,
    count(DISTINCT season) AS seasons_count,
    (sum(COALESCE(games, (0)::bigint)))::integer AS games,
    (sum(COALESCE(wins, (0)::bigint)))::integer AS wins,
    (sum(COALESCE(losses, (0)::bigint)))::integer AS losses,
    (sum(COALESCE(ties, (0)::bigint)))::integer AS ties,
    round((sum(COALESCE(wins, (0)::bigint)) / NULLIF((sum(COALESCE(wins, (0)::bigint)) + sum(COALESCE(losses, (0)::bigint))), (0)::numeric)), 4) AS win_pct,
    (((sum(COALESCE(ats_wins, (0)::bigint)))::integer + (sum(COALESCE(ats_losses, (0)::bigint)))::integer) + (sum(COALESCE(ats_pushes, (0)::bigint)))::integer) AS ats_games,
    (sum(COALESCE(ats_wins, (0)::bigint)))::integer AS ats_wins,
    (sum(COALESCE(ats_losses, (0)::bigint)))::integer AS ats_losses,
    (sum(COALESCE(ats_pushes, (0)::bigint)))::integer AS ats_pushes,
    round((sum(COALESCE(ats_wins, (0)::bigint)) / NULLIF((sum(COALESCE(ats_wins, (0)::bigint)) + sum(COALESCE(ats_losses, (0)::bigint))), (0)::numeric)), 4) AS ats_win_pct,
    count(*) FILTER (WHERE has_ats_data) AS seasons_with_ats_data
   FROM coach_seasons_ats
  GROUP BY coach_name, first_name, last_name, team;


--
-- Name: VIEW coach_records; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.coach_records IS 'Coach career records at a school (coach x team grain), straight-up and against-the-spread. Columns: coach_id, coach_name, first_name, last_name, team, first_season, last_season, seasons_count, games, wins, losses, ties, win_pct, ats_games, ats_wins, ats_losses, ats_pushes, ats_win_pct, seasons_with_ats_data. Coach attribution is whole-season (mid-season coaching changes not splittable -- see ref.coaches__seasons). ATS columns are partial pre-lines-era coverage (LEFT JOIN to marts.team_ats_records); use seasons_with_ats_data to gauge coverage. coach_id (added 2026-08-30) is ref.coach_seasons'' coach__id, matched by (first_name, last_name, team, year) -- the single id every MATCHED season of the coach''s career at this school agrees on; NULL when any season''s match is ambiguous (more than one distinct coach__id -- one ambiguous season poisons the entire career''s coach_id), when matched seasons disagree, or when zero seasons matched. Seasons outside ref.coach_seasons'' coverage (it has no pre-2014 depth) do NOT invalidate the match. Backed by ref.coaches / ref.coaches__seasons and marts.team_ats_records.';


