--
-- Name: recruiting_class; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.recruiting_class AS
 WITH recruit_details AS (
         SELECT r.committed_to AS team,
            r.year,
            r.stars,
            r.rating,
            r."position",
            r.ranking,
                CASE
                    WHEN ((r."position")::text = 'QB'::text) THEN 'qb'::text
                    WHEN ((r."position")::text = ANY (ARRAY[('RB'::character varying)::text, ('FB'::character varying)::text, ('APB'::character varying)::text])) THEN 'rb'::text
                    WHEN ((r."position")::text = ANY (ARRAY[('WR'::character varying)::text, ('TE'::character varying)::text])) THEN 'receiver'::text
                    WHEN ((r."position")::text = ANY (ARRAY[('OT'::character varying)::text, ('OG'::character varying)::text, ('OC'::character varying)::text, ('OL'::character varying)::text])) THEN 'oline'::text
                    WHEN ((r."position")::text = ANY (ARRAY[('DE'::character varying)::text, ('DT'::character varying)::text, ('DL'::character varying)::text, ('EDGE'::character varying)::text, ('SDE'::character varying)::text, ('WDE'::character varying)::text])) THEN 'dline'::text
                    WHEN ((r."position")::text = ANY (ARRAY[('ILB'::character varying)::text, ('OLB'::character varying)::text, ('LB'::character varying)::text])) THEN 'lb'::text
                    WHEN ((r."position")::text = ANY (ARRAY[('CB'::character varying)::text, ('S'::character varying)::text, ('DB'::character varying)::text])) THEN 'db'::text
                    WHEN ((r."position")::text = ANY (ARRAY[('K'::character varying)::text, ('P'::character varying)::text, ('LS'::character varying)::text])) THEN 'specialist'::text
                    ELSE 'ath'::text
                END AS position_group
           FROM recruiting.recruits r
          WHERE (r.committed_to IS NOT NULL)
        ), position_counts AS (
         SELECT recruit_details.team,
            recruit_details.year,
            recruit_details.position_group,
            count(*) AS cnt
           FROM recruit_details
          GROUP BY recruit_details.team, recruit_details.year, recruit_details.position_group
        ), top_position AS (
         SELECT DISTINCT ON (position_counts.team, position_counts.year) position_counts.team,
            position_counts.year,
            position_counts.position_group AS top_position_group
           FROM position_counts
          ORDER BY position_counts.team, position_counts.year, position_counts.cnt DESC
        )
 SELECT rd.team,
    rd.year,
    tr.rank AS national_rank,
    tr.points AS total_points,
    count(*) AS total_commits,
    (count(*) FILTER (WHERE (rd.stars = 5)))::integer AS five_stars,
    (count(*) FILTER (WHERE (rd.stars = 4)))::integer AS four_stars,
    (count(*) FILTER (WHERE (rd.stars = 3)))::integer AS three_stars,
    (count(*) FILTER (WHERE (rd.stars = 2)))::integer AS two_stars,
    (count(*) FILTER (WHERE ((rd.stars IS NULL) OR (rd.stars < 2))))::integer AS unrated,
    round(((count(*) FILTER (WHERE (rd.stars >= 4)))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS blue_chip_ratio,
    round((avg(rd.rating))::numeric, 4) AS avg_rating,
    max(rd.rating) AS top_rating,
    min(rd.ranking) FILTER (WHERE (rd.ranking IS NOT NULL)) AS best_recruit_rank,
    (count(*) FILTER (WHERE (rd.position_group = 'qb'::text)))::integer AS qb_commits,
    (count(*) FILTER (WHERE (rd.position_group = 'rb'::text)))::integer AS rb_commits,
    (count(*) FILTER (WHERE (rd.position_group = 'receiver'::text)))::integer AS receiver_commits,
    (count(*) FILTER (WHERE (rd.position_group = 'oline'::text)))::integer AS oline_commits,
    (count(*) FILTER (WHERE (rd.position_group = 'dline'::text)))::integer AS dline_commits,
    (count(*) FILTER (WHERE (rd.position_group = 'lb'::text)))::integer AS lb_commits,
    (count(*) FILTER (WHERE (rd.position_group = 'db'::text)))::integer AS db_commits,
    tp.top_position_group
   FROM ((recruit_details rd
     LEFT JOIN recruiting.team_recruiting tr ON ((((tr.team)::text = (rd.team)::text) AND (tr.year = rd.year))))
     LEFT JOIN top_position tp ON ((((tp.team)::text = (rd.team)::text) AND (tp.year = rd.year))))
  GROUP BY rd.team, rd.year, tr.rank, tr.points, tp.top_position_group
  WITH NO DATA;


--
-- Name: core_ratings; Type: TABLE; Schema: ratings; Owner: -
--

CREATE TABLE ratings.core_ratings (
    year bigint NOT NULL,
    through_season_type character varying,
    through_week bigint,
    team character varying NOT NULL,
    conference character varying,
    overall double precision,
    offense double precision,
    defense double precision,
    offense_plays bigint,
    defense_plays bigint,
    model_version character varying,
    _dlt_load_id character varying NOT NULL,
    _dlt_id character varying NOT NULL
);


--
-- Name: fpi_ratings; Type: TABLE; Schema: ratings; Owner: -
--

CREATE TABLE ratings.fpi_ratings (
    year bigint NOT NULL,
    team character varying NOT NULL,
    conference character varying,
    fpi double precision,
    resume_ranks__strength_of_record bigint,
    resume_ranks__fpi bigint,
    resume_ranks__average_win_probability bigint,
    resume_ranks__strength_of_schedule bigint,
    resume_ranks__game_control bigint,
    efficiencies__overall double precision,
    efficiencies__offense double precision,
    efficiencies__defense double precision,
    efficiencies__special_teams double precision,
    _dlt_load_id character varying NOT NULL,
    _dlt_id character varying NOT NULL,
    resume_ranks__remaining_strength_of_schedule bigint
);


--
-- Name: team_season_summary; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_season_summary AS
 WITH home_games AS (
         SELECT games.season,
            games.home_team AS team,
            games.home_conference AS conference,
            games.home_points AS points_for,
            games.away_points AS points_against,
                CASE
                    WHEN (games.home_points > games.away_points) THEN 1
                    ELSE 0
                END AS win,
                CASE
                    WHEN (games.home_points < games.away_points) THEN 1
                    ELSE 0
                END AS loss,
                CASE
                    WHEN ((games.home_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text)) THEN 1
                    ELSE 0
                END AS is_conference_game,
                CASE
                    WHEN ((games.home_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.home_points > games.away_points)) THEN 1
                    ELSE 0
                END AS conf_win,
                CASE
                    WHEN ((games.home_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.home_points < games.away_points)) THEN 1
                    ELSE 0
                END AS conf_loss
           FROM core.games
          WHERE (games.completed = true)
        ), away_games AS (
         SELECT games.season,
            games.away_team AS team,
            games.away_conference AS conference,
            games.away_points AS points_for,
            games.home_points AS points_against,
                CASE
                    WHEN (games.away_points > games.home_points) THEN 1
                    ELSE 0
                END AS win,
                CASE
                    WHEN (games.away_points < games.home_points) THEN 1
                    ELSE 0
                END AS loss,
                CASE
                    WHEN ((games.away_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text)) THEN 1
                    ELSE 0
                END AS is_conference_game,
                CASE
                    WHEN ((games.away_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.away_points > games.home_points)) THEN 1
                    ELSE 0
                END AS conf_win,
                CASE
                    WHEN ((games.away_conference IS NOT NULL) AND ((games.home_conference)::text = (games.away_conference)::text) AND (games.away_points < games.home_points)) THEN 1
                    ELSE 0
                END AS conf_loss
           FROM core.games
          WHERE (games.completed = true)
        ), all_games AS (
         SELECT home_games.season,
            home_games.team,
            home_games.conference,
            home_games.points_for,
            home_games.points_against,
            home_games.win,
            home_games.loss,
            home_games.is_conference_game,
            home_games.conf_win,
            home_games.conf_loss
           FROM home_games
        UNION ALL
         SELECT away_games.season,
            away_games.team,
            away_games.conference,
            away_games.points_for,
            away_games.points_against,
            away_games.win,
            away_games.loss,
            away_games.is_conference_game,
            away_games.conf_win,
            away_games.conf_loss
           FROM away_games
        ), team_records AS (
         SELECT all_games.season,
            all_games.team,
            max((all_games.conference)::text) AS conference,
            count(*) AS games,
            sum(all_games.win) AS wins,
            sum(all_games.loss) AS losses,
            sum(all_games.conf_win) AS conf_wins,
            sum(all_games.conf_loss) AS conf_losses,
            round(avg(all_games.points_for), 1) AS ppg,
            round(avg(all_games.points_against), 1) AS opp_ppg,
            round(avg((all_games.points_for - all_games.points_against)), 1) AS avg_margin
           FROM all_games
          GROUP BY all_games.season, all_games.team
        )
 SELECT tr.team,
    tr.conference,
    tr.season,
    (tr.games)::integer AS games,
    (tr.wins)::integer AS wins,
    (tr.losses)::integer AS losses,
    (tr.conf_wins)::integer AS conf_wins,
    (tr.conf_losses)::integer AS conf_losses,
    tr.ppg,
    tr.opp_ppg,
    tr.avg_margin,
    sp.rating AS sp_rating,
    sp.ranking AS sp_rank,
    sp.offense__rating AS sp_offense,
    sp.defense__rating AS sp_defense,
    elo.elo,
    fpi.fpi,
    cr.overall AS core_overall,
    cr.offense AS core_offense,
    cr.defense AS core_defense,
    rec.rank AS recruiting_rank,
    rec.points AS recruiting_points
   FROM (((((team_records tr
     LEFT JOIN ratings.sp_ratings sp ON ((((tr.team)::text = (sp.team)::text) AND (tr.season = sp.year))))
     LEFT JOIN ratings.elo_ratings elo ON ((((tr.team)::text = (elo.team)::text) AND (tr.season = elo.year))))
     LEFT JOIN ratings.fpi_ratings fpi ON ((((tr.team)::text = (fpi.team)::text) AND (tr.season = fpi.year))))
     LEFT JOIN ratings.core_ratings cr ON ((((tr.team)::text = (cr.team)::text) AND (tr.season = cr.year))))
     LEFT JOIN recruiting.team_recruiting rec ON ((((tr.team)::text = (rec.team)::text) AND (tr.season = rec.year))))
  WITH NO DATA;


--
-- Name: coaching_tenure; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.coaching_tenure AS
 WITH coach_seasons AS (
         SELECT c.first_name,
            c.last_name,
            (((c.first_name)::text || ' '::text) || (c.last_name)::text) AS coach_name,
            cs.school AS team,
            cs.year AS season,
            cs.games,
            cs.wins,
            cs.losses,
            cs.ties,
            cs.preseason_rank,
            cs.postseason_rank,
            cs.sp_overall,
            match.coach_id AS season_coach_id,
            match.ambiguous AS season_match_ambiguous
           FROM ((ref.coaches c
             JOIN ref.coaches__seasons cs ON (((cs._dlt_parent_id)::text = (c._dlt_id)::text)))
             LEFT JOIN LATERAL ( SELECT
                        CASE
                            WHEN (count(DISTINCT rcs.coach__id) = 1) THEN min(rcs.coach__id)
                            ELSE NULL::bigint
                        END AS coach_id,
                    (count(DISTINCT rcs.coach__id) > 1) AS ambiguous
                   FROM ref.coach_seasons rcs
                  WHERE (((rcs.coach__first_name)::text = (c.first_name)::text) AND ((rcs.coach__last_name)::text = (c.last_name)::text) AND ((rcs.team__school)::text = (cs.school)::text) AND (rcs.year = cs.year))) match ON (true))
          WHERE (cs.school IS NOT NULL)
        ), gap_detect AS (
         SELECT coach_seasons.first_name,
            coach_seasons.last_name,
            coach_seasons.coach_name,
            coach_seasons.team,
            coach_seasons.season,
            coach_seasons.games,
            coach_seasons.wins,
            coach_seasons.losses,
            coach_seasons.ties,
            coach_seasons.preseason_rank,
            coach_seasons.postseason_rank,
            coach_seasons.sp_overall,
            coach_seasons.season_coach_id,
            coach_seasons.season_match_ambiguous,
            (coach_seasons.season - lag(coach_seasons.season) OVER (PARTITION BY coach_seasons.first_name, coach_seasons.last_name, coach_seasons.team ORDER BY coach_seasons.season)) AS gap
           FROM coach_seasons
        ), tenure_groups AS (
         SELECT gap_detect.first_name,
            gap_detect.last_name,
            gap_detect.coach_name,
            gap_detect.team,
            gap_detect.season,
            gap_detect.games,
            gap_detect.wins,
            gap_detect.losses,
            gap_detect.ties,
            gap_detect.preseason_rank,
            gap_detect.postseason_rank,
            gap_detect.sp_overall,
            gap_detect.season_coach_id,
            gap_detect.season_match_ambiguous,
            gap_detect.gap,
            sum(
                CASE
                    WHEN ((gap_detect.gap IS NULL) OR (gap_detect.gap > 1)) THEN 1
                    ELSE 0
                END) OVER (PARTITION BY gap_detect.first_name, gap_detect.last_name, gap_detect.team ORDER BY gap_detect.season) AS tenure_id
           FROM gap_detect
        ), tenure_agg AS (
         SELECT tenure_groups.coach_name,
            tenure_groups.first_name,
            tenure_groups.last_name,
            tenure_groups.team,
            tenure_groups.tenure_id,
            min(tenure_groups.season) AS tenure_start,
            max(tenure_groups.season) AS tenure_end,
            count(DISTINCT tenure_groups.season) AS seasons_count,
                CASE
                    WHEN ((count(DISTINCT tenure_groups.season_coach_id) FILTER (WHERE (tenure_groups.season_coach_id IS NOT NULL)) = 1) AND (NOT bool_or(tenure_groups.season_match_ambiguous))) THEN min(tenure_groups.season_coach_id)
                    ELSE NULL::bigint
                END AS coach_id,
            (sum(COALESCE(tenure_groups.games, (0)::bigint)))::integer AS total_games,
            (sum(COALESCE(tenure_groups.wins, (0)::bigint)))::integer AS total_wins,
            (sum(COALESCE(tenure_groups.losses, (0)::bigint)))::integer AS total_losses,
            (sum(COALESCE(tenure_groups.ties, (0)::bigint)))::integer AS total_ties,
            max(tenure_groups.wins) AS best_season_wins,
            min(tenure_groups.wins) AS worst_season_wins,
            min(tenure_groups.preseason_rank) FILTER (WHERE (tenure_groups.preseason_rank IS NOT NULL)) AS best_preseason_rank,
            min(tenure_groups.postseason_rank) FILTER (WHERE (tenure_groups.postseason_rank IS NOT NULL)) AS best_postseason_rank,
            round((avg(tenure_groups.sp_overall))::numeric, 2) AS avg_sp_rating,
            max(tenure_groups.sp_overall) AS peak_sp_rating
           FROM tenure_groups
          GROUP BY tenure_groups.coach_name, tenure_groups.first_name, tenure_groups.last_name, tenure_groups.team, tenure_groups.tenure_id
        ), bowl_counts AS (
         SELECT ta_1.team,
            ta_1.first_name,
            ta_1.last_name,
            ta_1.tenure_start,
            count(DISTINCT g.id) AS bowl_games,
            count(DISTINCT g.id) FILTER (WHERE ((((g.home_team)::text = (ta_1.team)::text) AND (g.home_points > g.away_points)) OR (((g.away_team)::text = (ta_1.team)::text) AND (g.away_points > g.home_points)))) AS bowl_wins
           FROM (tenure_agg ta_1
             JOIN core.games g ON (((((g.home_team)::text = (ta_1.team)::text) OR ((g.away_team)::text = (ta_1.team)::text)) AND ((g.season >= ta_1.tenure_start) AND (g.season <= ta_1.tenure_end)) AND ((g.season_type)::text = 'postseason'::text) AND (g.completed = true))))
          GROUP BY ta_1.team, ta_1.first_name, ta_1.last_name, ta_1.tenure_start
        ), inherited AS (
         SELECT ta_1.first_name,
            ta_1.last_name,
            ta_1.team,
            ta_1.tenure_start,
            rc_1.national_rank AS inherited_talent_rank
           FROM (tenure_agg ta_1
             LEFT JOIN marts.recruiting_class rc_1 ON ((((rc_1.team)::text = (ta_1.team)::text) AND (rc_1.year = ta_1.tenure_start))))
        ), year3 AS (
         SELECT ta_1.first_name,
            ta_1.last_name,
            ta_1.team,
            ta_1.tenure_start,
            rc_1.national_rank AS year3_talent_rank
           FROM (tenure_agg ta_1
             LEFT JOIN marts.recruiting_class rc_1 ON ((((rc_1.team)::text = (ta_1.team)::text) AND (rc_1.year = (ta_1.tenure_start + 2)))))
          WHERE (ta_1.seasons_count >= 3)
        )
 SELECT ta.coach_id,
    ta.coach_name,
    ta.first_name,
    ta.last_name,
    ta.team,
    ta.tenure_start,
    ta.tenure_end,
    ta.seasons_count,
    ta.total_games,
    ta.total_wins,
    ta.total_losses,
    ta.total_ties,
    round(((ta.total_wins)::numeric / (NULLIF((ta.total_wins + ta.total_losses), 0))::numeric), 4) AS win_pct,
    (( SELECT sum(tss.conf_wins) AS sum
           FROM marts.team_season_summary tss
          WHERE (((tss.team)::text = (ta.team)::text) AND ((tss.season >= ta.tenure_start) AND (tss.season <= ta.tenure_end)))))::integer AS conf_wins,
    (( SELECT sum(tss.conf_losses) AS sum
           FROM marts.team_season_summary tss
          WHERE (((tss.team)::text = (ta.team)::text) AND ((tss.season >= ta.tenure_start) AND (tss.season <= ta.tenure_end)))))::integer AS conf_losses,
    round((( SELECT (sum(tss.conf_wins))::numeric AS sum
           FROM marts.team_season_summary tss
          WHERE (((tss.team)::text = (ta.team)::text) AND ((tss.season >= ta.tenure_start) AND (tss.season <= ta.tenure_end)))) / (NULLIF(( SELECT sum((tss.conf_wins + tss.conf_losses)) AS sum
           FROM marts.team_season_summary tss
          WHERE (((tss.team)::text = (ta.team)::text) AND ((tss.season >= ta.tenure_start) AND (tss.season <= ta.tenure_end)))), 0))::numeric), 4) AS conf_win_pct,
    ta.best_season_wins,
    ta.worst_season_wins,
    ta.avg_sp_rating,
    ta.peak_sp_rating,
    ta.best_preseason_rank,
    ta.best_postseason_rank,
    round(avg(rc.national_rank), 1) AS avg_recruiting_rank,
    min(rc.national_rank) AS best_recruiting_rank,
    ih.inherited_talent_rank,
    y3.year3_talent_rank,
        CASE
            WHEN ((ih.inherited_talent_rank IS NOT NULL) AND (y3.year3_talent_rank IS NOT NULL)) THEN (ih.inherited_talent_rank - y3.year3_talent_rank)
            ELSE NULL::bigint
        END AS talent_improvement,
    (COALESCE(bc.bowl_games, (0)::bigint))::integer AS bowl_games,
    (COALESCE(bc.bowl_wins, (0)::bigint))::integer AS bowl_wins,
    (ta.tenure_end >= (( SELECT max(coaches__seasons.year) AS max
           FROM ref.coaches__seasons) - 1)) AS is_active
   FROM ((((tenure_agg ta
     LEFT JOIN marts.recruiting_class rc ON ((((rc.team)::text = (ta.team)::text) AND ((rc.year >= ta.tenure_start) AND (rc.year <= ta.tenure_end)))))
     LEFT JOIN bowl_counts bc ON ((((bc.team)::text = (ta.team)::text) AND ((bc.first_name)::text = (ta.first_name)::text) AND ((bc.last_name)::text = (ta.last_name)::text) AND (bc.tenure_start = ta.tenure_start))))
     LEFT JOIN inherited ih ON ((((ih.team)::text = (ta.team)::text) AND ((ih.first_name)::text = (ta.first_name)::text) AND ((ih.last_name)::text = (ta.last_name)::text) AND (ih.tenure_start = ta.tenure_start))))
     LEFT JOIN year3 y3 ON ((((y3.team)::text = (ta.team)::text) AND ((y3.first_name)::text = (ta.first_name)::text) AND ((y3.last_name)::text = (ta.last_name)::text) AND (y3.tenure_start = ta.tenure_start))))
  GROUP BY ta.coach_id, ta.coach_name, ta.first_name, ta.last_name, ta.team, ta.tenure_id, ta.tenure_start, ta.tenure_end, ta.seasons_count, ta.total_games, ta.total_wins, ta.total_losses, ta.total_ties, ta.best_season_wins, ta.worst_season_wins, ta.avg_sp_rating, ta.peak_sp_rating, ta.best_preseason_rank, ta.best_postseason_rank, ih.inherited_talent_rank, y3.year3_talent_rank, bc.bowl_games, bc.bowl_wins
  WITH NO DATA;


--
-- Name: coaching_history; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.coaching_history AS
 SELECT coach_id,
    coach_name,
    first_name,
    last_name,
    team,
    tenure_start,
    tenure_end,
    seasons_count,
    total_games,
    total_wins,
    total_losses,
    total_ties,
    win_pct,
    conf_wins,
    conf_losses,
    conf_win_pct,
    best_season_wins,
    worst_season_wins,
    avg_sp_rating,
    peak_sp_rating,
    best_preseason_rank,
    best_postseason_rank,
    avg_recruiting_rank,
    best_recruiting_rank,
    inherited_talent_rank,
    year3_talent_rank,
    talent_improvement,
    bowl_games,
    bowl_wins,
    is_active
   FROM marts.coaching_tenure;


--
-- Name: VIEW coaching_history; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.coaching_history IS 'Coaching history with tenure performance summaries. One row per coach-team-tenure. Filter by team, coach_name, last_name, is_active. talent_improvement = inherited_rank - year3_rank (positive = improved recruiting). coach_id (added 2026-08-30) is ref.coach_seasons'' coach__id, matched by (first_name, last_name, team, year) -- the single id every MATCHED season of the tenure agrees on. NULL when any season''s match is ambiguous (more than one distinct coach__id -- one ambiguous season poisons the entire tenure''s coach_id), when matched seasons disagree, or when zero seasons matched; seasons outside ref.coach_seasons'' coverage (it has no pre-2014 depth) do NOT invalidate the match. Use it instead of first_name+last_name to join to api.coach_records or api.coach_tenures.';


--
-- Name: _game_epa_calc; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts._game_epa_calc AS
 SELECT game_id,
    offense AS team,
    round((avg(ppa) FILTER (WHERE (NOT (((period = 4) AND (abs(COALESCE(score_diff, 0)) > 28)) OR ((period >= 3) AND (abs(COALESCE(score_diff, 0)) > 35))))))::numeric, 4) AS epa_per_play,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (NOT (((period = 4) AND (abs(COALESCE(score_diff, 0)) > 28)) OR ((period >= 3) AND (abs(COALESCE(score_diff, 0)) > 35))))), 4) AS success_rate,
    round((avg(ppa) FILTER (WHERE ((ppa > (0)::double precision) AND (NOT (((period = 4) AND (abs(COALESCE(score_diff, 0)) > 28)) OR ((period >= 3) AND (abs(COALESCE(score_diff, 0)) > 35)))))))::numeric, 4) AS explosiveness,
    count(*) FILTER (WHERE (NOT (((period = 4) AND (abs(COALESCE(score_diff, 0)) > 28)) OR ((period >= 3) AND (abs(COALESCE(score_diff, 0)) > 35))))) AS plays_non_garbage,
    count(*) AS plays_total
   FROM core.plays p
  WHERE (ppa IS NOT NULL)
  GROUP BY game_id, offense
  WITH NO DATA;


--
-- Name: team_epa_season; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_epa_season AS
 SELECT epa.team,
    g.season,
    round(avg(epa.epa_per_play), 4) AS epa_per_play,
    round(avg(epa.success_rate), 4) AS success_rate,
    round(avg(epa.explosiveness), 4) AS explosiveness,
        CASE
            WHEN (avg(epa.epa_per_play) >= 0.16) THEN 'elite'::text
            WHEN (avg(epa.epa_per_play) >= 0.05) THEN 'above_avg'::text
            WHEN (avg(epa.epa_per_play) >= '-0.05'::numeric) THEN 'average'::text
            WHEN (avg(epa.epa_per_play) >= '-0.15'::numeric) THEN 'below_avg'::text
            ELSE 'struggling'::text
        END AS epa_tier,
    (sum(epa.plays_non_garbage))::bigint AS total_plays,
    (count(*))::integer AS games_played
   FROM (marts._game_epa_calc epa
     JOIN core.games g ON ((epa.game_id = g.id)))
  GROUP BY epa.team, g.season
  WITH NO DATA;


--
-- Name: conference_comparison; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.conference_comparison AS
 WITH team_conf AS (
         SELECT DISTINCT ON (teams.school) teams.school,
            teams.conference
           FROM ref.teams
          WHERE (teams.conference IS NOT NULL)
          ORDER BY teams.school, teams.classification
        ), non_conf_games AS (
         SELECT g.season,
                CASE
                    WHEN (((g.home_conference)::text <> (g.away_conference)::text) AND (g.home_points > g.away_points)) THEN g.home_conference
                    WHEN (((g.home_conference)::text <> (g.away_conference)::text) AND (g.away_points > g.home_points)) THEN g.away_conference
                    ELSE NULL::character varying
                END AS winning_conference,
                CASE
                    WHEN ((g.home_conference)::text <> (g.away_conference)::text) THEN g.home_conference
                    ELSE NULL::character varying
                END AS home_conf,
                CASE
                    WHEN ((g.home_conference)::text <> (g.away_conference)::text) THEN g.away_conference
                    ELSE NULL::character varying
                END AS away_conf
           FROM core.games g
          WHERE ((g.completed = true) AND (g.home_conference IS NOT NULL) AND (g.away_conference IS NOT NULL) AND ((g.home_conference)::text <> (g.away_conference)::text))
        ), non_conf_record AS (
         SELECT x.conf,
            x.season,
            count(*) AS non_conf_games,
            (sum(x.wins))::integer AS non_conf_wins
           FROM ( SELECT non_conf_games.home_conf AS conf,
                    non_conf_games.season,
                        CASE
                            WHEN ((non_conf_games.winning_conference)::text = (non_conf_games.home_conf)::text) THEN 1
                            ELSE 0
                        END AS wins
                   FROM non_conf_games
                  WHERE (non_conf_games.home_conf IS NOT NULL)
                UNION ALL
                 SELECT non_conf_games.away_conf AS conf,
                    non_conf_games.season,
                        CASE
                            WHEN ((non_conf_games.winning_conference)::text = (non_conf_games.away_conf)::text) THEN 1
                            ELSE 0
                        END AS wins
                   FROM non_conf_games
                  WHERE (non_conf_games.away_conf IS NOT NULL)) x
          GROUP BY x.conf, x.season
        ), conf_agg AS (
         SELECT tc.conference,
            tss.season,
            count(DISTINCT tss.team) AS member_count,
            round(avg(tss.wins), 2) AS avg_wins,
            round((avg(tss.sp_rating))::numeric, 2) AS avg_sp_rating,
            round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY tss.sp_rating))::numeric, 2) AS median_sp_rating,
            (array_agg(tss.team ORDER BY tss.sp_rating DESC NULLS LAST))[1] AS best_team,
            max(tss.sp_rating) AS best_team_sp,
            (array_agg(tss.team ORDER BY tss.sp_rating))[1] AS worst_team,
            min(tss.sp_rating) AS worst_team_sp,
            round((stddev(tss.sp_rating))::numeric, 2) AS std_dev_sp,
            round(avg(epa.epa_per_play), 4) AS avg_epa_per_play,
            round(avg(epa.success_rate), 4) AS avg_success_rate,
            round(avg(rc.national_rank), 1) AS avg_recruiting_rank,
            (sum((rc.five_stars + rc.four_stars)))::integer AS total_blue_chips,
            round(avg(rc.blue_chip_ratio), 4) AS avg_blue_chip_ratio,
            count(*) FILTER (WHERE ((tss.sp_rank IS NOT NULL) AND (tss.sp_rank <= 25))) AS ranked_team_count
           FROM (((marts.team_season_summary tss
             JOIN team_conf tc ON (((tc.school)::text = (tss.team)::text)))
             LEFT JOIN marts.team_epa_season epa ON ((((epa.team)::text = (tss.team)::text) AND (epa.season = tss.season))))
             LEFT JOIN marts.recruiting_class rc ON ((((rc.team)::text = (tss.team)::text) AND (rc.year = tss.season))))
          WHERE (tc.conference IS NOT NULL)
          GROUP BY tc.conference, tss.season
         HAVING (count(DISTINCT tss.team) >= 4)
        ), combined AS (
         SELECT ca.conference,
            ca.season,
            ca.member_count,
            ca.avg_wins,
            ca.avg_sp_rating,
            ca.median_sp_rating,
            ca.best_team,
            ca.best_team_sp,
            ca.worst_team,
            ca.worst_team_sp,
            ca.std_dev_sp,
            ca.avg_epa_per_play,
            ca.avg_success_rate,
            ca.avg_recruiting_rank,
            ca.total_blue_chips,
            ca.avg_blue_chip_ratio,
            ca.ranked_team_count,
            round(((ncr.non_conf_wins)::numeric / (NULLIF(ncr.non_conf_games, 0))::numeric), 4) AS non_conf_win_pct
           FROM (conf_agg ca
             LEFT JOIN non_conf_record ncr ON ((((ncr.conf)::text = (ca.conference)::text) AND (ncr.season = ca.season))))
        )
 SELECT conference,
    season,
    member_count,
    avg_wins,
    avg_sp_rating,
    median_sp_rating,
    best_team,
    best_team_sp,
    worst_team,
    worst_team_sp,
    std_dev_sp,
    avg_epa_per_play,
    avg_success_rate,
    avg_recruiting_rank,
    total_blue_chips,
    avg_blue_chip_ratio,
    ranked_team_count,
    non_conf_win_pct,
        CASE
            WHEN (avg_sp_rating IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY avg_sp_rating)
            ELSE NULL::double precision
        END AS avg_sp_pctl,
        CASE
            WHEN (avg_epa_per_play IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY avg_epa_per_play)
            ELSE NULL::double precision
        END AS avg_epa_pctl,
        CASE
            WHEN (avg_recruiting_rank IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY avg_recruiting_rank DESC)
            ELSE NULL::double precision
        END AS avg_recruiting_pctl,
        CASE
            WHEN (non_conf_win_pct IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY non_conf_win_pct)
            ELSE NULL::double precision
        END AS non_conf_win_pct_pctl
   FROM combined c
  WITH NO DATA;


--
-- Name: conference_comparison; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.conference_comparison AS
 SELECT conference,
    season,
    member_count,
    avg_wins,
    avg_sp_rating,
    median_sp_rating,
    best_team,
    best_team_sp,
    worst_team,
    worst_team_sp,
    std_dev_sp,
    avg_epa_per_play,
    avg_success_rate,
    avg_recruiting_rank,
    total_blue_chips,
    avg_blue_chip_ratio,
    non_conf_win_pct,
    ranked_team_count,
    avg_sp_pctl,
    avg_epa_pctl,
    avg_recruiting_pctl,
    non_conf_win_pct_pctl
   FROM marts.conference_comparison cc;


