CREATE MATERIALIZED VIEW marts.core_ratings AS
 SELECT year AS season,
    team,
    conference,
    round((overall)::numeric, 2) AS overall,
    round((offense)::numeric, 2) AS offense,
    round((defense)::numeric, 2) AS defense,
    offense_plays,
    defense_plays,
    through_week,
    through_season_type,
    model_version,
    rank() OVER (PARTITION BY year ORDER BY r.overall DESC NULLS LAST) AS overall_rank,
    rank() OVER (PARTITION BY year ORDER BY r.offense DESC NULLS LAST) AS offense_rank,
    rank() OVER (PARTITION BY year ORDER BY r.defense) AS defense_rank
   FROM ratings.core_ratings r
  WITH NO DATA;


