COMMENT ON VIEW api.core_ratings IS 'CFBD CORE ratings by team-season (2016+): overall/offense/defense with in-season overall_rank/offense_rank/defense_rank (defense ranked ascending -- lower is better) and through_week as-of markers. Backed by marts.core_ratings.';


--
-- Name: expected_points; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.expected_points AS
 SELECT era,
    state,
    ("substring"(state, 'd(\d)'::text))::integer AS down,
    split_part(state, '|'::text, 2) AS distance_bucket,
    ("substring"(state, 'z(\d+)'::text))::integer AS field_zone,
    (((("substring"(state, 'z(\d+)'::text))::integer - 1) * 10) + 1) AS yards_to_goal_min,
    LEAST((("substring"(state, 'z(\d+)'::text))::integer * 10), 99) AS yards_to_goal_max,
    n_obs,
    ep_drive,
    ep_net,
    p_td,
    p_fg,
    p_punt,
    p_turnover,
    se_boot,
    computed_at
   FROM analytics.ep_states;


--
-- Name: VIEW expected_points; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.expected_points IS 'House expected points per drive state and era (Goldner-basis drive EP from the play-by-play Markov chain, with game-cluster bootstrap SEs). ep_net NULL until the net next-score basis lands (P2). down=4 rows are go-for-it-conditional. Backed by analytics.ep_states; see docs/handoffs/2026-08-08-expected-points-handoff.md.';


