--
-- Name: game_detail; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.game_detail AS
 WITH consensus_lines AS (
         SELECT DISTINCT ON (lines.game_id) lines.game_id,
            lines.spread,
            lines.over_under,
            lines.provider
           FROM betting.lines
          ORDER BY lines.game_id,
                CASE
                    WHEN ((lines.provider)::text = 'consensus'::text) THEN 0
                    ELSE 1
                END, lines.provider
        )
 SELECT g.id AS game_id,
    g.season,
    g.week,
    g.season_type,
    g.start_date,
    g.start_time_tbd,
    g.completed,
    g.neutral_site,
    g.conference_game,
    g.home_team,
    g.home_conference,
    g.home_points,
    g.home_pregame_elo,
    home_epa.epa_per_play AS home_epa,
    home_epa.success_rate AS home_success_rate,
    g.away_team,
    g.away_conference,
    g.away_points,
    g.away_pregame_elo,
    away_epa.epa_per_play AS away_epa,
    away_epa.success_rate AS away_success_rate,
        CASE
            WHEN (g.home_points > g.away_points) THEN g.home_team
            WHEN (g.away_points > g.home_points) THEN g.away_team
            ELSE NULL::character varying
        END AS winner,
    abs((g.home_points - g.away_points)) AS point_diff,
    cl.spread AS home_spread,
    cl.over_under,
    cl.provider AS line_provider,
        CASE
            WHEN ((cl.spread IS NOT NULL) AND g.completed) THEN
            CASE
                WHEN (((g.home_points - g.away_points))::double precision > (('-1'::integer)::double precision * cl.spread)) THEN 'home_covered'::text
                WHEN (((g.home_points - g.away_points))::double precision < (('-1'::integer)::double precision * cl.spread)) THEN 'away_covered'::text
                ELSE 'push'::text
            END
            ELSE NULL::text
        END AS spread_result,
        CASE
            WHEN ((cl.over_under IS NOT NULL) AND g.completed) THEN
            CASE
                WHEN (((g.home_points + g.away_points))::double precision > cl.over_under) THEN 'over'::text
                WHEN (((g.home_points + g.away_points))::double precision < cl.over_under) THEN 'under'::text
                ELSE 'push'::text
            END
            ELSE NULL::text
        END AS ou_result,
    wp.home_win_probability AS pregame_home_win_prob,
    g.venue,
    g.venue_id,
    g.attendance,
    g.excitement_index
   FROM ((((core.games g
     LEFT JOIN consensus_lines cl ON ((cl.game_id = g.id)))
     LEFT JOIN metrics.pregame_win_probability wp ON ((wp.game_id = g.id)))
     LEFT JOIN marts._game_epa_calc home_epa ON (((home_epa.game_id = g.id) AND ((home_epa.team)::text = (g.home_team)::text))))
     LEFT JOIN marts._game_epa_calc away_epa ON (((away_epa.game_id = g.id) AND ((away_epa.team)::text = (g.away_team)::text))));


--
-- Name: VIEW game_detail; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.game_detail IS 'Single game detail with teams, betting lines, EPA, and results';


