--
-- Name: game_line_scores; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.game_line_scores AS
 SELECT g.id AS game_id,
    g.season,
    home_q1.value AS home_q1,
    home_q2.value AS home_q2,
    home_q3.value AS home_q3,
    home_q4.value AS home_q4,
    home_ot.ot_total AS home_ot,
    away_q1.value AS away_q1,
    away_q2.value AS away_q2,
    away_q3.value AS away_q3,
    away_q4.value AS away_q4,
    away_ot.ot_total AS away_ot
   FROM ((((((((((core.games g
     LEFT JOIN LATERAL ( SELECT games__home_line_scores.value
           FROM core.games__home_line_scores
          WHERE (((games__home_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__home_line_scores._dlt_list_idx = 0))) home_q1 ON (true))
     LEFT JOIN LATERAL ( SELECT games__home_line_scores.value
           FROM core.games__home_line_scores
          WHERE (((games__home_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__home_line_scores._dlt_list_idx = 1))) home_q2 ON (true))
     LEFT JOIN LATERAL ( SELECT games__home_line_scores.value
           FROM core.games__home_line_scores
          WHERE (((games__home_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__home_line_scores._dlt_list_idx = 2))) home_q3 ON (true))
     LEFT JOIN LATERAL ( SELECT games__home_line_scores.value
           FROM core.games__home_line_scores
          WHERE (((games__home_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__home_line_scores._dlt_list_idx = 3))) home_q4 ON (true))
     LEFT JOIN LATERAL ( SELECT sum(games__home_line_scores.value) AS ot_total
           FROM core.games__home_line_scores
          WHERE (((games__home_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__home_line_scores._dlt_list_idx >= 4))) home_ot ON (true))
     LEFT JOIN LATERAL ( SELECT games__away_line_scores.value
           FROM core.games__away_line_scores
          WHERE (((games__away_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__away_line_scores._dlt_list_idx = 0))) away_q1 ON (true))
     LEFT JOIN LATERAL ( SELECT games__away_line_scores.value
           FROM core.games__away_line_scores
          WHERE (((games__away_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__away_line_scores._dlt_list_idx = 1))) away_q2 ON (true))
     LEFT JOIN LATERAL ( SELECT games__away_line_scores.value
           FROM core.games__away_line_scores
          WHERE (((games__away_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__away_line_scores._dlt_list_idx = 2))) away_q3 ON (true))
     LEFT JOIN LATERAL ( SELECT games__away_line_scores.value
           FROM core.games__away_line_scores
          WHERE (((games__away_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__away_line_scores._dlt_list_idx = 3))) away_q4 ON (true))
     LEFT JOIN LATERAL ( SELECT sum(games__away_line_scores.value) AS ot_total
           FROM core.games__away_line_scores
          WHERE (((games__away_line_scores._dlt_parent_id)::text = (g._dlt_id)::text) AND (games__away_line_scores._dlt_list_idx >= 4))) away_ot ON (true));


