     JOIN core.game_player_stats__teams__categories__types types ON (((types._dlt_parent_id)::text = (cats._dlt_id)::text)))
     JOIN core.game_player_stats__teams__categories__types__athletes athletes ON (((athletes._dlt_parent_id)::text = (types._dlt_id)::text)));


