--
-- Name: game_predictions; Type: TABLE; Schema: predictions; Owner: -
--

CREATE TABLE predictions.game_predictions (
    prediction_id bigint NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    prediction_date date DEFAULT ((now() AT TIME ZONE 'utc'::text))::date NOT NULL,
    model_version text NOT NULL,
    game_id bigint NOT NULL,
    season bigint,
    week bigint,
    season_type character varying,
    home_team character varying NOT NULL,
    away_team character varying NOT NULL,
    neutral_site boolean,
    home_elo_pregame numeric(8,2),
    away_elo_pregame numeric(8,2),
    elo_margin numeric(6,2),
    epa_margin numeric(6,2),
    expected_home_margin numeric(6,2),
    home_win_prob numeric(5,4),
    market_provider character varying,
    market_home_margin numeric(6,2),
    market_spread numeric(6,2),
    market_captured_at timestamp with time zone,
    edge numeric(6,2),
    edge_pick character varying,
    evaluation_mode text NOT NULL,
    created_at timestamp with time zone,
    published_at timestamp with time zone,
    simulated_as_of_at timestamp with time zone,
    experiment_label text,
    fit_id text,
    input_hash text,
    input_snapshot jsonb,
    CONSTRAINT game_predictions_provenance_check CHECK ((((evaluation_mode = 'legacy_unknown'::text) AND (created_at IS NULL) AND (published_at IS NULL) AND (simulated_as_of_at IS NULL) AND (experiment_label IS NULL) AND (fit_id IS NULL) AND (input_hash IS NULL) AND (input_snapshot IS NULL)) OR ((evaluation_mode = ANY (ARRAY['published_forecast'::text, 'walk_forward_reconstruction'::text, 'hindsight_experiment'::text])) AND (created_at IS NOT NULL) AND (fit_id IS NOT NULL) AND (fit_id ~ '^[0-9a-f]{64}$'::text) AND (input_hash IS NOT NULL) AND (input_hash ~ '^[0-9a-f]{64}$'::text) AND (input_snapshot IS NOT NULL) AND (jsonb_typeof(input_snapshot) = 'object'::text) AND (((evaluation_mode = 'published_forecast'::text) AND (published_at IS NOT NULL) AND (published_at = created_at) AND (simulated_as_of_at IS NULL) AND (experiment_label IS NULL)) OR ((evaluation_mode = 'walk_forward_reconstruction'::text) AND (published_at IS NULL) AND (simulated_as_of_at IS NOT NULL) AND (experiment_label IS NULL)) OR ((evaluation_mode = 'hindsight_experiment'::text) AND (published_at IS NULL) AND (simulated_as_of_at IS NOT NULL) AND (experiment_label IS NOT NULL) AND (length(btrim(experiment_label)) > 0))))))
);


--
-- Name: TABLE game_predictions; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON TABLE predictions.game_predictions IS 'Immutable prediction ledger keyed by prediction_id. New rows explicitly distinguish published_forecast, walk_forward_reconstruction and hindsight_experiment. Legacy rows retain unknown provenance; prediction_date and computed_at are not publication evidence.';


--
-- Name: COLUMN game_predictions.created_at; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.game_predictions.created_at IS 'Actual database INSERT statement time for new ledger entries; NULL for unverifiable legacy rows.';


--
-- Name: COLUMN game_predictions.published_at; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.game_predictions.published_at IS 'Database write-time publication, set only for published_forecast. Prospective scoring requires known kickoff and published_at strictly before kickoff.';


--
-- Name: COLUMN game_predictions.simulated_as_of_at; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.game_predictions.simulated_as_of_at IS 'Nominal reconstructed kickoff, not evidence that corrected inputs or closing market lines were available then.';


