-- Name: game_predictions; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.game_predictions AS
 SELECT DISTINCT ON (game_id, model_version) prediction_id,
    computed_at,
    prediction_date,
    model_version,
    game_id,
    season,
    week,
    season_type,
    home_team,
    away_team,
    neutral_site,
    home_elo_pregame,
    away_elo_pregame,
    elo_margin,
    epa_margin,
    expected_home_margin,
    home_win_prob,
    market_provider,
    market_home_margin,
    market_spread,
    market_captured_at,
    edge,
    edge_pick,
    evaluation_mode,
    created_at,
    published_at,
    simulated_as_of_at,
    experiment_label,
    fit_id,
    input_hash
   FROM predictions.game_predictions
  WHERE (evaluation_mode = 'published_forecast'::text)
  ORDER BY game_id, model_version, published_at DESC, prediction_id DESC;


