--
-- Name: matchup; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.matchup AS
 WITH h2h_games AS (
         SELECT LEAST(games.home_team, games.away_team) AS team1,
            GREATEST(games.home_team, games.away_team) AS team2,
            games.season,
            games.week,
            games.start_date,
            games.home_team,
            games.away_team,
            games.home_points,
            games.away_points,
            games.venue,
                CASE
                    WHEN (games.home_points > games.away_points) THEN games.home_team
                    WHEN (games.away_points > games.home_points) THEN games.away_team
                    ELSE NULL::character varying
                END AS winner
           FROM core.games
          WHERE (games.completed = true)
        ), h2h_summary AS (
         SELECT h2h_games.team1,
            h2h_games.team2,
            count(*) AS total_games,
            sum(
                CASE
                    WHEN ((h2h_games.winner)::text = (h2h_games.team1)::text) THEN 1
                    ELSE 0
                END) AS team1_wins,
            sum(
                CASE
                    WHEN ((h2h_games.winner)::text = (h2h_games.team2)::text) THEN 1
                    ELSE 0
                END) AS team2_wins,
            sum(
                CASE
                    WHEN (h2h_games.winner IS NULL) THEN 1
                    ELSE 0
                END) AS ties,
            min(h2h_games.season) AS first_meeting,
            max(h2h_games.season) AS last_meeting
           FROM h2h_games
          GROUP BY h2h_games.team1, h2h_games.team2
        ), recent_games AS (
         SELECT h2h_games.team1,
            h2h_games.team2,
            array_agg(jsonb_build_object('season', h2h_games.season, 'winner', h2h_games.winner, 'home_team', h2h_games.home_team, 'home_points', h2h_games.home_points, 'away_points', h2h_games.away_points) ORDER BY h2h_games.season DESC) FILTER (WHERE (h2h_games.season >= 2014)) AS recent_results
           FROM h2h_games
          GROUP BY h2h_games.team1, h2h_games.team2
        )
 SELECT h.team1,
    h.team2,
    h.total_games,
    h.team1_wins,
    h.team2_wins,
    h.ties,
    h.first_meeting,
    h.last_meeting,
    r.recent_results,
    t1.season AS team1_season,
    t1.wins AS team1_wins_season,
    t1.losses AS team1_losses_season,
    t1.sp_rank AS team1_sp_rank,
    e1.epa_per_play AS team1_epa,
    e1.epa_tier AS team1_epa_tier,
    t2.season AS team2_season,
    t2.wins AS team2_wins_season,
    t2.losses AS team2_losses_season,
    t2.sp_rank AS team2_sp_rank,
    e2.epa_per_play AS team2_epa,
    e2.epa_tier AS team2_epa_tier
   FROM (((((h2h_summary h
     LEFT JOIN recent_games r ON ((((r.team1)::text = (h.team1)::text) AND ((r.team2)::text = (h.team2)::text))))
     LEFT JOIN LATERAL ( SELECT team_season_summary.team,
            team_season_summary.conference,
            team_season_summary.season,
            team_season_summary.games,
            team_season_summary.wins,
            team_season_summary.losses,
            team_season_summary.conf_wins,
            team_season_summary.conf_losses,
            team_season_summary.ppg,
            team_season_summary.opp_ppg,
            team_season_summary.avg_margin,
            team_season_summary.sp_rating,
            team_season_summary.sp_rank,
            team_season_summary.sp_offense,
            team_season_summary.sp_defense,
            team_season_summary.elo,
            team_season_summary.fpi,
            team_season_summary.core_overall,
            team_season_summary.core_offense,
            team_season_summary.core_defense,
            team_season_summary.recruiting_rank,
            team_season_summary.recruiting_points
           FROM marts.team_season_summary
          WHERE ((team_season_summary.team)::text = (h.team1)::text)
          ORDER BY team_season_summary.season DESC
         LIMIT 1) t1 ON (true))
     LEFT JOIN LATERAL ( SELECT team_season_summary.team,
            team_season_summary.conference,
            team_season_summary.season,
            team_season_summary.games,
            team_season_summary.wins,
            team_season_summary.losses,
            team_season_summary.conf_wins,
            team_season_summary.conf_losses,
            team_season_summary.ppg,
            team_season_summary.opp_ppg,
            team_season_summary.avg_margin,
            team_season_summary.sp_rating,
            team_season_summary.sp_rank,
            team_season_summary.sp_offense,
            team_season_summary.sp_defense,
            team_season_summary.elo,
            team_season_summary.fpi,
            team_season_summary.core_overall,
            team_season_summary.core_offense,
            team_season_summary.core_defense,
            team_season_summary.recruiting_rank,
            team_season_summary.recruiting_points
           FROM marts.team_season_summary
          WHERE ((team_season_summary.team)::text = (h.team2)::text)
          ORDER BY team_season_summary.season DESC
         LIMIT 1) t2 ON (true))
     LEFT JOIN LATERAL ( SELECT team_epa_season.team,
            team_epa_season.season,
            team_epa_season.epa_per_play,
            team_epa_season.success_rate,
            team_epa_season.explosiveness,
            team_epa_season.epa_tier,
            team_epa_season.total_plays,
            team_epa_season.games_played
           FROM marts.team_epa_season
          WHERE ((team_epa_season.team)::text = (h.team1)::text)
          ORDER BY team_epa_season.season DESC
         LIMIT 1) e1 ON (true))
     LEFT JOIN LATERAL ( SELECT team_epa_season.team,
            team_epa_season.season,
            team_epa_season.epa_per_play,
            team_epa_season.success_rate,
            team_epa_season.explosiveness,
            team_epa_season.epa_tier,
            team_epa_season.total_plays,
            team_epa_season.games_played
           FROM marts.team_epa_season
          WHERE ((team_epa_season.team)::text = (h.team2)::text)
          ORDER BY team_epa_season.season DESC
         LIMIT 1) e2 ON (true));


--
-- Name: VIEW matchup; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.matchup IS 'Head-to-head matchup history and current season comparison';


--
-- Name: pre_game_win_probability; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.pre_game_win_probability AS
 WITH consensus_lines AS (
         SELECT DISTINCT ON (lines.game_id) lines.game_id,
            lines.spread,
            lines.over_under,
            lines.provider
           FROM betting.lines
          ORDER BY lines.game_id,
                CASE
                    WHEN ((lines.provider)::text = 'consensus'::text) THEN 0
                    ELSE 1
                END, lines.provider
        ), games AS (
         SELECT g.id AS game_id,
            (g.season)::integer AS season,
            (g.week)::integer AS week,
            g.season_type,
            g.start_date,
            COALESCE(g.completed, false) AS completed,
            g.neutral_site,
            g.conference_game,
            g.home_team,
            g.away_team,
            g.home_points,
            g.away_points,
            wp.home_win_probability AS cfbd_home_win_prob,
            cl.spread AS market_spread,
            cl.over_under AS market_over_under
           FROM ((core.games g
             LEFT JOIN metrics.pregame_win_probability wp ON ((wp.game_id = g.id)))
             LEFT JOIN consensus_lines cl ON ((cl.game_id = g.id)))
          WHERE ((g.home_team IS NOT NULL) AND (g.away_team IS NOT NULL))
        ), ratings AS (
         SELECT gm.game_id,
            gm.season,
            gm.week,
            gm.season_type,
            gm.start_date,
            gm.completed,
            gm.neutral_site,
            gm.conference_game,
            gm.home_team,
            gm.away_team,
            gm.home_points,
            gm.away_points,
            gm.cfbd_home_win_prob,
            gm.market_spread,
            gm.market_over_under,
            (home_elo.elo)::numeric AS home_elo_rating,
            (away_elo.elo)::numeric AS away_elo_rating,
            (home_sp.rating)::numeric AS home_sp_rating,
            (away_sp.rating)::numeric AS away_sp_rating
           FROM ((((games gm
             LEFT JOIN LATERAL ( SELECT e.elo,
                    e.year
                   FROM ratings.elo_ratings e
                  WHERE (((e.team)::text = (gm.home_team)::text) AND (e.year <= gm.season))
                  ORDER BY
                        CASE
                            WHEN (e.year = gm.season) THEN 0
                            ELSE 1
                        END, e.year DESC
                 LIMIT 1) home_elo ON (true))
             LEFT JOIN LATERAL ( SELECT e.elo,
                    e.year
                   FROM ratings.elo_ratings e
                  WHERE (((e.team)::text = (gm.away_team)::text) AND (e.year <= gm.season))
                  ORDER BY
                        CASE
                            WHEN (e.year = gm.season) THEN 0
                            ELSE 1
                        END, e.year DESC
                 LIMIT 1) away_elo ON (true))
             LEFT JOIN LATERAL ( SELECT s_1.rating,
                    s_1.year
                   FROM ratings.sp_ratings s_1
                  WHERE (((s_1.team)::text = (gm.home_team)::text) AND (s_1.year <= gm.season))
                  ORDER BY
                        CASE
                            WHEN (s_1.year = gm.season) THEN 0
                            ELSE 1
                        END, s_1.year DESC
                 LIMIT 1) home_sp ON (true))
             LEFT JOIN LATERAL ( SELECT s_1.rating,
                    s_1.year
                   FROM ratings.sp_ratings s_1
                  WHERE (((s_1.team)::text = (gm.away_team)::text) AND (s_1.year <= gm.season))
                  ORDER BY
                        CASE
                            WHEN (s_1.year = gm.season) THEN 0
                            ELSE 1
                        END, s_1.year DESC
                 LIMIT 1) away_sp ON (true))
        ), signals AS (
         SELECT r.game_id,
            r.season,
            r.week,
            r.season_type,
            r.start_date,
            r.completed,
            r.neutral_site,
            r.conference_game,
            r.home_team,
            r.away_team,
            r.home_points,
            r.away_points,
            r.cfbd_home_win_prob,
            r.market_spread,
            r.market_over_under,
            r.home_elo_rating,
            r.away_elo_rating,
            r.home_sp_rating,
            r.away_sp_rating,
            (r.home_elo_rating - r.away_elo_rating) AS elo_diff,
            (r.home_sp_rating - r.away_sp_rating) AS sp_diff,
                CASE
                    WHEN ((r.home_elo_rating IS NOT NULL) AND (r.away_elo_rating IS NOT NULL)) THEN (1.0 / (1.0 + power(10.0, (- ((r.home_elo_rating - r.away_elo_rating) / 400.0)))))
                    ELSE NULL::numeric
                END AS elo_home_win_prob,
                CASE
                    WHEN ((r.home_sp_rating IS NOT NULL) AND (r.away_sp_rating IS NOT NULL)) THEN (1.0 / (1.0 + exp((- ((r.home_sp_rating - r.away_sp_rating) / 7.5)))))
                    ELSE NULL::numeric
                END AS sp_home_win_prob,
                CASE
                    WHEN (r.market_spread IS NOT NULL) THEN ((1.0)::double precision / ((1.0)::double precision + exp((((r.market_spread)::numeric / 6.5))::double precision)))
                    ELSE NULL::double precision
                END AS market_home_win_prob
           FROM ratings r
        ), blended AS (
         SELECT s_1.game_id,
            s_1.season,
            s_1.week,
            s_1.season_type,
            s_1.start_date,
            s_1.completed,
            s_1.neutral_site,
            s_1.conference_game,
            s_1.home_team,
            s_1.away_team,
            s_1.home_points,
            s_1.away_points,
            s_1.cfbd_home_win_prob,
            s_1.market_spread,
            s_1.market_over_under,
            s_1.home_elo_rating,
            s_1.away_elo_rating,
            s_1.home_sp_rating,
            s_1.away_sp_rating,
            s_1.elo_diff,
            s_1.sp_diff,
            s_1.elo_home_win_prob,
            s_1.sp_home_win_prob,
            s_1.market_home_win_prob,
            (((
                CASE
                    WHEN (s_1.cfbd_home_win_prob IS NOT NULL) THEN 0.50
                    ELSE 0.00
                END +
                CASE
                    WHEN (s_1.market_home_win_prob IS NOT NULL) THEN 0.25
                    ELSE 0.00
                END) +
                CASE
                    WHEN (s_1.elo_home_win_prob IS NOT NULL) THEN 0.15
                    ELSE 0.00
                END) +
                CASE
                    WHEN (s_1.sp_home_win_prob IS NOT NULL) THEN 0.10
                    ELSE 0.00
                END) AS total_weight,
            ((((COALESCE(s_1.cfbd_home_win_prob, (0.0)::double precision) * (0.50)::double precision) + (COALESCE(s_1.market_home_win_prob, (0.0)::double precision) * (0.25)::double precision)) + ((COALESCE(s_1.elo_home_win_prob, 0.0) * 0.15))::double precision) + ((COALESCE(s_1.sp_home_win_prob, 0.0) * 0.10))::double precision) AS weighted_prob_sum
           FROM signals s_1
        ), scored AS (
         SELECT b.game_id,
            b.season,
            b.week,
            b.season_type,
            b.start_date,
            b.completed,
            b.neutral_site,
            b.conference_game,
            b.home_team,
            b.away_team,
            b.home_points,
            b.away_points,
            b.cfbd_home_win_prob,
            b.market_spread,
            b.market_over_under,
            b.home_elo_rating,
            b.away_elo_rating,
            b.home_sp_rating,
            b.away_sp_rating,
            b.elo_diff,
            b.sp_diff,
            b.elo_home_win_prob,
            b.sp_home_win_prob,
            b.market_home_win_prob,
            b.total_weight,
            b.weighted_prob_sum,
            GREATEST(0.01, LEAST(0.99,
                CASE
                    WHEN (b.total_weight > (0)::numeric) THEN ((b.weighted_prob_sum / (b.total_weight)::double precision))::numeric
                    ELSE 0.50
                END)) AS home_prob
           FROM blended b
        )
 SELECT game_id,
    season,
    week,
    season_type,
    start_date,
    completed,
    neutral_site,
    conference_game,
    home_team,
    away_team,
    home_points,
    away_points,
    market_spread,
    market_over_under,
    home_elo_rating,
    away_elo_rating,
    elo_diff,
    home_sp_rating,
    away_sp_rating,
    sp_diff,
    round((cfbd_home_win_prob)::numeric, 4) AS cfbd_home_win_prob,
    round((market_home_win_prob)::numeric, 4) AS market_home_win_prob,
    round(elo_home_win_prob, 4) AS elo_home_win_prob,
    round(sp_home_win_prob, 4) AS sp_home_win_prob,
    round(home_prob, 4) AS home_win_probability,
    round((1.0 - home_prob), 4) AS away_win_probability,
        CASE
            WHEN (home_prob >= 0.50) THEN home_team
            ELSE away_team
        END AS projected_winner,
    round(((home_prob - 0.50) * 24.0), 1) AS projected_margin,
        CASE
            WHEN (abs((home_prob - 0.50)) >= 0.30) THEN 'heavy_favorite'::text
            WHEN (abs((home_prob - 0.50)) >= 0.20) THEN 'strong_lean'::text
            WHEN (abs((home_prob - 0.50)) >= 0.10) THEN 'lean'::text
            ELSE 'toss_up'::text
        END AS confidence_tier,
        CASE
            WHEN (completed AND (home_points IS NOT NULL) AND (away_points IS NOT NULL)) THEN
            CASE
                WHEN (home_points > away_points) THEN 1.0
                WHEN (home_points < away_points) THEN 0.0
                ELSE 0.5
            END
            ELSE NULL::numeric
        END AS actual_home_result,
        CASE
            WHEN (completed AND (home_points IS NOT NULL) AND (away_points IS NOT NULL)) THEN round(power((home_prob -
            CASE
                WHEN (home_points > away_points) THEN 1.0
                WHEN (home_points < away_points) THEN 0.0
                ELSE 0.5
            END), (2)::numeric), 4)
            ELSE NULL::numeric
        END AS brier_loss,
    'v1_blended_cfbd_market_elo_sp'::text AS model_version
   FROM scored s
  WITH NO DATA;


--
-- Name: season_simulation_outcomes; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.season_simulation_outcomes AS
 WITH latest_season AS (
         SELECT max(pre_game_win_probability.season) AS season
           FROM marts.pre_game_win_probability
          WHERE ((COALESCE(pre_game_win_probability.season_type, 'regular'::character varying))::text = 'regular'::text)
        ), team_games AS (
         SELECT p.season,
            p.game_id,
            p.week,
            p.completed,
            p.home_team AS team,
            p.away_team AS opponent,
            p.home_win_probability AS win_probability,
                CASE
                    WHEN (p.completed AND (p.home_points IS NOT NULL) AND (p.away_points IS NOT NULL)) THEN
                    CASE
                        WHEN (p.home_points > p.away_points) THEN 1.0
                        WHEN (p.home_points < p.away_points) THEN 0.0
                        ELSE 0.5
                    END
                    ELSE NULL::numeric
                END AS actual_win
           FROM (marts.pre_game_win_probability p
             JOIN latest_season ls ON ((ls.season = p.season)))
          WHERE ((COALESCE(p.season_type, 'regular'::character varying))::text = 'regular'::text)
        UNION ALL
         SELECT p.season,
            p.game_id,
            p.week,
            p.completed,
            p.away_team AS team,
            p.home_team AS opponent,
            (1.0 - p.home_win_probability) AS win_probability,
                CASE
                    WHEN (p.completed AND (p.home_points IS NOT NULL) AND (p.away_points IS NOT NULL)) THEN
                    CASE
                        WHEN (p.away_points > p.home_points) THEN 1.0
                        WHEN (p.away_points < p.home_points) THEN 0.0
                        ELSE 0.5
                    END
                    ELSE NULL::numeric
                END AS actual_win
           FROM (marts.pre_game_win_probability p
             JOIN latest_season ls ON ((ls.season = p.season)))
          WHERE ((COALESCE(p.season_type, 'regular'::character varying))::text = 'regular'::text)
        ), team_set AS (
         SELECT DISTINCT team_games.season,
            team_games.team
           FROM team_games
        ), simulations AS (
         SELECT generate_series(1, 2000) AS sim_id
        ), team_sim_wins AS (
         SELECT ts.season,
            ts.team,
            s_1.sim_id,
            sum(
                CASE
                    WHEN (tg.completed AND (tg.actual_win IS NOT NULL)) THEN tg.actual_win
                    WHEN (tg.win_probability IS NULL) THEN 0.5
                    WHEN (random() < (tg.win_probability)::double precision) THEN 1.0
                    ELSE 0.0
                END) AS simulated_wins,
            (count(*))::integer AS total_games
           FROM ((team_set ts
             CROSS JOIN simulations s_1)
             JOIN team_games tg ON (((tg.season = ts.season) AND ((tg.team)::text = (ts.team)::text))))
          GROUP BY ts.season, ts.team, s_1.sim_id
        ), summary AS (
         SELECT team_sim_wins.season,
            team_sim_wins.team,
            max(team_sim_wins.total_games) AS scheduled_games,
            round(avg(team_sim_wins.simulated_wins), 2) AS expected_wins,
            round(avg(((team_sim_wins.total_games)::numeric - team_sim_wins.simulated_wins)), 2) AS expected_losses,
            round(stddev_pop(team_sim_wins.simulated_wins), 2) AS wins_stddev,
            round((percentile_cont((0.10)::double precision) WITHIN GROUP (ORDER BY ((team_sim_wins.simulated_wins)::double precision)))::numeric, 2) AS wins_p10,
            round((percentile_cont((0.50)::double precision) WITHIN GROUP (ORDER BY ((team_sim_wins.simulated_wins)::double precision)))::numeric, 2) AS wins_p50,
            round((percentile_cont((0.90)::double precision) WITHIN GROUP (ORDER BY ((team_sim_wins.simulated_wins)::double precision)))::numeric, 2) AS wins_p90,
            round(avg(((team_sim_wins.simulated_wins >= 6.0))::integer), 4) AS bowl_eligibility_prob,
            round(avg(((team_sim_wins.simulated_wins >= 10.0))::integer), 4) AS ten_plus_win_prob,
            round(avg(((team_sim_wins.simulated_wins >= 12.0))::integer), 4) AS perfect_regular_season_prob,
            (count(*))::integer AS simulation_count
           FROM team_sim_wins
          GROUP BY team_sim_wins.season, team_sim_wins.team
        ), distribution_counts AS (
         SELECT team_sim_wins.season,
            team_sim_wins.team,
            team_sim_wins.simulated_wins,
            (count(*))::integer AS scenario_count
           FROM team_sim_wins
          GROUP BY team_sim_wins.season, team_sim_wins.team, team_sim_wins.simulated_wins
        ), distribution AS (
         SELECT dc.season,
            dc.team,
            jsonb_object_agg((dc.simulated_wins)::text, round(((dc.scenario_count)::numeric / (NULLIF(s_1.simulation_count, 0))::numeric), 4) ORDER BY dc.simulated_wins) AS win_distribution
           FROM (distribution_counts dc
             JOIN summary s_1 ON (((s_1.season = dc.season) AND ((s_1.team)::text = (dc.team)::text))))
          GROUP BY dc.season, dc.team
        )
 SELECT s.season,
    s.team,
    s.scheduled_games,
    s.expected_wins,
    s.expected_losses,
    s.wins_stddev,
    s.wins_p10,
    s.wins_p50,
    s.wins_p90,
    s.bowl_eligibility_prob,
    s.ten_plus_win_prob,
    s.perfect_regular_season_prob,
    d.win_distribution,
    s.simulation_count,
    'v1_monte_carlo_2000'::text AS simulation_method
   FROM (summary s
     LEFT JOIN distribution d ON (((d.season = s.season) AND ((d.team)::text = (s.team)::text))))
  WITH NO DATA;


--
-- Name: matchup_forecast; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.matchup_forecast WITH (security_invoker='false') AS
 SELECT p.game_id,
    p.season,
    p.week,
    p.season_type,
    p.start_date,
    p.completed,
    p.neutral_site,
    p.conference_game,
    p.home_team,
    p.away_team,
    p.market_spread,
    p.market_over_under,
    p.home_win_probability,
    p.away_win_probability,
    p.projected_winner,
    p.projected_margin,
    p.confidence_tier,
    p.cfbd_home_win_prob,
    p.market_home_win_prob,
    p.elo_home_win_prob,
    p.sp_home_win_prob,
    p.model_version,
    p.home_points,
    p.away_points,
        CASE
            WHEN (p.completed AND (p.home_points IS NOT NULL) AND (p.away_points IS NOT NULL)) THEN
            CASE
                WHEN (p.home_points > p.away_points) THEN p.home_team
                WHEN (p.away_points > p.home_points) THEN p.away_team
                ELSE NULL::character varying
            END
            ELSE NULL::character varying
        END AS actual_winner,
    p.brier_loss,
    home_out.expected_wins AS home_expected_wins,
    home_out.bowl_eligibility_prob AS home_bowl_eligibility_prob,
    home_out.ten_plus_win_prob AS home_ten_plus_win_prob,
    away_out.expected_wins AS away_expected_wins,
    away_out.bowl_eligibility_prob AS away_bowl_eligibility_prob,
    away_out.ten_plus_win_prob AS away_ten_plus_win_prob
   FROM ((marts.pre_game_win_probability p
     LEFT JOIN marts.season_simulation_outcomes home_out ON (((home_out.season = p.season) AND ((home_out.team)::text = (p.home_team)::text))))
     LEFT JOIN marts.season_simulation_outcomes away_out ON (((away_out.season = p.season) AND ((away_out.team)::text = (p.away_team)::text))));


--
-- Name: VIEW matchup_forecast; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.matchup_forecast IS 'Phase 1 matchup forecast with blended pregame win probabilities and team season outlook context. SECURITY INVOKER + read-only for anon (matches the 2026-02-07 hardening pattern).';


--
-- Name: model_backtest; Type: TABLE; Schema: predictions; Owner: -
--

CREATE TABLE predictions.model_backtest (
    backtest_id bigint NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    run_date date DEFAULT ((now() AT TIME ZONE 'utc'::text))::date NOT NULL,
    model_version text NOT NULL,
    feature_build_version text,
    scope text NOT NULL,
    season_start bigint NOT NULL,
    season_end bigint NOT NULL,
    seasons_covered bigint[] NOT NULL,
    train_through_min bigint NOT NULL,
    train_through_max bigint NOT NULL,
    n_sims bigint NOT NULL,
    seed bigint NOT NULL,
    strength_share numeric(4,3) NOT NULL,
    max_games_played_to_date bigint NOT NULL,
    games_dropped_outcome_dependent bigint NOT NULL,
    n bigint NOT NULL,
    win_mae numeric(6,3),
    rmse numeric(6,3),
    bias numeric(6,3),
    coverage numeric(5,4),
    baseline_prior_mae numeric(6,3),
    baseline_flat_mae numeric(6,3),
    resid_p05 numeric(6,3),
    resid_p10 numeric(6,3),
    resid_p25 numeric(6,3),
    resid_p50 numeric(6,3),
    resid_p75 numeric(6,3),
    resid_p90 numeric(6,3),
    resid_p95 numeric(6,3),
    bowl_brier numeric(6,5),
    ten_plus_brier numeric(6,5),
    calibration jsonb,
    respectable_win_mae numeric(4,2)
);


--
-- Name: TABLE model_backtest; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON TABLE predictions.model_backtest IS 'Append-only walk-forward preseason backtest snapshots: one immutable row per (model_version, UTC run_date, scope, season_start, season_end, strength_share), same-day ON CONFLICT DO UPDATE for intra-day convergence only. Measures season-win projection accuracy by re-scoring every game of season S from each team''s week-1 features.team_week vector using the frozen S-1 fit. Written by scripts/backtest_preseason.py; read downstream through api.model_backtest.';


--
-- Name: COLUMN model_backtest.seasons_covered; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.model_backtest.seasons_covered IS 'Seasons that actually contributed team-season rows, ascending. May be shorter than [season_start, season_end] when a season had no frozen S-1 fit or too few prior residuals for a sigma estimate. Seasons scored only to seed sigma are not listed -- they contribute no metrics.';


--
-- Name: COLUMN model_backtest.max_games_played_to_date; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.model_backtest.max_games_played_to_date IS 'Largest games_played_to_date on any joined week-1 vector. 0 is the honest expectation; above 0 means some "week-1" row already contained that season''s own games and every error metric on this row is understated.';


--
-- Name: COLUMN model_backtest.n; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.model_backtest.n IS 'Team-seasons compared. Named to match the BACKTEST_GATE log line so a row and its log can be diffed by eye.';


--
-- Name: COLUMN model_backtest.coverage; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.model_backtest.coverage IS 'Share of teams whose actual wins landed inside the simulated [p10, p90]; nominal 0.80. Materially below means the projection claims more confidence than it has; materially above means it is too wide to be useful.';


--
-- Name: COLUMN model_backtest.resid_p10; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.model_backtest.resid_p10 IS 'p10 of (actual - projected) wins. With resid_p90 this is the empirical 80% interval around a projection: [projected + resid_p10, projected + resid_p90]. It is ASYMMETRIC and it is NOT +/- win_mae -- a +/-MAE band spans only ~58% for a normal error.';


--
-- Name: COLUMN model_backtest.calibration; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.model_backtest.calibration IS 'Reliability buckets per published probability: {"p_bowl_eligible": [{bucket, n, mean_predicted, observed}, ...], "p_ten_plus": [...]}. Empty buckets are omitted rather than reported as 0/0.';


--
-- Name: COLUMN model_backtest.respectable_win_mae; Type: COMMENT; Schema: predictions; Owner: -
--

COMMENT ON COLUMN predictions.model_backtest.respectable_win_mae IS 'The advisory bar in force for this run (plan 4.5). The verdict is NOT stored: a stored judgement goes stale when the bar is revised, while the measurement does not. Compute win_mae <= respectable_win_mae, or apply your own bar.';


--
-- Name: model_backtest; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.model_backtest AS
 SELECT DISTINCT ON (model_version, scope, season_start, season_end, strength_share) backtest_id,
    computed_at,
    run_date,
    model_version,
    feature_build_version,
    scope,
    season_start,
    season_end,
    seasons_covered,
    train_through_min,
    train_through_max,
    n_sims,
    seed,
    strength_share,
    max_games_played_to_date,
    games_dropped_outcome_dependent,
    n,
    win_mae,
    rmse,
    bias,
    coverage,
    baseline_prior_mae,
    baseline_flat_mae,
    (win_mae < baseline_prior_mae) AS beats_prior_baseline,
    (win_mae < baseline_flat_mae) AS beats_flat_baseline,
    resid_p05,
    resid_p10,
    resid_p25,
    resid_p50,
    resid_p75,
    resid_p90,
    resid_p95,
    bowl_brier,
    ten_plus_brier,
    calibration,
    respectable_win_mae
   FROM predictions.model_backtest
  ORDER BY model_version, scope, season_start, season_end, strength_share, run_date DESC;


--
-- Name: VIEW model_backtest; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.model_backtest IS 'Latest walk-forward preseason backtest per (model_version, scope, season_start, season_end, strength_share), from the append-only predictions.model_backtest log. Columns: backtest_id, computed_at, run_date, model_version, feature_build_version, scope, season_start, season_end, seasons_covered, train_through_min, train_through_max, n_sims, seed, strength_share, max_games_played_to_date, games_dropped_outcome_dependent, n, win_mae, rmse, bias, coverage, baseline_prior_mae, baseline_flat_mae, beats_prior_baseline, beats_flat_baseline, resid_p05/p10/p25/p50/p75/p90/p95, bowl_brier, ten_plus_brier, calibration, respectable_win_mae. Measures season-win projection accuracy by re-scoring every game of season S from each team''s week-1 feature vector with the frozen S-1 fit, then simulating; n counts TEAM-SEASONS, not games. Use resid_p10/resid_p90 as an ASYMMETRIC 80% interval around projected_wins -- NOT +/- win_mae, which spans only ~58% for a normal error. scope=''fbs'' is the default reporting population; ''all_divisions'' includes FCS/D2, whose slates run long because CFBD labels their playoff bracket season_type=''regular''. seasons_covered may be shorter than [season_start, season_end] when a season had no frozen S-1 fit. max_games_played_to_date above 0 means some week-1 vector was not truly preseason and the errors are understated. NO ROW for a model version means it has never been backtested -- render that as unmeasured, never as an unqualified projection. Query predictions.model_backtest directly for run-by-run history.';


