-- Name: VIEW passing_charting_team_season; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.passing_charting_team_season IS 'Team-season passing charting, offense and defense sides (2025+): season, team_id, team, conference, offense_attempts, offense_completions, offense_total_air_yards, offense_average_depth_of_target, offense_air_yards_attempts_available, offense_total_yards_after_catch, offense_average_yards_after_catch, offense_yards_after_catch_attempts_available, and the defense_ equivalents. defense_* is this team''s passing DEFENSE (what opposing offenses did against them), not the opponent''s offensive row. NULL on a metric means those plays were not charted, 0 is a real observed value; the two *_attempts_available columns per side are the charting-coverage denominators. Coverage ratios per side: air-yards coverage = *_air_yards_attempts_available / *_attempts; per-catch YAC coverage = *_yards_after_catch_attempts_available / *_completions. CONTRACT: each side''s yards_after_catch_attempts_available is bounded by that side''s completions (YAC exists only on completions; live-verified 152/152 rows 2026-08-31). team_id is numeric (joins ref.teams(id)), derived from the (season, offense-name -> offense_id) mapping in stats.passing_plays; NULL when that mapping is ambiguous (never-guess; live 2026-08-31: 0 ambiguous, 152/152 mapped). Backed by marts.passing_charting_team_season.';


--
-- Name: penalty_log; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.penalty_log AS
 WITH infractions(priority, label, pattern) AS (
         VALUES (1,'Pass Interference'::text,'%pass interference%'::text), (2,'Kick Catch Interference'::text,'%kick catch%'::text), (3,'Roughing the Passer'::text,'%roughing%passer%'::text), (4,'Roughing the Kicker'::text,'%roughing%kicker%'::text), (5,'Roughing the Snapper'::text,'%roughing%snapper%'::text), (6,'Targeting'::text,'%targeting%'::text), (7,'Horse Collar'::text,'%horse collar%'::text), (8,'Face Mask'::text,'%face mask%'::text), (9,'Chop Block'::text,'%chop block%'::text), (10,'Clipping'::text,'%clipping%'::text), (11,'Intentional Grounding'::text,'%intentional grounding%'::text), (12,'False Start'::text,'%false start%'::text), (13,'Delay of Game'::text,'%delay of game%'::text), (14,'Encroachment'::text,'%encroachment%'::text), (15,'Offside'::text,'%offside%'::text), (16,'Holding'::text,'%holding%'::text), (17,'Illegal Block'::text,'%illegal block%'::text), (18,'Illegal Formation'::text,'%illegal formation%'::text), (19,'Illegal Motion'::text,'%illegal motion%'::text), (20,'Illegal Shift'::text,'%illegal shift%'::text), (21,'Illegal Substitution'::text,'%substitution%'::text), (22,'Illegal Touching'::text,'%illegal touch%'::text), (23,'Illegal Forward Pass'::text,'%illegal forward pass%'::text), (24,'Illegal Snap'::text,'%illegal snap%'::text), (25,'Ineligible Downfield'::text,'%ineligible%'::text), (26,'Unsportsmanlike Conduct'::text,'%unsportsmanlike%'::text), (27,'Personal Foul'::text,'%personal foul%'::text), (28,'Sideline Interference'::text,'%sideline interference%'::text), (29,'Too Many Men'::text,'%12 men%'::text), (30,'Too Many Men'::text,'%too many%'::text), (31,'Disqualification'::text,'%disqualification%'::text)
        ), team_idents AS (
         SELECT DISTINCT ON (teams.school) teams.school,
            replace((teams.school)::text, 'State'::text, 'St'::text) AS school_st,
            teams.abbreviation,
            teams.mascot
           FROM ref.teams
          ORDER BY teams.school, teams.classification
        ), penalty_plays AS (
         SELECT p.id AS play_id,
            p.game_id,
            p.season,
            g.week,
            g.season_type,
            p.period,
            p.down,
            p.distance,
            p.offense,
            p.defense,
            p.home,
            p.away,
            p.play_type,
            ((p.play_type)::text = 'Penalty'::text) AS is_penalty_play_type,
            p.yards_gained,
            p.ppa,
            p.play_text
           FROM (core.plays p
             JOIN core.games g ON (((p.game_id = g.id) AND (g.season = p.season))))
          WHERE (((p.play_type)::text = 'Penalty'::text) OR ((p.play_text)::text ~* 'penalt'::text))
        ), attributed AS (
         SELECT pp.play_id,
            pp.game_id,
            pp.season,
            pp.week,
            pp.season_type,
            pp.period,
            pp.down,
            pp.distance,
            pp.offense,
            pp.defense,
            pp.home,
            pp.away,
            pp.play_type,
            pp.is_penalty_play_type,
            pp.yards_gained,
            pp.ppa,
            pp.play_text,
                CASE
                    WHEN (m.matches_home AND (NOT m.matches_away)) THEN pp.home
                    WHEN (m.matches_away AND (NOT m.matches_home)) THEN pp.away
                    ELSE NULL::character varying
                END AS penalized_team
           FROM (((penalty_plays pp
             LEFT JOIN team_idents ht ON (((ht.school)::text = (pp.home)::text)))
             LEFT JOIN team_idents awy ON (((awy.school)::text = (pp.away)::text)))
             CROSS JOIN LATERAL ( SELECT (((pp.play_text)::text ~~* (('%'::text || (pp.home)::text) || ' penalty%'::text)) OR ((pp.play_text)::text ~~* (('%penalty '::text || (pp.home)::text) || ' %'::text)) OR ((ht.school_st <> (pp.home)::text) AND (((pp.play_text)::text ~~* (('%'::text || ht.school_st) || ' penalty%'::text)) OR ((pp.play_text)::text ~~* (('%penalty '::text || ht.school_st) || ' %'::text)))) OR ((ht.abbreviation IS NOT NULL) AND (((pp.play_text)::text ~~* (('%penalty '::text || (ht.abbreviation)::text) || ' %'::text)) OR ((pp.play_text)::text ~~* (('%penalty on '::text || (ht.abbreviation)::text) || '-%'::text)))) OR ((ht.mascot IS NOT NULL) AND ((pp.play_text)::text ~~* (('%penalty '::text || (ht.mascot)::text) || ' %'::text)))) AS matches_home,
                    (((pp.play_text)::text ~~* (('%'::text || (pp.away)::text) || ' penalty%'::text)) OR ((pp.play_text)::text ~~* (('%penalty '::text || (pp.away)::text) || ' %'::text)) OR ((awy.school_st <> (pp.away)::text) AND (((pp.play_text)::text ~~* (('%'::text || awy.school_st) || ' penalty%'::text)) OR ((pp.play_text)::text ~~* (('%penalty '::text || awy.school_st) || ' %'::text)))) OR ((awy.abbreviation IS NOT NULL) AND (((pp.play_text)::text ~~* (('%penalty '::text || (awy.abbreviation)::text) || ' %'::text)) OR ((pp.play_text)::text ~~* (('%penalty on '::text || (awy.abbreviation)::text) || '-%'::text)))) OR ((awy.mascot IS NOT NULL) AND ((pp.play_text)::text ~~* (('%penalty '::text || (awy.mascot)::text) || ' %'::text)))) AS matches_away) m)
        )
 SELECT a.play_id,
    a.game_id,
    a.season,
    a.week,
    a.season_type,
    a.period,
    a.down,
    a.distance,
    a.offense,
    a.defense,
    a.play_type,
    a.is_penalty_play_type,
    a.penalized_team,
        CASE
            WHEN ((a.penalized_team)::text = (a.home)::text) THEN a.away
            WHEN ((a.penalized_team)::text = (a.away)::text) THEN a.home
            ELSE NULL::character varying
        END AS benefiting_team,
    COALESCE(inf.label, 'Unknown'::text) AS infraction,
    ("substring"((a.play_text)::text, '(\d+) [Yy]ard'::text))::integer AS penalty_yards,
    ((a.play_text)::text ~* 'declined'::text) AS declined,
    ((a.play_text)::text ~* 'offsett'::text) AS offsetting,
    ((a.play_text)::text ~* 'no play'::text) AS no_play,
    ((length(lower((a.play_text)::text)) - length(replace(lower((a.play_text)::text), 'penalt'::text, ''::text))) > 6) AS multi_penalty,
    a.yards_gained,
    a.ppa,
    a.play_text,
    ((inf.label IS NOT NULL) AND (a.penalized_team IS NOT NULL)) AS parse_ok
   FROM (attributed a
     LEFT JOIN LATERAL ( SELECT i.label
           FROM infractions i
          WHERE ((a.play_text)::text ~~* i.pattern)
          ORDER BY i.priority
         LIMIT 1) inf ON (true))
  WITH NO DATA;


--
-- Name: penalty_log; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.penalty_log AS
 SELECT play_id,
    game_id,
    season,
    week,
    season_type,
    period,
    down,
    distance,
    offense,
    defense,
    play_type,
    is_penalty_play_type,
    penalized_team,
    benefiting_team,
    infraction,
    penalty_yards,
    declined,
    offsetting,
    no_play,
    multi_penalty,
    yards_gained,
    ppa,
    play_text,
    parse_ok
   FROM marts.penalty_log;


--
-- Name: VIEW penalty_log; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.penalty_log IS 'Play-derived penalty events, one row per play carrying penalty text (2004+). infraction/penalized_team are BEST-EFFORT parses of CFBD free-text play_text (four provider formats; see marts/041): infraction = ''Unknown'' or penalized_team IS NULL means unclassified, not absent -- filter on parse_ok for fully-attributed rows and treat counts as floors. is_penalty_play_type separates flag-was-the-play rows from penalties embedded in other plays (declined/offsetting/tacked-on). For official per-game counts use api.team_penalties.';


--
-- Name: ppa_players_season; Type: TABLE; Schema: metrics; Owner: -
--

CREATE TABLE metrics.ppa_players_season (
    season bigint NOT NULL,
    id character varying NOT NULL,
    name character varying,
    "position" character varying,
    team character varying,
    conference character varying,
    average_ppa__all double precision,
    average_ppa__pass double precision,
    average_ppa__rush double precision,
    average_ppa__first_down double precision,
    average_ppa__second_down double precision,
    average_ppa__third_down double precision,
    average_ppa__standard_downs double precision,
    average_ppa__passing_downs double precision,
    total_ppa__all double precision,
    total_ppa__pass double precision,
    total_ppa__rush double precision,
    total_ppa__first_down double precision,
    total_ppa__second_down double precision,
    total_ppa__third_down double precision,
    total_ppa__standard_downs double precision,
    total_ppa__passing_downs double precision,
    _dlt_load_id character varying NOT NULL,
    _dlt_id character varying NOT NULL
);


--
-- Name: player_comparison; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.player_comparison AS
 WITH position_groups AS (
         SELECT unnest.unnest AS "position",
                CASE
                    WHEN (unnest.unnest = 'QB'::text) THEN 'QB'::text
                    WHEN (unnest.unnest = ANY (ARRAY['RB'::text, 'FB'::text])) THEN 'RB'::text
                    WHEN (unnest.unnest = 'WR'::text) THEN 'WR'::text
                    WHEN (unnest.unnest = 'TE'::text) THEN 'TE'::text
                    WHEN (unnest.unnest = ANY (ARRAY['OL'::text, 'OT'::text, 'OG'::text, 'C'::text])) THEN 'OL'::text
                    WHEN (unnest.unnest = ANY (ARRAY['DL'::text, 'DE'::text, 'DT'::text, 'NT'::text, 'EDGE'::text])) THEN 'DL'::text
                    WHEN (unnest.unnest = ANY (ARRAY['LB'::text, 'OLB'::text, 'ILB'::text])) THEN 'LB'::text
                    WHEN (unnest.unnest = ANY (ARRAY['DB'::text, 'CB'::text, 'S'::text, 'FS'::text, 'SS'::text])) THEN 'DB'::text
                    WHEN (unnest.unnest = ANY (ARRAY['K'::text, 'P'::text])) THEN 'K/P'::text
                    ELSE NULL::text
                END AS position_group
           FROM unnest(ARRAY['QB'::text, 'RB'::text, 'FB'::text, 'WR'::text, 'TE'::text, 'OL'::text, 'OT'::text, 'OG'::text, 'C'::text, 'DL'::text, 'DE'::text, 'DT'::text, 'NT'::text, 'EDGE'::text, 'LB'::text, 'OLB'::text, 'ILB'::text, 'DB'::text, 'CB'::text, 'S'::text, 'FS'::text, 'SS'::text, 'K'::text, 'P'::text, 'ATH'::text, 'KR'::text, 'PR'::text, 'LS'::text]) unnest(unnest)
        ), stat_aggregates AS (
         SELECT s.player_id,
            s.team,
            s.season,
            mode() WITHIN GROUP (ORDER BY (jsonb_build_array((NULLIF(btrim((s.player)::text), ''::text) IS NULL), (NULLIF(btrim((s."position")::text), ''::text) IS NULL), s.player, s."position"))) AS metadata,
            max(
                CASE
                    WHEN (((s.category)::text = 'passing'::text) AND ((s.stat_type)::text = 'ATT'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS pass_att,
            max(
                CASE
                    WHEN (((s.category)::text = 'passing'::text) AND ((s.stat_type)::text = 'COMPLETIONS'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS pass_cmp,
            max(
                CASE
                    WHEN (((s.category)::text = 'passing'::text) AND ((s.stat_type)::text = 'YDS'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS pass_yds,
            max(
                CASE
                    WHEN (((s.category)::text = 'passing'::text) AND ((s.stat_type)::text = 'TD'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS pass_td,
            max(
                CASE
                    WHEN (((s.category)::text = 'passing'::text) AND ((s.stat_type)::text = 'INT'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS pass_int,
            max(
                CASE
                    WHEN (((s.category)::text = 'passing'::text) AND ((s.stat_type)::text = 'PCT'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS pass_pct,
            max(
                CASE
                    WHEN (((s.category)::text = 'rushing'::text) AND ((s.stat_type)::text = 'CAR'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rush_car,
            max(
                CASE
                    WHEN (((s.category)::text = 'rushing'::text) AND ((s.stat_type)::text = 'YDS'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rush_yds,
            max(
                CASE
                    WHEN (((s.category)::text = 'rushing'::text) AND ((s.stat_type)::text = 'TD'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rush_td,
            max(
                CASE
                    WHEN (((s.category)::text = 'rushing'::text) AND ((s.stat_type)::text = 'YPC'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rush_ypc,
            max(
                CASE
                    WHEN (((s.category)::text = 'receiving'::text) AND ((s.stat_type)::text = 'REC'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rec,
            max(
                CASE
                    WHEN (((s.category)::text = 'receiving'::text) AND ((s.stat_type)::text = 'YDS'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rec_yds,
            max(
                CASE
                    WHEN (((s.category)::text = 'receiving'::text) AND ((s.stat_type)::text = 'TD'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rec_td,
            max(
                CASE
                    WHEN (((s.category)::text = 'receiving'::text) AND ((s.stat_type)::text = 'YPR'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS rec_ypr,
            max(
                CASE
                    WHEN (((s.category)::text = 'defensive'::text) AND ((s.stat_type)::text = 'TOT'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS tackles,
            max(
                CASE
                    WHEN (((s.category)::text = 'defensive'::text) AND ((s.stat_type)::text = 'SACKS'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS sacks,
            max(
                CASE
                    WHEN (((s.category)::text = 'defensive'::text) AND ((s.stat_type)::text = 'TFL'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS tfl,
            max(
                CASE
                    WHEN (((s.category)::text = 'defensive'::text) AND ((s.stat_type)::text = 'PD'::text)) THEN (NULLIF((s.stat)::text, ''::text))::numeric
                    ELSE NULL::numeric
                END) AS pass_def
           FROM stats.player_season_stats s
          GROUP BY s.player_id, s.team, s.season
        ), pivoted_stats AS (
         SELECT sa.player_id,
            (sa.metadata ->> 2) AS name,
            sa.team,
            (sa.metadata ->> 3) AS "position",
            sa.season,
            sa.pass_att,
            sa.pass_cmp,
            sa.pass_yds,
            sa.pass_td,
            sa.pass_int,
            sa.pass_pct,
            sa.rush_car,
            sa.rush_yds,
            sa.rush_td,
            sa.rush_ypc,
            sa.rec,
            sa.rec_yds,
            sa.rec_td,
            sa.rec_ypr,
            sa.tackles,
            sa.sacks,
            sa.tfl,
            sa.pass_def
           FROM stat_aggregates sa
        ), roster_deduped AS (
         SELECT DISTINCT ON (roster.id, roster.year) roster.id,
            roster.year,
            roster.height,
            roster.weight,
            roster.jersey,
            roster.home_city,
            roster.home_state,
            roster.team
           FROM core.roster
          ORDER BY roster.id, roster.year, roster.team
        ), recruits_deduped AS (
         SELECT DISTINCT ON (recruits.athlete_id) recruits.athlete_id,
            recruits.stars,
            recruits.rating,
            recruits.ranking,
            recruits.year
           FROM recruiting.recruits
          ORDER BY recruits.athlete_id, recruits.rating DESC NULLS LAST
        ), with_extras AS (
         SELECT ps.player_id,
            ps.name,
            ps.team,
            ps."position",
            pg.position_group,
            ps.season,
            COALESCE(r_match.height, r_any.height) AS height,
            COALESCE(r_match.weight, r_any.weight) AS weight,
            COALESCE(r_match.jersey, r_any.jersey) AS jersey,
            COALESCE(r_match.home_city, r_any.home_city) AS home_city,
            COALESCE(r_match.home_state, r_any.home_state) AS home_state,
            rec.stars,
            rec.rating AS recruit_rating,
            rec.ranking AS national_ranking,
            rec.year AS recruit_class,
            ps.pass_att,
            ps.pass_cmp,
            ps.pass_yds,
            ps.pass_td,
            ps.pass_int,
            ps.pass_pct,
            ps.rush_car,
            ps.rush_yds,
            ps.rush_td,
            ps.rush_ypc,
            ps.rec,
            ps.rec_yds,
            ps.rec_td,
            ps.rec_ypr,
            ps.tackles,
            ps.sacks,
            ps.tfl,
            ps.pass_def,
            ppa.average_ppa__all AS ppa_avg,
            ppa.total_ppa__all AS ppa_total
           FROM (((((pivoted_stats ps
             LEFT JOIN position_groups pg ON ((pg."position" = ps."position")))
             LEFT JOIN core.roster r_match ON ((((r_match.id)::text = (ps.player_id)::text) AND (r_match.year = ps.season) AND ((r_match.team)::text = (ps.team)::text))))
             LEFT JOIN roster_deduped r_any ON ((((r_any.id)::text = (ps.player_id)::text) AND (r_any.year = ps.season) AND (r_match.id IS NULL))))
             LEFT JOIN recruits_deduped rec ON (((rec.athlete_id)::text = (ps.player_id)::text)))
             LEFT JOIN metrics.ppa_players_season ppa ON ((((ppa.id)::text = (ps.player_id)::text) AND (ppa.season = ps.season))))
        )
 SELECT player_id,
    name,
    team,
    "position",
    position_group,
    season,
    height,
    weight,
    jersey,
    home_city,
    home_state,
    stars,
    recruit_rating,
    national_ranking,
    recruit_class,
    pass_att,
    pass_cmp,
    pass_yds,
    pass_td,
    pass_int,
    pass_pct,
    rush_car,
    rush_yds,
    rush_td,
    rush_ypc,
    rec,
    rec_yds,
    rec_td,
    rec_ypr,
    tackles,
    sacks,
    tfl,
    pass_def,
    ppa_avg,
    ppa_total,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY pass_yds NULLS FIRST)
            ELSE NULL::double precision
        END AS pass_yds_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY pass_td NULLS FIRST)
            ELSE NULL::double precision
        END AS pass_td_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY pass_pct NULLS FIRST)
            ELSE NULL::double precision
        END AS pass_pct_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY rush_yds NULLS FIRST)
            ELSE NULL::double precision
        END AS rush_yds_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY rush_td NULLS FIRST)
            ELSE NULL::double precision
        END AS rush_td_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY rush_ypc NULLS FIRST)
            ELSE NULL::double precision
        END AS rush_ypc_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY rec_yds NULLS FIRST)
            ELSE NULL::double precision
        END AS rec_yds_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY rec_td NULLS FIRST)
            ELSE NULL::double precision
        END AS rec_td_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY tackles NULLS FIRST)
            ELSE NULL::double precision
        END AS tackles_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY sacks NULLS FIRST)
            ELSE NULL::double precision
        END AS sacks_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY tfl NULLS FIRST)
            ELSE NULL::double precision
        END AS tfl_pctl,
        CASE
            WHEN (position_group IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season, position_group ORDER BY ppa_avg NULLS FIRST)
            ELSE NULL::double precision
        END AS ppa_avg_pctl
   FROM with_extras we
  WITH NO DATA;


--
-- Name: player_comparison; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.player_comparison AS
 SELECT player_id,
    name,
    team,
    "position",
    position_group,
    season,
    height,
    weight,
    jersey,
    home_city,
    home_state,
    stars,
    recruit_rating,
    national_ranking,
    recruit_class,
    pass_att,
    pass_cmp,
    pass_yds,
    pass_td,
    pass_int,
    pass_pct,
    rush_car,
    rush_yds,
    rush_td,
    rush_ypc,
    rec,
    rec_yds,
    rec_td,
    rec_ypr,
    tackles,
    sacks,
    tfl,
    pass_def,
    ppa_avg,
    ppa_total,
    pass_yds_pctl,
    pass_td_pctl,
    pass_pct_pctl,
    rush_yds_pctl,
    rush_td_pctl,
    rush_ypc_pctl,
    rec_yds_pctl,
    rec_td_pctl,
    tackles_pctl,
    sacks_pctl,
    tfl_pctl,
    ppa_avg_pctl
   FROM marts.player_comparison;


