--
-- Name: player_detail; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.player_detail AS
 WITH player_passing AS (
         SELECT player_season_stats.player_id,
            player_season_stats.season,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'ATT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_att,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'COMPLETIONS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_cmp,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_yds,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_td,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'INT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_int,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'PCT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_pct
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'passing'::text)
          GROUP BY player_season_stats.player_id, player_season_stats.season
        ), player_rushing AS (
         SELECT player_season_stats.player_id,
            player_season_stats.season,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'CAR'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_car,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_yds,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_td,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YPC'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_ypc
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'rushing'::text)
          GROUP BY player_season_stats.player_id, player_season_stats.season
        ), player_receiving AS (
         SELECT player_season_stats.player_id,
            player_season_stats.season,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'REC'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec_yds,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec_td,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YPR'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec_ypr
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'receiving'::text)
          GROUP BY player_season_stats.player_id, player_season_stats.season
        ), player_defense AS (
         SELECT player_season_stats.player_id,
            player_season_stats.season,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TOT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS tackles,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'SACKS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS sacks,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TFL'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS tfl,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'PD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_def
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'defensive'::text)
          GROUP BY player_season_stats.player_id, player_season_stats.season
        ), recruit_dedup AS (
         SELECT DISTINCT ON (recruits.athlete_id) recruits.athlete_id,
            recruits.stars,
            recruits.rating,
            recruits.ranking,
            recruits.year
           FROM recruiting.recruits
          ORDER BY recruits.athlete_id, recruits.year DESC NULLS LAST
        )
 SELECT r.id AS player_id,
    (((r.first_name)::text || ' '::text) || (r.last_name)::text) AS name,
    r.team,
    r."position",
    r.year AS season,
    r.height,
    r.weight,
    r.jersey,
    r.home_city,
    r.home_state,
    rec.stars,
    rec.rating AS recruit_rating,
    rec.ranking AS national_ranking,
    rec.year AS recruit_class,
    pp.pass_att,
    pp.pass_cmp,
    pp.pass_yds,
    pp.pass_td,
    pp.pass_int,
    pp.pass_pct,
    pr.rush_car,
    pr.rush_yds,
    pr.rush_td,
    pr.rush_ypc,
    prv.rec,
    prv.rec_yds,
    prv.rec_td,
    prv.rec_ypr,
    pd.tackles,
    pd.sacks,
    pd.tfl,
    pd.pass_def,
    ppa.average_ppa__all AS ppa_avg,
    ppa.total_ppa__all AS ppa_total,
    ov.games,
    ov.usage_overall,
    ov.usage_pass,
    ov.usage_rush,
    ov.ppa_overview_avg,
    ov.ppa_overview_total
   FROM (((((((core.roster r
     LEFT JOIN recruit_dedup rec ON (((rec.athlete_id)::text = (r.id)::text)))
     LEFT JOIN player_passing pp ON ((((pp.player_id)::text = (r.id)::text) AND (pp.season = r.year))))
     LEFT JOIN player_rushing pr ON ((((pr.player_id)::text = (r.id)::text) AND (pr.season = r.year))))
     LEFT JOIN player_receiving prv ON ((((prv.player_id)::text = (r.id)::text) AND (prv.season = r.year))))
     LEFT JOIN player_defense pd ON ((((pd.player_id)::text = (r.id)::text) AND (pd.season = r.year))))
     LEFT JOIN metrics.ppa_players_season ppa ON ((((ppa.id)::text = (r.id)::text) AND (ppa.season = r.year))))
     LEFT JOIN LATERAL ( SELECT pso.games,
            pso.usage__overall AS usage_overall,
            pso.usage__pass AS usage_pass,
            COALESCE((pso.usage__rush)::double precision, pso.usage__rush__v_double) AS usage_rush,
            pso.ppa__average__all AS ppa_overview_avg,
            pso.ppa__total__all AS ppa_overview_total,
            pso.team
           FROM stats.player_season_overview pso
          WHERE (((pso.id)::text = (r.id)::text) AND (pso.season = r.year))
          ORDER BY ((pso.team)::text = (r.team)::text) DESC, pso.team
         LIMIT 1) ov ON (true));


--
-- Name: VIEW player_detail; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.player_detail IS 'Comprehensive player profile with roster info, recruiting data, season stats, PPA metrics, and a compact season-overview payload (games/usage/ppa_overview_*). One row per (player_id, season, team) -- recruiting pedigree (stars/recruit_rating/national_ranking/recruit_class) is deduped to one row per player_id, keeping the highest (most authoritative) recruit_class year for a reclassified player (fixed 2026-08-30; was fanning out on players with 2+ recruiting.recruits rows). games/usage_overall/usage_pass/usage_rush/ppa_overview_avg/ppa_overview_total are from stats.player_season_overview via a fanout-proof LATERAL join (team-matched stint preferred, falls back to any stint for that player-season) -- NULL outside that table''s coverage.';


--
-- Name: player_season_leaders; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.player_season_leaders AS
 WITH passing AS (
         SELECT player_season_stats.season,
            'passing'::text AS category,
            player_season_stats.player_id,
            player_season_stats.player AS player_name,
            player_season_stats.team,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS yards,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS touchdowns,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'INT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS interceptions,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'PCT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pct,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'ATT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS attempts,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'COMPLETIONS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS completions
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'passing'::text)
          GROUP BY player_season_stats.season, player_season_stats.player_id, player_season_stats.player, player_season_stats.team
        ), rushing AS (
         SELECT player_season_stats.season,
            'rushing'::text AS category,
            player_season_stats.player_id,
            player_season_stats.player AS player_name,
            player_season_stats.team,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS yards,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS touchdowns,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'CAR'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS carries,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YPC'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS yards_per_carry,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'LONG'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS longest
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'rushing'::text)
          GROUP BY player_season_stats.season, player_season_stats.player_id, player_season_stats.player, player_season_stats.team
        ), receiving AS (
         SELECT player_season_stats.season,
            'receiving'::text AS category,
            player_season_stats.player_id,
            player_season_stats.player AS player_name,
            player_season_stats.team,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS yards,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS touchdowns,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'REC'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS receptions,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YPR'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS yards_per_reception,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'LONG'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS longest
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'receiving'::text)
          GROUP BY player_season_stats.season, player_season_stats.player_id, player_season_stats.player, player_season_stats.team
        ), defensive AS (
         SELECT player_season_stats.season,
            'defense'::text AS category,
            player_season_stats.player_id,
            player_season_stats.player AS player_name,
            player_season_stats.team,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TOT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS total_tackles,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'SOLO'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS solo_tackles,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'SACKS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS sacks,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TFL'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS tackles_for_loss,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'PD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS passes_defended
           FROM stats.player_season_stats
          WHERE ((player_season_stats.category)::text = 'defensive'::text)
          GROUP BY player_season_stats.season, player_season_stats.player_id, player_season_stats.player, player_season_stats.team
        )
 SELECT passing.season,
    passing.category,
    passing.player_id,
    passing.player_name,
    passing.team,
    passing.yards,
    passing.touchdowns,
    passing.interceptions,
    passing.pct,
    passing.attempts,
    passing.completions,
    NULL::numeric AS carries,
    NULL::numeric AS yards_per_carry,
    NULL::numeric AS receptions,
    NULL::numeric AS yards_per_reception,
    NULL::numeric AS longest,
    NULL::numeric AS total_tackles,
    NULL::numeric AS solo_tackles,
    NULL::numeric AS sacks,
    NULL::numeric AS tackles_for_loss,
    NULL::numeric AS passes_defended,
    rank() OVER (PARTITION BY passing.season ORDER BY passing.yards DESC NULLS LAST) AS yards_rank
   FROM passing
UNION ALL
 SELECT rushing.season,
    rushing.category,
    rushing.player_id,
    rushing.player_name,
    rushing.team,
    rushing.yards,
    rushing.touchdowns,
    NULL::numeric AS interceptions,
    NULL::numeric AS pct,
    NULL::numeric AS attempts,
    NULL::numeric AS completions,
    rushing.carries,
    rushing.yards_per_carry,
    NULL::numeric AS receptions,
    NULL::numeric AS yards_per_reception,
    rushing.longest,
    NULL::numeric AS total_tackles,
    NULL::numeric AS solo_tackles,
    NULL::numeric AS sacks,
    NULL::numeric AS tackles_for_loss,
    NULL::numeric AS passes_defended,
    rank() OVER (PARTITION BY rushing.season ORDER BY rushing.yards DESC NULLS LAST) AS yards_rank
   FROM rushing
UNION ALL
 SELECT receiving.season,
    receiving.category,
    receiving.player_id,
    receiving.player_name,
    receiving.team,
    receiving.yards,
    receiving.touchdowns,
    NULL::numeric AS interceptions,
    NULL::numeric AS pct,
    NULL::numeric AS attempts,
    NULL::numeric AS completions,
    NULL::numeric AS carries,
    NULL::numeric AS yards_per_carry,
    receiving.receptions,
    receiving.yards_per_reception,
    receiving.longest,
    NULL::numeric AS total_tackles,
    NULL::numeric AS solo_tackles,
    NULL::numeric AS sacks,
    NULL::numeric AS tackles_for_loss,
    NULL::numeric AS passes_defended,
    rank() OVER (PARTITION BY receiving.season ORDER BY receiving.yards DESC NULLS LAST) AS yards_rank
   FROM receiving
UNION ALL
 SELECT defensive.season,
    defensive.category,
    defensive.player_id,
    defensive.player_name,
    defensive.team,
    NULL::numeric AS yards,
    NULL::numeric AS touchdowns,
    NULL::numeric AS interceptions,
    NULL::numeric AS pct,
    NULL::numeric AS attempts,
    NULL::numeric AS completions,
    NULL::numeric AS carries,
    NULL::numeric AS yards_per_carry,
    NULL::numeric AS receptions,
    NULL::numeric AS yards_per_reception,
    NULL::numeric AS longest,
    defensive.total_tackles,
    defensive.solo_tackles,
    defensive.sacks,
    defensive.tackles_for_loss,
    defensive.passes_defended,
    rank() OVER (PARTITION BY defensive.season ORDER BY defensive.total_tackles DESC NULLS LAST) AS yards_rank
   FROM defensive;


--
-- Name: player_usage; Type: TABLE; Schema: stats; Owner: -
--

CREATE TABLE stats.player_usage (
    season bigint NOT NULL,
    id character varying NOT NULL,
    name character varying,
    "position" character varying,
    team character varying,
    conference character varying,
    usage__overall double precision,
    usage__pass bigint,
    usage__rush double precision,
    usage__first_down double precision,
    usage__second_down double precision,
    usage__third_down bigint,
    usage__standard_downs double precision,
    usage__passing_downs double precision,
    _dlt_load_id character varying NOT NULL,
    _dlt_id character varying NOT NULL,
    usage__pass__v_double double precision,
    usage__third_down__v_double double precision
);


--
-- Name: player_usage; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.player_usage AS
 SELECT season,
    id AS athlete_id,
    name AS player_name,
    "position",
    team,
    conference,
    round((usage__overall)::numeric, 4) AS usage_overall,
    round((COALESCE((usage__pass)::double precision, usage__pass__v_double))::numeric, 4) AS usage_pass,
    round((usage__rush)::numeric, 4) AS usage_rush,
    round((usage__first_down)::numeric, 4) AS usage_first_down,
    round((usage__second_down)::numeric, 4) AS usage_second_down,
    round((COALESCE((usage__third_down)::double precision, usage__third_down__v_double))::numeric, 4) AS usage_third_down,
    round((usage__standard_downs)::numeric, 4) AS usage_standard_downs,
    round((usage__passing_downs)::numeric, 4) AS usage_passing_downs
   FROM stats.player_usage u
  WITH NO DATA;


--
-- Name: player_usage_leaders; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.player_usage_leaders AS
 SELECT season,
    athlete_id,
    player_name,
    "position",
    team,
    conference,
    usage_overall,
    usage_pass,
    usage_rush,
    usage_first_down,
    usage_second_down,
    usage_third_down,
    usage_standard_downs,
    usage_passing_downs
   FROM marts.player_usage;


--
-- Name: VIEW player_usage_leaders; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.player_usage_leaders IS 'Player usage rates by season: share of team plays (overall, pass, rush, and down-split: first/second/third down, standard/passing downs) per athlete. Backed by marts.player_usage.';


