--
-- Name: player_wepa_season; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.player_wepa_season AS
 WITH combined AS (
         SELECT wepa_players_passing.year AS season,
            wepa_players_passing.athlete_id,
            wepa_players_passing.athlete_name,
            wepa_players_passing."position",
            wepa_players_passing.team,
            wepa_players_passing.conference,
            'passing'::text AS category,
            wepa_players_passing.wepa,
            NULL::double precision AS paar,
            wepa_players_passing.wepa AS metric,
            wepa_players_passing.plays
           FROM metrics.wepa_players_passing
        UNION ALL
         SELECT wepa_players_rushing.year AS season,
            wepa_players_rushing.athlete_id,
            wepa_players_rushing.athlete_name,
            wepa_players_rushing."position",
            wepa_players_rushing.team,
            wepa_players_rushing.conference,
            'rushing'::text AS category,
            wepa_players_rushing.wepa,
            NULL::double precision AS paar,
            wepa_players_rushing.wepa AS metric,
            wepa_players_rushing.plays
           FROM metrics.wepa_players_rushing
        UNION ALL
         SELECT wepa_players_kicking.year AS season,
            wepa_players_kicking.athlete_id,
            wepa_players_kicking.athlete_name,
            NULL::character varying AS "position",
            wepa_players_kicking.team,
            wepa_players_kicking.conference,
            'kicking'::text AS category,
            NULL::double precision AS wepa,
            wepa_players_kicking.paar,
            wepa_players_kicking.paar AS metric,
            wepa_players_kicking.attempts AS plays
           FROM metrics.wepa_players_kicking
        )
 SELECT season,
    athlete_id,
    athlete_name,
    "position",
    team,
    conference,
    category,
    wepa,
    paar,
    metric,
    plays,
    rank() OVER (PARTITION BY season, category ORDER BY metric DESC NULLS LAST) AS season_rank
   FROM combined
  WITH NO DATA;


