--
-- Name: prediction_accuracy; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.prediction_accuracy AS
 WITH latest_pred AS (
         SELECT DISTINCT ON (p.game_id, p.model_version) p.game_id,
            p.model_version,
            p.season,
            p.expected_home_margin,
            p.home_win_prob,
            p.market_spread,
            p.edge,
            p.edge_pick,
            g.home_points,
            g.away_points
           FROM (predictions.game_predictions p
             JOIN core.games g ON ((g.id = p.game_id)))
          WHERE (g.completed AND (g.home_points IS NOT NULL) AND (g.away_points IS NOT NULL) AND (p.evaluation_mode = 'published_forecast'::text) AND (g.start_date IS NOT NULL) AND (p.published_at < g.start_date))
          ORDER BY p.game_id, p.model_version, p.published_at DESC, p.prediction_id DESC
        ), scored AS (
         SELECT lp.model_version,
            lp.season,
            lp.game_id,
            lp.expected_home_margin,
            lp.home_win_prob,
            lp.market_spread,
            lp.edge,
            lp.edge_pick,
            ((lp.home_points - lp.away_points))::numeric AS actual_home_margin,
                CASE
                    WHEN (lp.home_points > lp.away_points) THEN 1.0
                    WHEN (lp.home_points = lp.away_points) THEN 0.5
                    ELSE 0.0
                END AS actual_home_result,
            wp.home_win_probability AS cfbd_home_win_prob
           FROM (latest_pred lp
             LEFT JOIN metrics.pregame_win_probability wp ON ((wp.game_id = lp.game_id)))
        ), expanded AS (
         SELECT s.model_version,
            s.season,
            s.game_id,
            s.expected_home_margin,
            s.home_win_prob,
            s.market_spread,
            s.edge,
            s.edge_pick,
            s.actual_home_margin,
            s.actual_home_result,
            s.cfbd_home_win_prob,
            th.edge_threshold,
            ((th.edge_threshold = 0) OR ((s.edge IS NOT NULL) AND (abs(s.edge) >= (th.edge_threshold)::numeric))) AS qualifies
           FROM (scored s
             CROSS JOIN ( VALUES (0), (3), (6), (10)) th(edge_threshold))
        ), agg AS (
         SELECT expanded.model_version,
            expanded.season,
            expanded.edge_threshold,
            count(*) FILTER (WHERE expanded.qualifies) AS n_games,
            count(*) FILTER (WHERE (expanded.qualifies AND (expanded.market_spread IS NOT NULL))) AS n_with_market,
            avg(abs((expanded.expected_home_margin - expanded.actual_home_margin))) FILTER (WHERE expanded.qualifies) AS margin_mae,
            sqrt(avg(power((expanded.expected_home_margin - expanded.actual_home_margin), (2)::numeric)) FILTER (WHERE expanded.qualifies)) AS margin_rmse,
            count(*) FILTER (WHERE (expanded.qualifies AND (expanded.market_spread IS NOT NULL) AND ((expanded.actual_home_margin + expanded.market_spread) <> (0)::numeric) AND ((((expanded.edge_pick)::text = 'home'::text) AND ((expanded.actual_home_margin + expanded.market_spread) > (0)::numeric)) OR (((expanded.edge_pick)::text = 'away'::text) AND ((expanded.actual_home_margin + expanded.market_spread) < (0)::numeric))))) AS ats_wins,
            count(*) FILTER (WHERE (expanded.qualifies AND (expanded.market_spread IS NOT NULL) AND ((expanded.actual_home_margin + expanded.market_spread) <> (0)::numeric) AND (NOT ((((expanded.edge_pick)::text = 'home'::text) AND ((expanded.actual_home_margin + expanded.market_spread) > (0)::numeric)) OR (((expanded.edge_pick)::text = 'away'::text) AND ((expanded.actual_home_margin + expanded.market_spread) < (0)::numeric)))))) AS ats_losses,
            count(*) FILTER (WHERE (expanded.qualifies AND (expanded.market_spread IS NOT NULL) AND ((expanded.actual_home_margin + expanded.market_spread) = (0)::numeric))) AS ats_pushes,
            avg(power((expanded.home_win_prob - expanded.actual_home_result), (2)::numeric)) FILTER (WHERE (expanded.qualifies AND (expanded.home_win_prob IS NOT NULL) AND (expanded.cfbd_home_win_prob IS NOT NULL))) AS brier,
            avg(power((expanded.cfbd_home_win_prob - (expanded.actual_home_result)::double precision), (2)::double precision)) FILTER (WHERE (expanded.qualifies AND (expanded.home_win_prob IS NOT NULL) AND (expanded.cfbd_home_win_prob IS NOT NULL))) AS cfbd_brier,
            count(*) FILTER (WHERE (expanded.qualifies AND (expanded.home_win_prob IS NOT NULL) AND (expanded.cfbd_home_win_prob IS NOT NULL))) AS n_scored_win_prob
           FROM expanded
          GROUP BY expanded.model_version, expanded.season, expanded.edge_threshold
        )
 SELECT model_version,
    season,
    edge_threshold,
    n_games,
    n_with_market,
    round(margin_mae, 4) AS margin_mae,
    round(margin_rmse, 4) AS margin_rmse,
    ats_wins,
    ats_losses,
    ats_pushes,
    round(((ats_wins)::numeric / (NULLIF((ats_wins + ats_losses), 0))::numeric), 4) AS ats_hit_rate,
    round(brier, 6) AS brier,
    round((cfbd_brier)::numeric, 6) AS cfbd_brier,
    n_scored_win_prob
   FROM agg
  WITH NO DATA;


--
-- Name: prediction_accuracy; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.prediction_accuracy AS
 SELECT model_version,
    season,
    edge_threshold,
