--
-- Name: recruiting_roi; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.recruiting_roi AS
 WITH rolling_recruiting AS (
         SELECT tss.team,
            tss.season,
            avg(rc.national_rank) AS avg_class_rank_4yr,
            avg(rc.total_points) AS avg_class_points_4yr,
            sum((rc.five_stars + rc.four_stars)) AS total_blue_chips_4yr,
            sum(rc.total_commits) AS total_recruits_4yr,
            round(((sum((rc.five_stars + rc.four_stars)))::numeric / NULLIF(sum(rc.total_commits), (0)::numeric)), 4) AS blue_chip_ratio
           FROM (marts.team_season_summary tss
             LEFT JOIN marts.recruiting_class rc ON ((((rc.team)::text = (tss.team)::text) AND ((rc.year >= (tss.season - 4)) AND (rc.year <= (tss.season - 1))))))
          GROUP BY tss.team, tss.season
         HAVING (count(rc.year) >= 2)
        ), draft_output AS (
         SELECT dp.college_team AS team,
            dp.year AS season,
            count(*) AS players_drafted,
            (sum(GREATEST((260 - COALESCE(dp.overall, (260)::bigint)), (0)::bigint)))::integer AS draft_picks_value
           FROM draft.draft_picks dp
          WHERE (dp.college_team IS NOT NULL)
          GROUP BY dp.college_team, dp.year
        ), expected_perf AS (
         SELECT tss.team,
            tss.season,
                CASE
                    WHEN (rr.avg_class_rank_4yr <= (10)::numeric) THEN 'elite'::text
                    WHEN (rr.avg_class_rank_4yr <= (25)::numeric) THEN 'high'::text
                    WHEN (rr.avg_class_rank_4yr <= (50)::numeric) THEN 'mid'::text
                    ELSE 'low'::text
                END AS talent_bucket,
            tss.wins,
            tss.sp_rating,
            epa.epa_per_play,
            epa.success_rate,
            rr.avg_class_rank_4yr,
            rr.avg_class_points_4yr,
            rr.total_blue_chips_4yr,
            rr.blue_chip_ratio,
            round(((tss.wins)::numeric / (NULLIF(tss.games, 0))::numeric), 4) AS win_pct
           FROM ((marts.team_season_summary tss
             JOIN rolling_recruiting rr ON ((((rr.team)::text = (tss.team)::text) AND (rr.season = tss.season))))
             LEFT JOIN marts.team_epa_season epa ON ((((epa.team)::text = (tss.team)::text) AND (epa.season = tss.season))))
        ), bucket_medians AS (
         SELECT expected_perf.season,
            expected_perf.talent_bucket,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((expected_perf.wins)::double precision)) AS expected_wins,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((expected_perf.epa_per_play)::double precision)) AS expected_epa
           FROM expected_perf
          GROUP BY expected_perf.season, expected_perf.talent_bucket
        ), combined AS (
         SELECT ep.team,
            ep.season,
            tss.conference,
            ep.avg_class_rank_4yr,
            ep.avg_class_points_4yr,
            ep.total_blue_chips_4yr,
            ep.blue_chip_ratio,
            tss.wins,
            tss.losses,
            ep.win_pct,
            tss.sp_rating,
            tss.sp_rank,
            ep.epa_per_play,
            ep.success_rate,
            (COALESCE(do2.players_drafted, (0)::bigint))::integer AS players_drafted,
            COALESCE(do2.draft_picks_value, 0) AS draft_picks_value,
            round((((tss.wins)::double precision - bm.expected_wins))::numeric, 2) AS wins_over_expected,
            round((((ep.epa_per_play)::double precision - bm.expected_epa))::numeric, 4) AS epa_over_expected,
            round(((tss.wins)::numeric / NULLIF(ep.avg_class_rank_4yr, (0)::numeric)), 4) AS recruiting_efficiency
           FROM (((expected_perf ep
             JOIN marts.team_season_summary tss ON ((((tss.team)::text = (ep.team)::text) AND (tss.season = ep.season))))
             LEFT JOIN bucket_medians bm ON (((bm.season = ep.season) AND (bm.talent_bucket = ep.talent_bucket))))
             LEFT JOIN draft_output do2 ON ((((do2.team)::text = (ep.team)::text) AND (do2.season = ep.season))))
        )
 SELECT team,
    season,
    conference,
    avg_class_rank_4yr,
    avg_class_points_4yr,
    total_blue_chips_4yr,
    blue_chip_ratio,
    wins,
    losses,
    win_pct,
    sp_rating,
    sp_rank,
    epa_per_play,
    success_rate,
    players_drafted,
    draft_picks_value,
    wins_over_expected,
    epa_over_expected,
    recruiting_efficiency,
        CASE
            WHEN (win_pct IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY win_pct)
            ELSE NULL::double precision
        END AS win_pct_pctl,
        CASE
            WHEN (epa_per_play IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY epa_per_play)
            ELSE NULL::double precision
        END AS epa_pctl,
        CASE
            WHEN (recruiting_efficiency IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY recruiting_efficiency)
            ELSE NULL::double precision
        END AS recruiting_efficiency_pctl
   FROM combined c
  WITH NO DATA;


--
-- Name: recruiting_roi; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.recruiting_roi AS
 SELECT team,
    season,
    conference,
    avg_class_rank_4yr,
    avg_class_points_4yr,
    total_blue_chips_4yr,
    blue_chip_ratio,
    wins,
    losses,
    win_pct,
    sp_rating,
    sp_rank,
    epa_per_play,
    success_rate,
    players_drafted,
    draft_picks_value,
    wins_over_expected,
    epa_over_expected,
    recruiting_efficiency,
    win_pct_pctl,
    epa_pctl,
    recruiting_efficiency_pctl
   FROM marts.recruiting_roi;


--
-- Name: VIEW recruiting_roi; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.recruiting_roi IS 'Recruiting ROI: 4-year rolling recruiting investment vs on-field outcomes. One row per team-season. blue_chip_ratio = 4+5 star ratio. recruiting_efficiency = wins / avg_class_rank. wins_over_expected = actual wins - median wins for teams with similar recruiting rank.';


--
-- Name: refresh_campaigns; Type: TABLE; Schema: meta; Owner: -
--

CREATE TABLE meta.refresh_campaigns (
    campaign text NOT NULL,
    description text,
    seasons integer[] NOT NULL,
    tasks text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    last_finalized_at timestamp with time zone
);


--
-- Name: refresh_progress; Type: TABLE; Schema: meta; Owner: -
--

CREATE TABLE meta.refresh_progress (
    campaign text NOT NULL,
    task text NOT NULL,
    game_id bigint NOT NULL,
    calls integer DEFAULT 1 NOT NULL,
    refreshed_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'refreshed'::text NOT NULL,
    CONSTRAINT refresh_progress_status_check CHECK ((status = ANY (ARRAY['refreshed'::text, 'no_data'::text])))
);


--
-- Name: refresh_campaign_status; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.refresh_campaign_status AS
 WITH campaign_seasons AS (
         SELECT c.campaign,
            c.completed_at,
            c.last_finalized_at,
            unnest(c.seasons) AS season
           FROM meta.refresh_campaigns c
        ), progress_seasoned AS (
         SELECT rp.campaign,
            rp.game_id,
            rp.status,
            g.season
           FROM (meta.refresh_progress rp
             JOIN core.games g ON ((g.id = rp.game_id)))
        )
 SELECT cs.campaign,
    cs.season,
    count(DISTINCT ps.game_id) FILTER (WHERE (ps.status = 'refreshed'::text)) AS games_refreshed,
    count(DISTINCT ps.game_id) FILTER (WHERE (ps.status = 'no_data'::text)) AS games_no_data,
    cs.completed_at,
    cs.last_finalized_at
   FROM (campaign_seasons cs
     LEFT JOIN progress_seasoned ps ON (((ps.campaign = cs.campaign) AND (ps.season = cs.season))))
  GROUP BY cs.campaign, cs.season, cs.completed_at, cs.last_finalized_at;


--
-- Name: VIEW refresh_campaign_status; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.refresh_campaign_status IS 'Per (campaign, season) progress against meta.refresh_campaigns'' declared scope: games_refreshed/games_no_data are distinct game counts from meta.refresh_progress (status=''refreshed''/''no_data'' respectively), summed across every task the campaign declared -- not a per-task breakdown (query meta.refresh_progress directly for that). completed_at is set once the campaign''s full backlog has drained; last_finalized_at is the watermark of the last successful post-drain finalize (NULL = never finalized). Lets a downstream consumer scope-invalidate a cached historical answer for one season instead of distrusting an entire in-progress correction campaign''s range. Backed by meta.refresh_campaigns + meta.refresh_progress joined to core.games for season.';


