--
-- Name: rushing_plays; Type: TABLE; Schema: stats; Owner: -
--

CREATE TABLE stats.rushing_plays (
    game_id bigint NOT NULL,
    play_id character varying NOT NULL,
    drive_id character varying,
    season bigint,
    week bigint,
    season_type character varying,
    offense_id bigint,
    offense character varying,
    offense_conference character varying,
    defense_id bigint,
    defense character varying,
    defense_conference character varying,
    period bigint,
    down bigint,
    distance bigint,
    play_text character varying,
    start_yardline bigint,
    start_yards_to_goal bigint,
    rusher_id character varying,
    rusher character varying,
    rushing_yards bigint,
    rusher_yards bigint,
    is_rushing_touchdown boolean,
    is_sack boolean,
    is_kneel boolean,
    is_team_rush boolean,
    attribution_status character varying,
    direction_analysis_eligible boolean,
    parse_status character varying,
    ppa double precision,
    success boolean,
    clock__minutes bigint,
    clock__seconds bigint,
    _dlt_load_id character varying NOT NULL,
    _dlt_id character varying NOT NULL,
    rush_direction character varying
);


--
-- Name: TABLE rushing_plays; Type: COMMENT; Schema: stats; Owner: -
--

COMMENT ON TABLE stats.rushing_plays IS 'Play-grain rushing charting from CFBD /rushing/plays (spec v5.26.0). One row per rush attempt, with direction (left/middle/right/unknown), attribution status, and per-play PPA/success where charted. PK (game_id, play_id). parse_status marks charting completeness (complete/partial/invalid -- invalid is its own bucket, never counted as charted and never folded into partial or any coverage denominator). Data loaded from 2025 forward only (RUSHING_DATA_START).';


--
-- Name: COLUMN rushing_plays.attribution_status; Type: COMMENT; Schema: stats; Owner: -
--

COMMENT ON COLUMN stats.rushing_plays.attribution_status IS 'CFBD''s rusher-attribution outcome for this play: individual (cleanly attributed to one rusher -- the only status counted in player-grain aggregate totals), team (a team-credited rush with no individual rusher), multi_carrier (more than one player involved, not split to one rusher), or unmatched/ambiguous/conflict/unlinked (attribution could not be resolved to a specific player). Player-grain aggregate tables (stats.rushing_player_games/season) count team, multi_carrier, and the unresolved statuses separately on the row and exclude them from attempts/total_rushing_yards -- see those tables'' comments for the R10 non-reconciliation statement.';


--
-- Name: COLUMN rushing_plays.direction_analysis_eligible; Type: COMMENT; Schema: stats; Owner: -
--

COMMENT ON COLUMN stats.rushing_plays.direction_analysis_eligible IS 'Whether this play is eligible for direction charting at all (some plays -- e.g. kneels, certain broken plays -- are never direction-eligible regardless of charting progress). FALSE means rush_direction will never be populated for this play; TRUE means it can be, pending charting. Aggregate-row direction_eligible_attempts sums this flag.';


--
-- Name: COLUMN rushing_plays.parse_status; Type: COMMENT; Schema: stats; Owner: -
--

COMMENT ON COLUMN stats.rushing_plays.parse_status IS 'CFBD charting-completeness marker for this play: complete, partial, or invalid. invalid is its own bucket -- CFBD could not reliably chart this rush at all, so it is never counted as charted and never folded into partial or any coverage denominator (rushing_yards_available, direction_eligible_attempts, direction_available_attempts). partial means charting is incomplete (some charted-metric columns may read NULL); complete means charting has finished for this play. 2025 is expected to carry a mix of all three as an active re-charting queue; 2026+ is expected mostly complete.';


--
-- Name: COLUMN rushing_plays.ppa; Type: COMMENT; Schema: stats; Owner: -
--

COMMENT ON COLUMN stats.rushing_plays.ppa IS 'Predicted points added (PPA) for this charted rush. NULL means this play has not been charted for PPA yet.';


--
-- Name: COLUMN rushing_plays.success; Type: COMMENT; Schema: stats; Owner: -
--

COMMENT ON COLUMN stats.rushing_plays.success IS 'Whether this charted rush was a success by CFBD''s success-rate definition. NULL means this play has not been charted for success yet.';


--
-- Name: COLUMN rushing_plays.rush_direction; Type: COMMENT; Schema: stats; Owner: -
--

COMMENT ON COLUMN stats.rushing_plays.rush_direction IS 'Charted rush direction: left, middle, right, or unknown (charted as direction-eligible but a specific side has not yet been assigned). NULL means this play has not been charted for direction yet -- see direction_analysis_eligible for whether it ever will be. Aggregate-row direction_available_attempts sums the non-NULL count.';


