    defense__directions__right__line_yards_total__v_double double precision,
    defense__directions__middle__second_level_yards__v_double double precision,
    defense__directions__middle__power_success__v_double double precision,
    defense__directions__left__line_yards__v_double double precision,
    offense__line_yards_total__v_double double precision,
