CREATE MATERIALIZED VIEW marts.rushing_charting_direction_season AS
 WITH team_ids AS (
         SELECT rp.season,
            rp.offense AS team,
                CASE
                    WHEN (count(DISTINCT rp.offense_id) = 1) THEN min(rp.offense_id)
                    ELSE NULL::bigint
                END AS team_id
           FROM stats.rushing_plays rp
          WHERE (rp.offense_id IS NOT NULL)
          GROUP BY rp.season, rp.offense
        ), player_melt AS (
         SELECT rps.season,
            'player'::text AS entity_type,
            rps.player_id AS entity_id,
            rps.team,
            ti.team_id,
            'offense'::text AS side,
            d.direction,
            d.carries,
            d.yards,
            d.yards_per_carry,
            d.success_rate,
            d.ppa,
            d.total_ppa,
            d.line_yards,
            d.line_yards_total,
            d.second_level_yards,
            d.second_level_yards_total,
            d.open_field_yards,
            d.open_field_yards_total,
            d.stuff_rate,
            d.power_success,
            d.explosiveness,
            rps.direction_eligible_attempts,
            rps.direction_available_attempts
           FROM ((stats.rushing_player_season rps
             LEFT JOIN team_ids ti ON (((ti.season = rps.season) AND ((ti.team)::text = (rps.team)::text))))
             CROSS JOIN LATERAL ( VALUES ('left'::text,rps.directions__left__carries,(rps.directions__left__yards)::double precision,rps.directions__left__yards_per_carry,rps.directions__left__success_rate,rps.directions__left__ppa,rps.directions__left__total_ppa,rps.directions__left__line_yards,COALESCE((rps.directions__left__line_yards_total)::double precision, rps.directions__left__line_yards_total__v_double),rps.directions__left__second_level_yards,(rps.directions__left__second_level_yards_total)::double precision,rps.directions__left__open_field_yards,(rps.directions__left__open_field_yards_total)::double precision,rps.directions__left__stuff_rate,COALESCE((rps.directions__left__power_success)::double precision, rps.directions__left__power_success__v_double),rps.directions__left__explosiveness), ('middle'::text,rps.directions__middle__carries,(rps.directions__middle__yards)::double precision,COALESCE((rps.directions__middle__yards_per_carry)::double precision, rps.directions__middle__yards_per_carry__v_double),COALESCE((rps.directions__middle__success_rate)::double precision, rps.directions__middle__success_rate__v_double),COALESCE((rps.directions__middle__ppa)::double precision, rps.directions__middle__ppa__v_double),COALESCE((rps.directions__middle__total_ppa)::double precision, rps.directions__middle__total_ppa__v_double),COALESCE((rps.directions__middle__line_yards)::double precision, rps.directions__middle__line_yards__v_double),COALESCE((rps.directions__middle__line_yards_total)::double precision, rps.directions__middle__line_yards_total__v_double),COALESCE((rps.directions__middle__second_level_yards)::double precision, rps.directions__middle__second_level_yards__v_double),(rps.directions__middle__second_level_yards_total)::double precision,COALESCE((rps.directions__middle__open_field_yards)::double precision, rps.directions__middle__open_field_yards__v_double),(rps.directions__middle__open_field_yards_total)::double precision,COALESCE((rps.directions__middle__stuff_rate)::double precision, rps.directions__middle__stuff_rate__v_double),COALESCE((rps.directions__middle__power_success)::double precision, rps.directions__middle__power_success__v_double),COALESCE((rps.directions__middle__explosiveness)::double precision, rps.directions__middle__explosiveness__v_double)), ('right'::text,rps.directions__right__carries,(rps.directions__right__yards)::double precision,rps.directions__right__yards_per_carry,rps.directions__right__success_rate,rps.directions__right__ppa,rps.directions__right__total_ppa,rps.directions__right__line_yards,rps.directions__right__line_yards_total,rps.directions__right__second_level_yards,(rps.directions__right__second_level_yards_total)::double precision,rps.directions__right__open_field_yards,(rps.directions__right__open_field_yards_total)::double precision,rps.directions__right__stuff_rate,COALESCE((rps.directions__right__power_success)::double precision, rps.directions__right__power_success__v_double),rps.directions__right__explosiveness), ('unknown'::text,rps.directions__unknown__carries,(rps.directions__unknown__yards)::double precision,rps.directions__unknown__yards_per_carry,rps.directions__unknown__success_rate,rps.directions__unknown__ppa,rps.directions__unknown__total_ppa,rps.directions__unknown__line_yards,rps.directions__unknown__line_yards_total,rps.directions__unknown__second_level_yards,(rps.directions__unknown__second_level_yards_total)::double precision,rps.directions__unknown__open_field_yards,(rps.directions__unknown__open_field_yards_total)::double precision,rps.directions__unknown__stuff_rate,COALESCE((rps.directions__unknown__power_success)::double precision, rps.directions__unknown__power_success__v_double),rps.directions__unknown__explosiveness)) d(direction, carries, yards, yards_per_carry, success_rate, ppa, total_ppa, line_yards, line_yards_total, second_level_yards, second_level_yards_total, open_field_yards, open_field_yards_total, stuff_rate, power_success, explosiveness))
        ), team_offense_melt AS (
         SELECT rts.season,
            'team'::text AS entity_type,
            COALESCE((ti.team_id)::text, (rts.team)::text) AS entity_id,
            rts.team,
            ti.team_id,
            'offense'::text AS side,
            d.direction,
            d.carries,
            d.yards,
            d.yards_per_carry,
            d.success_rate,
            d.ppa,
            d.total_ppa,
            d.line_yards,
            d.line_yards_total,
            d.second_level_yards,
            d.second_level_yards_total,
            d.open_field_yards,
            d.open_field_yards_total,
            d.stuff_rate,
            d.power_success,
            d.explosiveness,
            rts.offense__direction_eligible_attempts AS direction_eligible_attempts,
            rts.offense__direction_available_attempts AS direction_available_attempts
           FROM ((stats.rushing_team_season rts
             LEFT JOIN team_ids ti ON (((ti.season = rts.season) AND ((ti.team)::text = (rts.team)::text))))
             CROSS JOIN LATERAL ( VALUES ('left'::text,rts.offense__directions__left__carries,(rts.offense__directions__left__yards)::double precision,rts.offense__directions__left__yards_per_carry,rts.offense__directions__left__success_rate,rts.offense__directions__left__ppa,rts.offense__directions__left__total_ppa,rts.offense__directions__left__line_yards,rts.offense__directions__left__line_yards_total,rts.offense__directions__left__second_level_yards,(rts.offense__directions__left__second_level_yards_total)::double precision,rts.offense__directions__left__open_field_yards,(rts.offense__directions__left__open_field_yards_total)::double precision,rts.offense__directions__left__stuff_rate,rts.offense__directions__left__power_success,rts.offense__directions__left__explosiveness), ('middle'::text,rts.offense__directions__middle__carries,(rts.offense__directions__middle__yards)::double precision,rts.offense__directions__middle__yards_per_carry,rts.offense__directions__middle__success_rate,rts.offense__directions__middle__ppa,rts.offense__directions__middle__total_ppa,rts.offense__directions__middle__line_yards,rts.offense__directions__middle__line_yards_total,rts.offense__directions__middle__second_level_yards,(rts.offense__directions__middle__second_level_yards_total)::double precision,rts.offense__directions__middle__open_field_yards,(rts.offense__directions__middle__open_field_yards_total)::double precision,rts.offense__directions__middle__stuff_rate,rts.offense__directions__middle__power_success,rts.offense__directions__middle__explosiveness), ('right'::text,rts.offense__directions__right__carries,(rts.offense__directions__right__yards)::double precision,rts.offense__directions__right__yards_per_carry,rts.offense__directions__right__success_rate,rts.offense__directions__right__ppa,rts.offense__directions__right__total_ppa,rts.offense__directions__right__line_yards,rts.offense__directions__right__line_yards_total,rts.offense__directions__right__second_level_yards,(rts.offense__directions__right__second_level_yards_total)::double precision,rts.offense__directions__right__open_field_yards,(rts.offense__directions__right__open_field_yards_total)::double precision,rts.offense__directions__right__stuff_rate,rts.offense__directions__right__power_success,rts.offense__directions__right__explosiveness), ('unknown'::text,rts.offense__directions__unknown__carries,(rts.offense__directions__unknown__yards)::double precision,rts.offense__directions__unknown__yards_per_carry,rts.offense__directions__unknown__success_rate,rts.offense__directions__unknown__ppa,rts.offense__directions__unknown__total_ppa,rts.offense__directions__unknown__line_yards,rts.offense__directions__unknown__line_yards_total,rts.offense__directions__unknown__second_level_yards,(rts.offense__directions__unknown__second_level_yards_total)::double precision,rts.offense__directions__unknown__open_field_yards,(rts.offense__directions__unknown__open_field_yards_total)::double precision,rts.offense__directions__unknown__stuff_rate,rts.offense__directions__unknown__power_success,rts.offense__directions__unknown__explosiveness)) d(direction, carries, yards, yards_per_carry, success_rate, ppa, total_ppa, line_yards, line_yards_total, second_level_yards, second_level_yards_total, open_field_yards, open_field_yards_total, stuff_rate, power_success, explosiveness))
        ), team_defense_melt AS (
         SELECT rts.season,
            'team'::text AS entity_type,
            COALESCE((ti.team_id)::text, (rts.team)::text) AS entity_id,
            rts.team,
            ti.team_id,
            'defense'::text AS side,
            d.direction,
            d.carries,
            d.yards,
            d.yards_per_carry,
            d.success_rate,
            d.ppa,
            d.total_ppa,
            d.line_yards,
            d.line_yards_total,
            d.second_level_yards,
            d.second_level_yards_total,
            d.open_field_yards,
            d.open_field_yards_total,
            d.stuff_rate,
            d.power_success,
            d.explosiveness,
            rts.defense__direction_eligible_attempts AS direction_eligible_attempts,
            rts.defense__direction_available_attempts AS direction_available_attempts
           FROM ((stats.rushing_team_season rts
             LEFT JOIN team_ids ti ON (((ti.season = rts.season) AND ((ti.team)::text = (rts.team)::text))))
             CROSS JOIN LATERAL ( VALUES ('left'::text,rts.defense__directions__left__carries,(rts.defense__directions__left__yards)::double precision,rts.defense__directions__left__yards_per_carry,rts.defense__directions__left__success_rate,rts.defense__directions__left__ppa,rts.defense__directions__left__total_ppa,COALESCE((rts.defense__directions__left__line_yards)::double precision, rts.defense__directions__left__line_yards__v_double),rts.defense__directions__left__line_yards_total,rts.defense__directions__left__second_level_yards,(rts.defense__directions__left__second_level_yards_total)::double precision,rts.defense__directions__left__open_field_yards,(rts.defense__directions__left__open_field_yards_total)::double precision,rts.defense__directions__left__stuff_rate,rts.defense__directions__left__power_success,rts.defense__directions__left__explosiveness), ('middle'::text,rts.defense__directions__middle__carries,(rts.defense__directions__middle__yards)::double precision,rts.defense__directions__middle__yards_per_carry,rts.defense__directions__middle__success_rate,rts.defense__directions__middle__ppa,rts.defense__directions__middle__total_ppa,rts.defense__directions__middle__line_yards,rts.defense__directions__middle__line_yards_total,COALESCE((rts.defense__directions__middle__second_level_yards)::double precision, rts.defense__directions__middle__second_level_yards__v_double),(rts.defense__directions__middle__second_level_yards_total)::double precision,rts.defense__directions__middle__open_field_yards,(rts.defense__directions__middle__open_field_yards_total)::double precision,rts.defense__directions__middle__stuff_rate,COALESCE((rts.defense__directions__middle__power_success)::double precision, rts.defense__directions__middle__power_success__v_double),rts.defense__directions__middle__explosiveness), ('right'::text,rts.defense__directions__right__carries,(rts.defense__directions__right__yards)::double precision,rts.defense__directions__right__yards_per_carry,rts.defense__directions__right__success_rate,rts.defense__directions__right__ppa,rts.defense__directions__right__total_ppa,rts.defense__directions__right__line_yards,COALESCE((rts.defense__directions__right__line_yards_total)::double precision, rts.defense__directions__right__line_yards_total__v_double),rts.defense__directions__right__second_level_yards,(rts.defense__directions__right__second_level_yards_total)::double precision,rts.defense__directions__right__open_field_yards,(rts.defense__directions__right__open_field_yards_total)::double precision,rts.defense__directions__right__stuff_rate,COALESCE((rts.defense__directions__right__power_success)::double precision, rts.defense__directions__right__power_success__v_double),rts.defense__directions__right__explosiveness), ('unknown'::text,rts.defense__directions__unknown__carries,(rts.defense__directions__unknown__yards)::double precision,rts.defense__directions__unknown__yards_per_carry,rts.defense__directions__unknown__success_rate,rts.defense__directions__unknown__ppa,rts.defense__directions__unknown__total_ppa,rts.defense__directions__unknown__line_yards,rts.defense__directions__unknown__line_yards_total,rts.defense__directions__unknown__second_level_yards,(rts.defense__directions__unknown__second_level_yards_total)::double precision,rts.defense__directions__unknown__open_field_yards,(rts.defense__directions__unknown__open_field_yards_total)::double precision,rts.defense__directions__unknown__stuff_rate,rts.defense__directions__unknown__power_success,rts.defense__directions__unknown__explosiveness)) d(direction, carries, yards, yards_per_carry, success_rate, ppa, total_ppa, line_yards, line_yards_total, second_level_yards, second_level_yards_total, open_field_yards, open_field_yards_total, stuff_rate, power_success, explosiveness))
        )
 SELECT player_melt.season,
