 SELECT season,
    entity_type,
    entity_id,
    team,
    team_id,
    side,
    direction,
    carries,
    yards,
    yards_per_carry,
    success_rate,
    ppa,
    total_ppa,
    line_yards,
    line_yards_total,
    second_level_yards,
    second_level_yards_total,
    open_field_yards,
    open_field_yards_total,
