   FROM marts.rushing_charting_player_season;


--
-- Name: VIEW rushing_charting_player_season; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.rushing_charting_player_season IS 'Rushing charting by player-season (2025+): season, player_id, player, team, conference, position, attempts, rushing_yards_available, individual_attempts, unattributed_attempts, sacks, kneels, team_rushes, multi_carrier_attempts, direction_eligible_attempts, direction_available_attempts, total_rushing_yards, yards_per_carry, success_rate, ppa, total_ppa, line_yards, line_yards_total, second_level_yards, second_level_yards_total, open_field_yards, open_field_yards_total, stuff_rate, power_success, explosiveness. NULL on a rate/yardage-tier metric means those carries were not charted (0 is a real value); rushing_yards_available (yardage tiers) and direction_eligible_attempts/direction_available_attempts (direction splits) are the coverage denominators and are never interchangeable. CONTRACT (R10): player totals never reconcile to team totals in api.rushing_charting_team_season -- CFBD attributes some carries to team-only/multi-carrier/unresolved buckets that never attach to a player. Per-direction splits for these same player-seasons live in api.rushing_charting_direction_season. Backed by marts.rushing_charting_player_season.';


--
-- Name: rushing_charting_team_season; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.rushing_charting_team_season AS
 WITH team_ids AS (
         SELECT rp.season,
            rp.offense AS team,
                CASE
                    WHEN (count(DISTINCT rp.offense_id) = 1) THEN min(rp.offense_id)
                    ELSE NULL::bigint
                END AS team_id
           FROM stats.rushing_plays rp
          WHERE (rp.offense_id IS NOT NULL)
          GROUP BY rp.season, rp.offense
        )
 SELECT rts.season,
    ti.team_id,
    rts.team,
    rts.conference,
    rts.offense__attempts AS offense_attempts,
    rts.offense__rushing_yards_available AS offense_rushing_yards_available,
    (rts.offense__total_rushing_yards)::double precision AS offense_total_rushing_yards,
    rts.offense__yards_per_carry AS offense_yards_per_carry,
    rts.offense__individual_attempts AS offense_individual_attempts,
    rts.offense__unattributed_attempts AS offense_unattributed_attempts,
    rts.offense__sacks AS offense_sacks,
    rts.offense__kneels AS offense_kneels,
    rts.offense__team_rushes AS offense_team_rushes,
    rts.offense__multi_carrier_attempts AS offense_multi_carrier_attempts,
    rts.offense__direction_eligible_attempts AS offense_direction_eligible_attempts,
    rts.offense__direction_available_attempts AS offense_direction_available_attempts,
    rts.offense__success_rate AS offense_success_rate,
    rts.offense__ppa AS offense_ppa,
    rts.offense__total_ppa AS offense_total_ppa,
    rts.offense__line_yards AS offense_line_yards,
    COALESCE((rts.offense__line_yards_total)::double precision, rts.offense__line_yards_total__v_double) AS offense_line_yards_total,
    COALESCE((rts.offense__second_level_yards)::double precision, rts.offense__second_level_yards__v_double) AS offense_second_level_yards,
    (rts.offense__second_level_yards_total)::double precision AS offense_second_level_yards_total,
    COALESCE((rts.offense__open_field_yards)::double precision, rts.offense__open_field_yards__v_double) AS offense_open_field_yards,
    (rts.offense__open_field_yards_total)::double precision AS offense_open_field_yards_total,
    rts.offense__stuff_rate AS offense_stuff_rate,
    rts.offense__power_success AS offense_power_success,
    rts.offense__explosiveness AS offense_explosiveness,
    rts.offense__touchdown_status_available AS offense_touchdown_status_available,
    rts.offense__rushing_touchdowns AS offense_rushing_touchdowns,
    rts.defense__attempts AS defense_attempts,
    rts.defense__rushing_yards_available AS defense_rushing_yards_available,
    (rts.defense__total_rushing_yards)::double precision AS defense_total_rushing_yards,
    rts.defense__yards_per_carry AS defense_yards_per_carry,
    rts.defense__individual_attempts AS defense_individual_attempts,
    rts.defense__unattributed_attempts AS defense_unattributed_attempts,
    rts.defense__sacks AS defense_sacks,
    rts.defense__kneels AS defense_kneels,
    rts.defense__team_rushes AS defense_team_rushes,
    rts.defense__multi_carrier_attempts AS defense_multi_carrier_attempts,
    rts.defense__direction_eligible_attempts AS defense_direction_eligible_attempts,
    rts.defense__direction_available_attempts AS defense_direction_available_attempts,
    rts.defense__success_rate AS defense_success_rate,
    rts.defense__ppa AS defense_ppa,
    rts.defense__total_ppa AS defense_total_ppa,
    rts.defense__line_yards AS defense_line_yards,
    rts.defense__line_yards_total AS defense_line_yards_total,
    rts.defense__second_level_yards AS defense_second_level_yards,
    (rts.defense__second_level_yards_total)::double precision AS defense_second_level_yards_total,
    rts.defense__open_field_yards AS defense_open_field_yards,
    (rts.defense__open_field_yards_total)::double precision AS defense_open_field_yards_total,
    rts.defense__stuff_rate AS defense_stuff_rate,
    rts.defense__power_success AS defense_power_success,
    rts.defense__explosiveness AS defense_explosiveness,
    rts.defense__touchdown_status_available AS defense_touchdown_status_available,
    rts.defense__rushing_touchdowns AS defense_rushing_touchdowns
   FROM (stats.rushing_team_season rts
     LEFT JOIN team_ids ti ON (((ti.season = rts.season) AND ((ti.team)::text = (rts.team)::text))))
  WITH NO DATA;


