--
-- Name: team_detail; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.team_detail AS
 SELECT t.school,
    t.mascot,
    t.abbreviation,
    t.color,
    t.alternate_color,
    logo.value AS logo_url,
    t.conference,
    t.classification,
    tss.season AS current_season,
    tss.games,
    tss.wins,
    tss.losses,
    tss.conf_wins,
    tss.conf_losses,
    tss.ppg,
    tss.opp_ppg,
    tss.avg_margin,
    tss.sp_rating,
    tss.sp_rank,
    tss.sp_offense,
    tss.sp_defense,
    tss.elo,
    tss.fpi,
    tss.core_overall,
    tss.core_offense,
    tss.core_defense,
    epa.epa_per_play,
    epa.epa_tier,
    epa.success_rate,
    epa.explosiveness,
    tss.recruiting_rank,
    tss.recruiting_points
   FROM (((ref.teams t
     LEFT JOIN LATERAL ( SELECT teams__logos.value
           FROM ref.teams__logos
          WHERE (((teams__logos._dlt_parent_id)::text = (t._dlt_id)::text) AND (teams__logos._dlt_list_idx = 0))
         LIMIT 1) logo ON (true))
     LEFT JOIN LATERAL ( SELECT team_season_summary.team,
            team_season_summary.conference,
            team_season_summary.season,
            team_season_summary.games,
            team_season_summary.wins,
            team_season_summary.losses,
            team_season_summary.conf_wins,
            team_season_summary.conf_losses,
            team_season_summary.ppg,
            team_season_summary.opp_ppg,
            team_season_summary.avg_margin,
            team_season_summary.sp_rating,
            team_season_summary.sp_rank,
            team_season_summary.sp_offense,
            team_season_summary.sp_defense,
            team_season_summary.elo,
            team_season_summary.fpi,
            team_season_summary.core_overall,
            team_season_summary.core_offense,
            team_season_summary.core_defense,
            team_season_summary.recruiting_rank,
            team_season_summary.recruiting_points
           FROM marts.team_season_summary
          WHERE ((team_season_summary.team)::text = (t.school)::text)
          ORDER BY team_season_summary.season DESC
         LIMIT 1) tss ON (true))
     LEFT JOIN LATERAL ( SELECT team_epa_season.team,
            team_epa_season.season,
            team_epa_season.epa_per_play,
            team_epa_season.success_rate,
            team_epa_season.explosiveness,
            team_epa_season.epa_tier,
            team_epa_season.total_plays,
            team_epa_season.games_played
           FROM marts.team_epa_season
          WHERE ((team_epa_season.team)::text = (t.school)::text)
          ORDER BY team_epa_season.season DESC
         LIMIT 1) epa ON (true))
  WHERE ((t.classification)::text = 'fbs'::text);


--
-- Name: VIEW team_detail; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.team_detail IS 'Team page data with current season stats, ratings, and EPA metrics';


--
-- Name: house_elo; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.house_elo AS
 WITH team_games AS (
         SELECT house_elo_game.home_team AS team,
            house_elo_game.season,
            house_elo_game.home_postgame_elo AS postgame_elo,
            house_elo_game.start_date,
            house_elo_game.game_id
           FROM analytics.house_elo_game
        UNION ALL
         SELECT house_elo_game.away_team AS team,
            house_elo_game.season,
            house_elo_game.away_postgame_elo AS postgame_elo,
            house_elo_game.start_date,
            house_elo_game.game_id
           FROM analytics.house_elo_game
        ), season_end AS (
         SELECT DISTINCT ON (team_games.team, team_games.season) team_games.team,
            team_games.season,
            team_games.postgame_elo AS season_end_elo
           FROM team_games
          ORDER BY team_games.team, team_games.season, team_games.start_date DESC NULLS LAST, team_games.game_id DESC
        ), games_count AS (
         SELECT team_games.team,
            team_games.season,
            count(*) AS games_played
           FROM team_games
          GROUP BY team_games.team, team_games.season
        )
 SELECT se.team,
    se.season,
    se.season_end_elo,
    rank() OVER (PARTITION BY se.season ORDER BY se.season_end_elo DESC) AS elo_rank,
    gc.games_played,
    ((gc.games_played < 4) OR (se.season < 1900)) AS low_confidence,
    er.elo AS cfbd_elo
   FROM ((season_end se
     JOIN games_count gc ON ((((gc.team)::text = (se.team)::text) AND (gc.season = se.season))))
     LEFT JOIN ratings.elo_ratings er ON (((er.year = se.season) AND ((er.team)::text = (se.team)::text))))
  WITH NO DATA;


--
-- Name: team_elo; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.team_elo AS
 SELECT team,
    season,
    season_end_elo,
    elo_rank,
    games_played,
    low_confidence,
    cfbd_elo
   FROM marts.house_elo;


--
-- Name: VIEW team_elo; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.team_elo IS 'Season-end house Elo rating per team per season. Columns: team, season, season_end_elo, elo_rank, games_played, low_confidence, cfbd_elo. low_confidence flags teams with <4 games in the season or seasons before 1900; cfbd_elo is CFBD''s own Elo (coverage ~2015+) for side-by-side comparison only. Backed by marts.house_elo.';


