-- Name: team_history; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.team_history AS
 SELECT tss.team,
    tss.season,
    tss.conference,
    tss.games,
    tss.wins,
    tss.losses,
    tss.conf_wins,
    tss.conf_losses,
    tss.ppg,
    tss.opp_ppg,
    tss.avg_margin,
    tss.sp_rating,
    tss.sp_rank,
    tss.sp_offense,
    tss.sp_defense,
    tss.elo,
    tss.fpi,
    tss.core_overall,
    tss.core_offense,
    tss.core_defense,
    epa.epa_per_play,
    epa.epa_tier,
    epa.success_rate,
    epa.explosiveness,
    epa.total_plays,
    tss.recruiting_rank,
    tss.recruiting_points
   FROM (marts.team_season_summary tss
     LEFT JOIN marts.team_epa_season epa ON ((((epa.team)::text = (tss.team)::text) AND (epa.season = tss.season))))
  ORDER BY tss.team, tss.season DESC;


