COMMENT ON VIEW api.team_history IS 'Multi-season team history with records, ratings (incl. SP+ offense/defense split and CORE, 2016+), and EPA trends';


--
-- Name: team_penalty_box; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_penalty_box AS
 WITH box AS (
         SELECT gts.id AS game_id,
            t.team,
            t.home_away,
            max((
                CASE
                    WHEN ((s.category)::text = 'totalPenaltiesYards'::text) THEN s.stat
                    ELSE NULL::character varying
                END)::text) AS pen_raw
           FROM ((core.game_team_stats gts
             JOIN core.game_team_stats__teams t ON (((t._dlt_parent_id)::text = (gts._dlt_id)::text)))
             JOIN core.game_team_stats__teams__stats s ON (((s._dlt_parent_id)::text = (t._dlt_id)::text)))
          GROUP BY gts.id, t.team, t.home_away
        ), parsed AS (
         SELECT box.game_id,
            box.team,
            box.home_away,
            (NULLIF(split_part(box.pen_raw, '-'::text, 1), ''::text))::integer AS penalties,
            (NULLIF(split_part(box.pen_raw, '-'::text, 2), ''::text))::integer AS penalty_yards
           FROM box
          WHERE (box.pen_raw IS NOT NULL)
        )
 SELECT p.game_id,
    g.season,
    g.week,
    g.season_type,
    p.team,
    opp.team AS opponent,
    p.home_away,
    p.penalties,
    p.penalty_yards,
    opp.penalties AS opponent_penalties,
    opp.penalty_yards AS opponent_penalty_yards
   FROM ((parsed p
     JOIN core.games g ON ((g.id = p.game_id)))
     LEFT JOIN parsed opp ON (((opp.game_id = p.game_id) AND ((opp.team)::text <> (p.team)::text))))
  WITH NO DATA;


--
-- Name: team_penalties; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.team_penalties AS
 SELECT game_id,
    season,
    week,
    season_type,
    team,
    opponent,
    home_away,
    penalties,
    penalty_yards,
    opponent_penalties,
    opponent_penalty_yards
   FROM marts.team_penalty_box;


--
-- Name: VIEW team_penalties; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.team_penalties IS 'Official box-score penalty counts per (game, team), 2004+: penalties/penalty_yards committed by team, opponent_* committed against them (from CFBD totalPenaltiesYards). Aggregate over season for per-game averages; use api.penalty_log for infraction-level detail (holding, PI, ...).';


--
-- Name: play_epa; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.play_epa AS
 SELECT id AS play_id,
    game_id,
    drive_id,
    season,
    offense,
    defense,
    down,
    distance,
    yards_to_goal,
    yards_gained,
    play_type,
    play_text,
    scoring,
    period,
    ppa AS epa,
        CASE
            WHEN (ppa > (0)::double precision) THEN 1
            ELSE 0
        END AS success,
        CASE
            WHEN (ppa > (0.5)::double precision) THEN 1
            ELSE 0
        END AS explosive,
        CASE
            WHEN (down = 1) THEN 'first'::text
            WHEN (down = 2) THEN 'second'::text
            WHEN (down = 3) THEN 'third'::text
            WHEN (down = 4) THEN 'fourth'::text
            ELSE NULL::text
        END AS down_name,
        CASE
            WHEN (distance <= 3) THEN 'short'::text
            WHEN (distance <= 7) THEN 'medium'::text
            ELSE 'long'::text
        END AS distance_bucket,
        CASE
            WHEN (yards_to_goal <= 20) THEN 'red_zone'::text
            WHEN (yards_to_goal <= 40) THEN 'opponent_territory'::text
            WHEN (yards_to_goal <= 60) THEN 'midfield'::text
            ELSE 'own_territory'::text
        END AS field_position,
        CASE
            WHEN (((period = 4) AND (abs(COALESCE(score_diff, 0)) > 28)) OR ((period >= 3) AND (abs(COALESCE(score_diff, 0)) > 35))) THEN true
            ELSE false
        END AS is_garbage_time,
        CASE
            WHEN (((play_type)::text ~~* '%rush%'::text) OR ((play_type)::text ~~* '%run%'::text)) THEN 'rush'::text
            WHEN (((play_type)::text ~~* '%pass%'::text) OR ((play_type)::text ~~* '%sack%'::text)) THEN 'pass'::text
            ELSE 'other'::text
        END AS play_category
   FROM core.plays p
  WHERE ((ppa IS NOT NULL) AND ((play_type)::text <> ALL (ARRAY[('Timeout'::character varying)::text, ('End Period'::character varying)::text, ('End of Half'::character varying)::text, ('End of Game'::character varying)::text, ('Kickoff'::character varying)::text, ('Kickoff Return (Offense)'::character varying)::text])))
  WITH NO DATA;


--
-- Name: team_playcalling_tendencies; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_playcalling_tendencies AS
 WITH base_plays AS (
         SELECT pe.offense AS team,
            pe.season,
            pe.down,
            pe.distance_bucket,
            pe.field_position,
            pe.play_category,
                CASE
                    WHEN (COALESCE(p.score_diff, 0) >= 14) THEN 'big_lead'::text
                    WHEN (COALESCE(p.score_diff, 0) >= 1) THEN 'small_lead'::text
                    WHEN (COALESCE(p.score_diff, 0) = 0) THEN 'tied'::text
                    WHEN (COALESCE(p.score_diff, 0) >= '-13'::integer) THEN 'small_deficit'::text
                    ELSE 'big_deficit'::text
                END AS score_diff_bucket
           FROM (marts.play_epa pe
             JOIN core.plays p ON (((p.id)::text = (pe.play_id)::text)))
          WHERE ((NOT pe.is_garbage_time) AND (pe.play_category = ANY (ARRAY['rush'::text, 'pass'::text])))
        )
 SELECT team,
    season,
    down,
    distance_bucket,
    field_position,
    score_diff_bucket,
    count(*) AS total_plays,
    count(*) FILTER (WHERE (play_category = 'rush'::text)) AS rush_plays,
    count(*) FILTER (WHERE (play_category = 'pass'::text)) AS pass_plays,
    round(((count(*) FILTER (WHERE (play_category = 'rush'::text)))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS run_rate,
    round(((count(*) FILTER (WHERE (play_category = 'pass'::text)))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS pass_rate
   FROM base_plays
  GROUP BY team, season, down, distance_bucket, field_position, score_diff_bucket
  WITH NO DATA;


--
-- Name: team_situational_success; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_situational_success AS
 WITH base_plays AS (
         SELECT pe.offense AS team,
            pe.season,
            pe.down,
            pe.distance_bucket,
            pe.field_position,
            pe.play_category,
            pe.success,
            pe.explosive,
            pe.epa,
            pe.yards_gained,
            pe.distance,
                CASE
                    WHEN (COALESCE(p.score_diff, 0) >= 14) THEN 'big_lead'::text
                    WHEN (COALESCE(p.score_diff, 0) >= 1) THEN 'small_lead'::text
                    WHEN (COALESCE(p.score_diff, 0) = 0) THEN 'tied'::text
                    WHEN (COALESCE(p.score_diff, 0) >= '-13'::integer) THEN 'small_deficit'::text
                    ELSE 'big_deficit'::text
                END AS score_diff_bucket
           FROM (marts.play_epa pe
             JOIN core.plays p ON (((p.id)::text = (pe.play_id)::text)))
          WHERE ((NOT pe.is_garbage_time) AND (pe.play_category = ANY (ARRAY['rush'::text, 'pass'::text])))
        )
 SELECT team,
    season,
    down,
    distance_bucket,
    field_position,
    score_diff_bucket,
    count(*) AS total_plays,
        CASE
            WHEN (count(*) >= 10) THEN round(avg(success), 4)
            ELSE NULL::numeric
        END AS success_rate,
        CASE
            WHEN (count(*) >= 10) THEN round((avg(epa))::numeric, 4)
            ELSE NULL::numeric
        END AS avg_epa,
        CASE
            WHEN (count(*) >= 10) THEN round(avg(explosive), 4)
            ELSE NULL::numeric
        END AS explosive_rate,
        CASE
            WHEN (count(*) FILTER (WHERE (play_category = 'rush'::text)) >= 10) THEN round(avg(success) FILTER (WHERE (play_category = 'rush'::text)), 4)
            ELSE NULL::numeric
        END AS rush_success_rate,
        CASE
            WHEN (count(*) FILTER (WHERE (play_category = 'rush'::text)) >= 10) THEN round((avg(epa) FILTER (WHERE (play_category = 'rush'::text)))::numeric, 4)
            ELSE NULL::numeric
        END AS rush_avg_epa,
        CASE
            WHEN (count(*) FILTER (WHERE (play_category = 'pass'::text)) >= 10) THEN round(avg(success) FILTER (WHERE (play_category = 'pass'::text)), 4)
            ELSE NULL::numeric
        END AS pass_success_rate,
        CASE
            WHEN (count(*) FILTER (WHERE (play_category = 'pass'::text)) >= 10) THEN round((avg(epa) FILTER (WHERE (play_category = 'pass'::text)))::numeric, 4)
            ELSE NULL::numeric
        END AS pass_avg_epa,
        CASE
            WHEN ((down = ANY (ARRAY[(3)::bigint, (4)::bigint])) AND (count(*) >= 10)) THEN round(avg(
            CASE
                WHEN (yards_gained >= distance) THEN 1.0
                ELSE 0.0
            END), 4)
            ELSE NULL::numeric
        END AS yardage_success_rate
   FROM base_plays
  GROUP BY team, season, down, distance_bucket, field_position, score_diff_bucket
  WITH NO DATA;


--
-- Name: team_playcalling_profile; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.team_playcalling_profile AS
 WITH tendency_agg AS (
         SELECT team_playcalling_tendencies.team,
            team_playcalling_tendencies.season,
            sum(team_playcalling_tendencies.total_plays) AS total_plays,
            round((sum(team_playcalling_tendencies.rush_plays) / NULLIF(sum(team_playcalling_tendencies.total_plays), (0)::numeric)), 4) AS overall_run_rate,
            round((sum(team_playcalling_tendencies.rush_plays) FILTER (WHERE (team_playcalling_tendencies.down = ANY (ARRAY[(1)::bigint, (2)::bigint]))) / NULLIF(sum(team_playcalling_tendencies.total_plays) FILTER (WHERE (team_playcalling_tendencies.down = ANY (ARRAY[(1)::bigint, (2)::bigint]))), (0)::numeric)), 4) AS early_down_run_rate,
            round((sum(team_playcalling_tendencies.pass_plays) FILTER (WHERE (team_playcalling_tendencies.down = 3)) / NULLIF(sum(team_playcalling_tendencies.total_plays) FILTER (WHERE (team_playcalling_tendencies.down = 3)), (0)::numeric)), 4) AS third_down_pass_rate,
            round((sum(team_playcalling_tendencies.rush_plays) FILTER (WHERE (team_playcalling_tendencies.field_position = 'red_zone'::text)) / NULLIF(sum(team_playcalling_tendencies.total_plays) FILTER (WHERE (team_playcalling_tendencies.field_position = 'red_zone'::text)), (0)::numeric)), 4) AS red_zone_run_rate,
            round((sum(team_playcalling_tendencies.rush_plays) FILTER (WHERE (team_playcalling_tendencies.score_diff_bucket = ANY (ARRAY['big_lead'::text, 'small_lead'::text]))) / NULLIF(sum(team_playcalling_tendencies.total_plays) FILTER (WHERE (team_playcalling_tendencies.score_diff_bucket = ANY (ARRAY['big_lead'::text, 'small_lead'::text]))), (0)::numeric)), 4) AS leading_run_rate,
            round((sum(team_playcalling_tendencies.rush_plays) FILTER (WHERE (team_playcalling_tendencies.score_diff_bucket = ANY (ARRAY['big_deficit'::text, 'small_deficit'::text]))) / NULLIF(sum(team_playcalling_tendencies.total_plays) FILTER (WHERE (team_playcalling_tendencies.score_diff_bucket = ANY (ARRAY['big_deficit'::text, 'small_deficit'::text]))), (0)::numeric)), 4) AS trailing_run_rate
           FROM marts.team_playcalling_tendencies
          GROUP BY team_playcalling_tendencies.team, team_playcalling_tendencies.season
        ), success_agg AS (
         SELECT team_situational_success.team,
            team_situational_success.season,
            round((sum((team_situational_success.success_rate * (team_situational_success.total_plays)::numeric)) / NULLIF(sum(team_situational_success.total_plays), (0)::numeric)), 4) AS overall_success_rate,
            round((sum((team_situational_success.avg_epa * (team_situational_success.total_plays)::numeric)) / NULLIF(sum(team_situational_success.total_plays), (0)::numeric)), 4) AS overall_avg_epa,
            round((sum((team_situational_success.success_rate * (team_situational_success.total_plays)::numeric)) FILTER (WHERE (team_situational_success.down = 3)) / NULLIF(sum(team_situational_success.total_plays) FILTER (WHERE (team_situational_success.down = 3)), (0)::numeric)), 4) AS third_down_success_rate,
            round((sum((team_situational_success.success_rate * (team_situational_success.total_plays)::numeric)) FILTER (WHERE (team_situational_success.field_position = 'red_zone'::text)) / NULLIF(sum(team_situational_success.total_plays) FILTER (WHERE (team_situational_success.field_position = 'red_zone'::text)), (0)::numeric)), 4) AS red_zone_success_rate
           FROM marts.team_situational_success
          WHERE (team_situational_success.total_plays >= 10)
          GROUP BY team_situational_success.team, team_situational_success.season
        ), teams_deduped AS (
         SELECT DISTINCT ON (teams.school) teams.school,
            teams.conference
           FROM ref.teams
          ORDER BY teams.school, teams.classification
        ), combined AS (
         SELECT ta.team,
            ta.season,
            t.conference,
            tes.games_played,
            ta.overall_run_rate,
            ta.early_down_run_rate,
            ta.third_down_pass_rate,
            ta.red_zone_run_rate,
            sa.overall_success_rate,
            sa.overall_avg_epa,
            sa.third_down_success_rate,
            sa.red_zone_success_rate,
            ta.leading_run_rate,
            ta.trailing_run_rate,
            round((ta.leading_run_rate - ta.trailing_run_rate), 4) AS run_rate_delta,
            round((ta.total_plays / (NULLIF(tes.games_played, 0))::numeric), 1) AS pace_plays_per_game
           FROM (((tendency_agg ta
             LEFT JOIN success_agg sa ON ((((sa.team)::text = (ta.team)::text) AND (sa.season = ta.season))))
             LEFT JOIN marts.team_epa_season tes ON ((((tes.team)::text = (ta.team)::text) AND (tes.season = ta.season))))
             LEFT JOIN teams_deduped t ON (((t.school)::text = (ta.team)::text)))
        )
 SELECT team,
    season,
    conference,
    games_played,
    overall_run_rate,
    early_down_run_rate,
    third_down_pass_rate,
    red_zone_run_rate,
    overall_success_rate,
    overall_avg_epa,
    third_down_success_rate,
    red_zone_success_rate,
    leading_run_rate,
    trailing_run_rate,
    run_rate_delta,
    pace_plays_per_game,
        CASE
            WHEN (overall_run_rate IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY overall_run_rate)
            ELSE NULL::double precision
        END AS overall_run_rate_pctl,
        CASE
            WHEN (early_down_run_rate IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY early_down_run_rate)
            ELSE NULL::double precision
        END AS early_down_run_rate_pctl,
        CASE
            WHEN (third_down_pass_rate IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY third_down_pass_rate)
            ELSE NULL::double precision
        END AS third_down_pass_rate_pctl,
        CASE
            WHEN (overall_avg_epa IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY overall_avg_epa)
            ELSE NULL::double precision
        END AS overall_epa_pctl,
        CASE
            WHEN (third_down_success_rate IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY third_down_success_rate)
            ELSE NULL::double precision
        END AS third_down_success_pctl,
        CASE
            WHEN (red_zone_success_rate IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY red_zone_success_rate)
            ELSE NULL::double precision
        END AS red_zone_success_pctl,
        CASE
            WHEN (run_rate_delta IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY run_rate_delta)
            ELSE NULL::double precision
        END AS run_rate_delta_pctl,
        CASE
            WHEN (pace_plays_per_game IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY pace_plays_per_game)
            ELSE NULL::double precision
        END AS pace_pctl
   FROM combined c;


--
-- Name: VIEW team_playcalling_profile; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.team_playcalling_profile IS 'Team playcalling identity with situational tendencies and percentile rankings. One row per team-season. Filter by team, season, conference. Percentiles are per-season. NULL rates indicate insufficient plays in that situation. Backed by materialized views (tendencies + success).';


--
-- Name: player_returning; Type: TABLE; Schema: stats; Owner: -
--

CREATE TABLE stats.player_returning (
    season bigint NOT NULL,
    team character varying NOT NULL,
    conference character varying,
    total_ppa double precision,
    total_passing_ppa double precision,
    total_receiving_ppa bigint,
    total_rushing_ppa double precision,
    percent_ppa double precision,
    percent_passing_ppa double precision,
    percent_receiving_ppa double precision,
    percent_rushing_ppa double precision,
    usage double precision,
    passing_usage double precision,
    receiving_usage double precision,
    rushing_usage double precision,
    _dlt_load_id character varying NOT NULL,
    _dlt_id character varying NOT NULL,
    total_receiving_ppa__v_double double precision
);


--
-- Name: returning_production; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.returning_production AS
 SELECT season,
    team,
    conference,
    round((total_ppa)::numeric, 2) AS total_ppa,
    round((total_passing_ppa)::numeric, 2) AS total_passing_ppa,
    round((COALESCE((total_receiving_ppa)::double precision, total_receiving_ppa__v_double))::numeric, 2) AS total_receiving_ppa,
    round((total_rushing_ppa)::numeric, 2) AS total_rushing_ppa,
    round((percent_ppa)::numeric, 4) AS returning_ppa_pct,
    round((percent_passing_ppa)::numeric, 4) AS returning_passing_ppa_pct,
    round((percent_receiving_ppa)::numeric, 4) AS returning_receiving_ppa_pct,
    round((percent_rushing_ppa)::numeric, 4) AS returning_rushing_ppa_pct,
    round((usage)::numeric, 4) AS usage,
    round((passing_usage)::numeric, 4) AS passing_usage,
    round((receiving_usage)::numeric, 4) AS receiving_usage,
    round((rushing_usage)::numeric, 4) AS rushing_usage,
    rank() OVER (PARTITION BY season ORDER BY percent_ppa DESC NULLS LAST) AS returning_rank
   FROM stats.player_returning p
  WITH NO DATA;


--
-- Name: team_returning_production; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.team_returning_production AS
 SELECT season,
    team,
    conference,
    total_ppa,
    total_passing_ppa,
    total_receiving_ppa,
    total_rushing_ppa,
    returning_ppa_pct,
    returning_passing_ppa_pct,
    returning_receiving_ppa_pct,
    returning_rushing_ppa_pct,
    usage,
    passing_usage,
    receiving_usage,
    rushing_usage,
    returning_rank
   FROM marts.returning_production;


--
-- Name: VIEW team_returning_production; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.team_returning_production IS 'Returning production by team-season: total and percent of last season''s PPA (overall/passing/receiving/rushing) and usage returning, with returning_rank within season. Backed by marts.returning_production.';


--
-- Name: team_week; Type: TABLE; Schema: features; Owner: -
--

CREATE TABLE features.team_week (
    season bigint NOT NULL,
    season_type character varying NOT NULL,
    week bigint NOT NULL,
    week_index bigint NOT NULL,
    team character varying NOT NULL,
    conference character varying,
    game_id bigint NOT NULL,
    games_played_to_date bigint NOT NULL,
    elo_pregame numeric(8,2),
    adj_epa_off numeric(8,5),
    adj_epa_def numeric(8,5),
    adj_epa_net numeric(8,5),
    adj_epa_hfa numeric(8,5),
    adj_epa_source character varying,
    off_epa_per_play numeric(8,5),
    off_success_rate numeric(8,5),
    off_explosiveness_rate numeric(8,5),
    off_plays_per_game numeric(8,3),
    def_epa_per_play_allowed numeric(8,5),
    def_success_rate_allowed numeric(8,5),
    def_explosiveness_rate_allowed numeric(8,5),
    havoc_rate_defense numeric(8,5),
    havoc_rate_offense_allowed numeric(8,5),
    returning_ppa_pct numeric(8,4),
    returning_passing_ppa_pct numeric(8,4),
    returning_rushing_ppa_pct numeric(8,4),
    returning_usage numeric(8,4),
    preseason_sp_rating numeric(8,3),
    preseason_sp_offense numeric(8,3),
    preseason_sp_defense numeric(8,3),
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    feature_build_version character varying,
    recruiting_points_3yr numeric(10,3),
    blue_chip_pipeline numeric(6,4),
    hc_first_year numeric(2,1),
    prior_def_line_yards numeric(8,4),
    prior_def_stuff_rate numeric(8,4),
    hc_first_year_unproven numeric(2,1),
    draft_picks_3yr numeric(6,1),
    draft_departures numeric(6,1),
    off_ppd numeric(8,5)
);


--
-- Name: TABLE team_week; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON TABLE features.team_week IS 'As-of feature vector for fitted_v1, one row per (season, season_type, week, team) -- a team plays <=1 game/week, both sides of every core.games row get a row. week_index is the derived monotone ordering key (week_index = week for season_type=''regular'', 100 + week for ''postseason'', since CFBD restarts week numbering at 1 for bowls). As-of rule: the row for week_index WI uses only data with week_index < WI within the same season, plus explicitly leak-free preseason constants (returning_*, preseason_sp_*) and prior-season (S-1) fallbacks (adj_epa_* when adj_epa_source=''prior_season''), both known before the season starts. Column contract: docs/brainstorms/2026-07-21-team-week-feature-design.md section 1. Written by scripts/build_features.py.';


--
-- Name: COLUMN team_week.recruiting_points_3yr; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.recruiting_points_3yr IS 'Decayed sum of recruiting.team_recruiting.points over the four classes signed before season S (weight 0.8^(S-year-1), CLASS_WINDOW=4). Preseason-known: every class in the window signed before S began. Screened +0.2642 against season-S SP+ controlling for prior-season SP+ -- the strongest preseason signal in the candidate set, and the control every other candidate was screened against. NULL (never 0) when no recruiting rows exist for the window.';


--
-- Name: COLUMN team_week.blue_chip_pipeline; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.blue_chip_pipeline IS 'Share of signees rated 4-5 stars across the same four-class window (blue chips / total signees). Preseason-known. Screened +0.0782 controlling for prior SP+ AND recruiting_points_3yr -- BELOW the pre-registered 0.08 floor, shipped as an explicit recorded override because the shortfall is ~0.07 standard errors at n=1,439 and q=0.0095. A rate: NULL, never 0, when the window has no signees.';


--
-- Name: COLUMN team_week.hc_first_year; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.hc_first_year IS '1.0 when the head coach''s tenure at this school begins in season S, else 0.0. Tenure computed gaps-and-islands over ref.coaches__seasons so a coach returning for a second stint does not inherit the first stint''s start year. Preseason-known: the hire precedes the season. Screened -0.1615 -- the second-strongest signal in the set, and previously invisible: it was hidden inside a zero-filled regime-scoped recruiting column until the two were separated. NULL means no coach record for this school-year; 0.0 is a real value.';


--
-- Name: COLUMN team_week.prior_def_line_yards; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.prior_def_line_yards IS 'stats.advanced_team_stats.defense__line_yards for season S-1 -- line yards ALLOWED by this defense last season. Leak-free: S-1 is complete before S begins. Screened -0.0997 controlling for prior SP+ and recruiting; the sign is the trenches thesis CONFIRMED (allowing fewer line yards predicts a better season), not refuted. NULL, never 0, when the team had no prior FBS season.';


--
-- Name: COLUMN team_week.prior_def_stuff_rate; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.prior_def_stuff_rate IS 'stats.advanced_team_stats.defense__stuff_rate for season S-1 -- rate at which this defense stuffed runs at or behind the line. Leak-free: S-1 is complete before S begins. Screened +0.0816, clearing the pre-registered 0.08 floor by 0.0016; treat as marginal. NULL, never 0, when the team had no prior FBS season.';


--
-- Name: COLUMN team_week.hc_first_year_unproven; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.hc_first_year_unproven IS '1.0 when season S is the head coach''s first at this school AND he is unproven -- either no prior head-coaching season anywhere, or prior seasons averaging below 0.0 SP+ (an average FBS team). 0.0 for a continuing staff and for a first-year hire whose previous teams averaged at or above average. Career prior is his mean SP+ over seasons STRICTLY before S at any school, so S itself can never enter; S-1 can, and should, because its final SP+ publishes months before week 1. Tenure computed gaps-and-islands over ref.coaches__seasons; school-years CFBD lists multiple coaches for yield NULL rather than a guess. Screened -0.1844 controlling for prior SP+ and recruiting_points_3yr, versus +0.0096 (p=0.73) for proven hires and -0.1548 for the flat hc_first_year it replaces in the fitted_v1 vector. NULL means the classification is unknown (no coach record, or an unratable prior career); 0.0 is a real value. 100% NULL for 2026 until CFBD publishes coaching records around August.';


--
-- Name: COLUMN team_week.draft_picks_3yr; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.draft_picks_3yr IS 'Count of NFL draft picks this program produced across the three drafts before season S (draft years S-3..S-1), never season S''s own draft. Preseason-known: all three drafts concluded before week 1. Screened +0.0834 against season-S SP+ controlling for BOTH prior-season SP+ and recruiting_points_3yr, and +0.2342 controlling for prior SP+ alone -- so it is NOT merely a recruiting proxy, reversing the earlier recorded finding, which was measured on a column that was a fabricated zero on 54.2% of rows before the 2000-2019 backfill. 0.0 is a REAL value (this program produced no picks); NULL means the source drafts are absent from draft.draft_picks entirely and the count is not a measurement.';


--
-- Name: COLUMN team_week.draft_departures; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.draft_departures IS 'Count of NFL draft picks this program LOST in the April draft of year S -- players gone before the season starts. Preseason-known: the draft precedes week 1. Screened -0.0925 controlling for prior SP+ and recruiting_points_3yr: losing draftable players predicts a worse season once prior quality is held fixed. Deliberately a SEPARATE column from draft_picks_3yr rather than netted against it, because the two carry opposite signs (+0.0834 vs -0.0925) and combining them cancels most of both. The earlier recorded reading of this column as a sign-flipped confound was measured on 45.1% fabricated zeros and is withdrawn. 0.0 is a REAL value; NULL means year S''s draft is absent from draft.draft_picks.';


--
-- Name: COLUMN team_week.off_ppd; Type: COMMENT; Schema: features; Owner: -
--

COMMENT ON COLUMN features.team_week.off_ppd IS 'Offensive points per drive, season-to-date as-of entering week W: mean(end_offense_score - start_offense_score) over the team''s own offensive drives from core.drives with week_index < W, same season (exact score-delta points, not a TD=7/FG=3 estimate). NULL, never 0, when the team has no qualifying prior drive (week 1) -- same season-to-date NULL rule as off_epa_per_play. Screened at +0.0700 (v1, Elo/adj_epa_net control) and +0.0901 (v2, model-margin control, p=5.7e-12) against home margin -- the sole survivor of the six 2026-07-28 drive/trajectory candidates. Populated for transparency; enters the fitted_v1 vector only if the U4 isolated walk-forward gate passes (see docs/plans/2026-07-28-001-feat-starter-pack-model-features-plan.md).';


