CREATE MATERIALIZED VIEW marts.team_wepa_season AS
 SELECT year AS season,
    team_id,
    team,
    conference,
    round((epa__total)::numeric, 4) AS epa_total,
    round((epa__passing)::numeric, 4) AS epa_passing,
    round((epa__rushing)::numeric, 4) AS epa_rushing,
    round((epa_allowed__total)::numeric, 4) AS epa_allowed_total,
    round((epa_allowed__passing)::numeric, 4) AS epa_allowed_passing,
    round((epa_allowed__rushing)::numeric, 4) AS epa_allowed_rushing,
    round((success_rate__total)::numeric, 4) AS success_rate_total,
    round((success_rate__standard_downs)::numeric, 4) AS success_rate_standard_downs,
    round((success_rate__passing_downs)::numeric, 4) AS success_rate_passing_downs,
    round((success_rate_allowed__total)::numeric, 4) AS success_rate_allowed_total,
    round((success_rate_allowed__standard_downs)::numeric, 4) AS success_rate_allowed_standard_downs,
    round((success_rate_allowed__passing_downs)::numeric, 4) AS success_rate_allowed_passing_downs,
    round((rushing__line_yards)::numeric, 2) AS rushing_line_yards,
    round((rushing__second_level_yards)::numeric, 2) AS rushing_second_level_yards,
    round((rushing__open_field_yards)::numeric, 2) AS rushing_open_field_yards,
    round((rushing__highlight_yards)::numeric, 2) AS rushing_highlight_yards,
    round((rushing_allowed__line_yards)::numeric, 2) AS rushing_allowed_line_yards,
    round((rushing_allowed__second_level_yards)::numeric, 2) AS rushing_allowed_second_level_yards,
    round((rushing_allowed__open_field_yards)::numeric, 2) AS rushing_allowed_open_field_yards,
    round((rushing_allowed__highlight_yards)::numeric, 2) AS rushing_allowed_highlight_yards,
    round((explosiveness)::numeric, 4) AS explosiveness,
    round((explosiveness_allowed)::numeric, 4) AS explosiveness_allowed,
    rank() OVER (PARTITION BY year ORDER BY epa__total DESC NULLS LAST) AS epa_rank,
    rank() OVER (PARTITION BY year ORDER BY epa_allowed__total) AS defense_rank
   FROM metrics.wepa_team_season w
  WITH NO DATA;


