--
-- Name: transfer_portal; Type: TABLE; Schema: recruiting; Owner: -
--

CREATE TABLE recruiting.transfer_portal (
    season bigint NOT NULL,
    first_name character varying NOT NULL,
    last_name character varying NOT NULL,
    "position" character varying,
    origin character varying,
    transfer_date timestamp with time zone,
    stars bigint,
    eligibility character varying,
    _dlt_load_id character varying NOT NULL,
    _dlt_id character varying NOT NULL,
    destination character varying,
    rating double precision
);


--
-- Name: transfer_portal_impact; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.transfer_portal_impact AS
 WITH portal_in AS (
         SELECT tp.destination AS team,
            tp.season,
            count(*) AS transfers_in,
            round(avg(tp.stars), 2) AS avg_incoming_stars,
            round((avg(tp.rating))::numeric, 4) AS avg_incoming_rating,
            count(*) FILTER (WHERE (tp.stars >= 4)) AS incoming_high_stars
           FROM recruiting.transfer_portal tp
          WHERE (tp.destination IS NOT NULL)
          GROUP BY tp.destination, tp.season
        ), portal_out AS (
         SELECT tp.origin AS team,
            tp.season,
            count(*) AS transfers_out
           FROM recruiting.transfer_portal tp
          WHERE (tp.origin IS NOT NULL)
          GROUP BY tp.origin, tp.season
        ), roster_size AS (
         SELECT roster.team,
            roster.year AS season,
            count(*) AS total_roster
           FROM core.roster
          GROUP BY roster.team, roster.year
        ), team_perf AS (
         SELECT tss.team,
            tss.season,
            tss.conference,
            tss.wins,
            tss.sp_rating,
            lag(tss.wins) OVER (PARTITION BY tss.team ORDER BY tss.season) AS prior_season_wins,
            lag(tss.sp_rating) OVER (PARTITION BY tss.team ORDER BY tss.season) AS prior_season_sp_rating
           FROM marts.team_season_summary tss
        ), combined AS (
         SELECT tp.team,
            tp.season,
            tp.conference,
            (COALESCE(pi.transfers_in, (0)::bigint))::integer AS transfers_in,
            (COALESCE(po.transfers_out, (0)::bigint))::integer AS transfers_out,
            ((COALESCE(pi.transfers_in, (0)::bigint) - COALESCE(po.transfers_out, (0)::bigint)))::integer AS net_transfers,
            pi.avg_incoming_stars,
            pi.avg_incoming_rating,
            (COALESCE(pi.incoming_high_stars, (0)::bigint))::integer AS incoming_high_stars,
            tp.prior_season_wins,
            tp.prior_season_sp_rating,
            tp.wins AS current_wins,
            tp.sp_rating AS current_sp_rating,
            (tp.wins - tp.prior_season_wins) AS win_delta,
            round(((tp.sp_rating - tp.prior_season_sp_rating))::numeric, 2) AS sp_delta,
            round(((COALESCE(pi.transfers_in, (0)::bigint))::numeric / (NULLIF(rs.total_roster, 0))::numeric), 4) AS portal_dependency,
            round((((tp.wins - tp.prior_season_wins))::numeric / (NULLIF(pi.transfers_in, 0))::numeric), 4) AS win_delta_per_transfer_in
           FROM (((team_perf tp
             LEFT JOIN portal_in pi ON ((((pi.team)::text = (tp.team)::text) AND (pi.season = tp.season))))
             LEFT JOIN portal_out po ON ((((po.team)::text = (tp.team)::text) AND (po.season = tp.season))))
             LEFT JOIN roster_size rs ON ((((rs.team)::text = (tp.team)::text) AND (rs.season = tp.season))))
          WHERE ((tp.prior_season_wins IS NOT NULL) AND ((pi.transfers_in IS NOT NULL) OR (po.transfers_out IS NOT NULL)))
        )
 SELECT team,
    season,
    conference,
    transfers_in,
    transfers_out,
    net_transfers,
    avg_incoming_stars,
    avg_incoming_rating,
    incoming_high_stars,
    prior_season_wins,
    prior_season_sp_rating,
    current_wins,
    current_sp_rating,
    win_delta,
    sp_delta,
    portal_dependency,
    win_delta_per_transfer_in,
        CASE
            WHEN (net_transfers IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY net_transfers)
            ELSE NULL::double precision
        END AS net_transfers_pctl,
        CASE
            WHEN (win_delta IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY win_delta)
            ELSE NULL::double precision
        END AS win_delta_pctl,
        CASE
            WHEN (portal_dependency IS NOT NULL) THEN percent_rank() OVER (PARTITION BY season ORDER BY portal_dependency)
            ELSE NULL::double precision
        END AS portal_dependency_pctl
   FROM combined c
  WITH NO DATA;


--
-- Name: transfer_portal_impact; Type: VIEW; Schema: api; Owner: -
--

CREATE VIEW api.transfer_portal_impact AS
 SELECT team,
    season,
    conference,
    transfers_in,
    transfers_out,
    net_transfers,
    avg_incoming_stars,
    avg_incoming_rating,
    incoming_high_stars,
    prior_season_wins,
    prior_season_sp_rating,
    current_wins,
    current_sp_rating,
    win_delta,
    sp_delta,
    portal_dependency,
    win_delta_per_transfer_in,
    net_transfers_pctl,
    win_delta_pctl,
    portal_dependency_pctl
   FROM marts.transfer_portal_impact;


--
-- Name: VIEW transfer_portal_impact; Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON VIEW api.transfer_portal_impact IS 'Transfer portal impact: portal activity correlated with team performance changes. One row per team-season (portal era ~2021+). portal_dependency = transfers_in / roster_size. win_delta = current_wins - prior_season_wins.';


