--
-- Name: coach_record; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.coach_record AS
 WITH coach_seasons AS (
         SELECT c.first_name,
            c.last_name,
            (((c.first_name)::text || ' '::text) || (c.last_name)::text) AS coach_name,
            cs.school AS team,
            cs.year AS season,
            cs.games,
            cs.wins,
            cs.losses,
            cs.ties,
            cs.preseason_rank,
            cs.postseason_rank,
            cs.srs,
            cs.sp_overall,
            cs.sp_offense,
            cs.sp_defense
           FROM (ref.coaches c
             JOIN ref.coaches__seasons cs ON (((cs._dlt_parent_id)::text = (c._dlt_id)::text)))
          WHERE (cs.school IS NOT NULL)
        ), coach_team_agg AS (
         SELECT coach_seasons.coach_name,
            coach_seasons.first_name,
            coach_seasons.last_name,
            coach_seasons.team,
            min(coach_seasons.season) AS first_season,
            max(coach_seasons.season) AS last_season,
            count(DISTINCT coach_seasons.season) AS seasons_at_team,
            sum(coach_seasons.games) AS total_games,
            sum(coach_seasons.wins) AS total_wins,
            sum(coach_seasons.losses) AS total_losses,
            sum(COALESCE(coach_seasons.ties, (0)::bigint)) AS total_ties,
            min(coach_seasons.preseason_rank) FILTER (WHERE (coach_seasons.preseason_rank IS NOT NULL)) AS best_preseason_rank,
            min(coach_seasons.postseason_rank) FILTER (WHERE (coach_seasons.postseason_rank IS NOT NULL)) AS best_postseason_rank,
            round((avg(coach_seasons.sp_overall))::numeric, 2) AS avg_sp_rating
           FROM coach_seasons
          GROUP BY coach_seasons.coach_name, coach_seasons.first_name, coach_seasons.last_name, coach_seasons.team
        )
 SELECT cta.coach_name,
    cta.first_name,
    cta.last_name,
    cta.team,
    cta.first_season,
    cta.last_season,
    cta.seasons_at_team,
    (cta.total_games)::integer AS total_games,
    (cta.total_wins)::integer AS total_wins,
    (cta.total_losses)::integer AS total_losses,
    (cta.total_ties)::integer AS total_ties,
    round((cta.total_wins / NULLIF((cta.total_wins + cta.total_losses), (0)::numeric)), 4) AS win_pct,
    cta.best_preseason_rank,
    cta.best_postseason_rank,
    cta.avg_sp_rating,
    round(avg(tr.rank), 1) AS avg_recruiting_rank
   FROM (coach_team_agg cta
     LEFT JOIN recruiting.team_recruiting tr ON ((((tr.team)::text = (cta.team)::text) AND ((tr.year >= cta.first_season) AND (tr.year <= cta.last_season)))))
  GROUP BY cta.coach_name, cta.first_name, cta.last_name, cta.team, cta.first_season, cta.last_season, cta.seasons_at_team, cta.total_games, cta.total_wins, cta.total_losses, cta.total_ties, cta.best_preseason_rank, cta.best_postseason_rank, cta.avg_sp_rating
  WITH NO DATA;


--
-- Name: conference_era_summary; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.conference_era_summary AS
 WITH conference_seasons AS (
         SELECT e.era_code,
            e.era_name,
            t.season,
            g.home_conference AS conference,
            (avg(t.epa_per_play))::numeric(6,4) AS avg_epa,
            (avg(t.success_rate))::numeric(5,3) AS avg_success_rate,
            count(DISTINCT t.team) AS teams
           FROM ((marts.team_epa_season t
             JOIN core.games g ON ((((t.team)::text = (g.home_team)::text) AND (t.season = g.season))))
             CROSS JOIN LATERAL ref.get_era((t.season)::integer) e(era_code, era_name))
          WHERE ((g.home_conference IS NOT NULL) AND ((g.home_conference)::text <> ''::text))
          GROUP BY e.era_code, e.era_name, t.season, g.home_conference
        )
 SELECT era_code,
    era_name,
    conference,
    count(DISTINCT season) AS seasons,
    (avg(avg_epa))::numeric(6,4) AS avg_epa,
    (avg(avg_success_rate))::numeric(5,3) AS avg_success_rate,
    (avg(teams))::numeric(4,1) AS avg_teams,
    (max(avg_epa))::numeric(6,4) AS best_season_epa,
    (min(avg_epa))::numeric(6,4) AS worst_season_epa,
    rank() OVER (PARTITION BY era_code ORDER BY (avg(avg_epa)) DESC) AS era_rank
   FROM conference_seasons
  GROUP BY era_code, era_name, conference
  WITH NO DATA;


--
-- Name: conference_head_to_head; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.conference_head_to_head AS
 WITH conf_games AS (
         SELECT g.season,
            LEAST(g.home_conference, g.away_conference) AS conference_1,
            GREATEST(g.home_conference, g.away_conference) AS conference_2,
            g.home_conference,
            g.away_conference,
            g.home_points,
            g.away_points,
            (g.home_points - g.away_points) AS point_diff
           FROM core.games g
          WHERE ((g.completed = true) AND (g.home_conference IS NOT NULL) AND (g.away_conference IS NOT NULL) AND ((g.home_conference)::text <> (g.away_conference)::text) AND (g.home_points IS NOT NULL) AND (g.away_points IS NOT NULL))
        )
 SELECT conference_1,
    conference_2,
    season,
    (count(*))::integer AS total_games,
    (count(*) FILTER (WHERE ((((home_conference)::text = (conference_1)::text) AND (home_points > away_points)) OR (((away_conference)::text = (conference_1)::text) AND (away_points > home_points)))))::integer AS conf1_wins,
    (count(*) FILTER (WHERE ((((home_conference)::text = (conference_2)::text) AND (home_points > away_points)) OR (((away_conference)::text = (conference_2)::text) AND (away_points > home_points)))))::integer AS conf2_wins,
    (count(*) FILTER (WHERE (home_points = away_points)))::integer AS ties,
    round(((count(*) FILTER (WHERE ((((home_conference)::text = (conference_1)::text) AND (home_points > away_points)) OR (((away_conference)::text = (conference_1)::text) AND (away_points > home_points)))))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS conf1_win_pct,
    round(avg(
        CASE
            WHEN ((home_conference)::text = (conference_1)::text) THEN (home_points - away_points)
            ELSE (away_points - home_points)
        END), 2) AS avg_point_diff
   FROM conf_games
  GROUP BY conference_1, conference_2, season
  WITH NO DATA;


--
-- Name: data_freshness; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.data_freshness AS
 WITH tracked_tables AS (
         SELECT t.schema_name,
            t.table_name,
            t.expected_refresh_frequency
           FROM ( VALUES ('ref'::text,'teams'::text,'static'::text), ('ref'::text,'conferences'::text,'static'::text), ('ref'::text,'venues'::text,'static'::text), ('ref'::text,'coaches'::text,'seasonal'::text), ('core'::text,'games'::text,'weekly'::text), ('core'::text,'drives'::text,'weekly'::text), ('core'::text,'plays'::text,'weekly'::text), ('core'::text,'game_team_stats'::text,'weekly'::text), ('core'::text,'game_player_stats'::text,'weekly'::text), ('core'::text,'roster'::text,'seasonal'::text), ('stats'::text,'player_season_stats'::text,'seasonal'::text), ('stats'::text,'team_season_stats'::text,'seasonal'::text), ('ratings'::text,'sp_ratings'::text,'weekly'::text), ('ratings'::text,'elo_ratings'::text,'weekly'::text), ('ratings'::text,'fpi_ratings'::text,'seasonal'::text), ('ratings'::text,'srs_ratings'::text,'seasonal'::text), ('ratings'::text,'core_ratings'::text,'weekly'::text), ('recruiting'::text,'recruits'::text,'seasonal'::text), ('recruiting'::text,'team_recruiting'::text,'seasonal'::text), ('recruiting'::text,'transfer_portal'::text,'seasonal'::text), ('betting'::text,'lines'::text,'weekly'::text), ('draft'::text,'draft_picks'::text,'seasonal'::text), ('metrics'::text,'ppa_predicted'::text,'static'::text), ('metrics'::text,'win_probability'::text,'weekly'::text)) t(schema_name, table_name, expected_refresh_frequency)
        ), table_stats AS (
         SELECT ((root.relnamespace)::regnamespace)::text AS schema_name,
            root.relname AS table_name,
            (sum(GREATEST(c.reltuples, (0)::real)))::bigint AS row_count,
            max(GREATEST(s.last_vacuum, s.last_autovacuum, s.last_analyze, s.last_autoanalyze)) AS last_activity_recorded,
            sum(((s.n_tup_ins + s.n_tup_upd) + s.n_tup_del)) AS writes_since_reset
           FROM ((pg_stat_user_tables s
             JOIN pg_class c ON ((s.relid = c.oid)))
             JOIN pg_class root ON ((root.oid = (COALESCE(pg_partition_root((s.relid)::regclass), (s.relid)::regclass))::oid)))
          WHERE (c.relkind <> 'p'::"char")
          GROUP BY root.relnamespace, root.relname
        ), freshness AS (
         SELECT tt.schema_name,
            tt.table_name,
            COALESCE(ts.row_count, (0)::bigint) AS row_count,
            COALESCE(ts.last_activity_recorded,
                CASE
                    WHEN (ts.writes_since_reset > (0)::numeric) THEN pg_postmaster_start_time()
                    ELSE NULL::timestamp with time zone
                END) AS last_activity,
            tt.expected_refresh_frequency
           FROM (tracked_tables tt
             LEFT JOIN table_stats ts ON (((ts.schema_name = tt.schema_name) AND (ts.table_name = tt.table_name))))
        )
 SELECT schema_name,
    table_name,
    row_count,
    last_activity,
    expected_refresh_frequency,
        CASE
            WHEN (last_activity IS NOT NULL) THEN round((EXTRACT(epoch FROM (now() - last_activity)) / 86400.0), 1)
            ELSE NULL::numeric
        END AS days_since_activity,
        CASE
            WHEN (expected_refresh_frequency = 'static'::text) THEN false
            WHEN ((expected_refresh_frequency = 'weekly'::text) AND ((last_activity IS NULL) OR (last_activity < (now() - '14 days'::interval)))) THEN true
            WHEN ((expected_refresh_frequency = 'seasonal'::text) AND ((last_activity IS NULL) OR (last_activity < (now() - '90 days'::interval)))) THEN true
            ELSE false
        END AS is_stale
   FROM freshness
  ORDER BY schema_name, table_name
  WITH NO DATA;


