--
-- Name: defensive_havoc; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.defensive_havoc AS
 WITH defensive_plays AS (
         SELECT p.defense AS team,
            g.season,
            p.ppa,
            p.play_type,
            (NOT (((p.period = 4) AND (abs(COALESCE(p.score_diff, 0)) > 28)) OR ((p.period >= 3) AND (abs(COALESCE(p.score_diff, 0)) > 35)))) AS is_competitive,
                CASE
                    WHEN ((p.play_type)::text ~~* '%sack%'::text) THEN 1
                    ELSE 0
                END AS is_sack,
                CASE
                    WHEN ((p.play_type)::text ~~* '%interception%'::text) THEN 1
                    ELSE 0
                END AS is_interception,
                CASE
                    WHEN ((p.play_type)::text ~~* '%fumble%'::text) THEN 1
                    ELSE 0
                END AS is_fumble,
                CASE
                    WHEN ((((p.play_type)::text ~~* '%rush%'::text) OR ((p.play_type)::text ~~* '%run%'::text)) AND (COALESCE(p.yards_gained, (0)::bigint) <= 0)) THEN true
                    ELSE false
                END AS is_stuff,
                CASE
                    WHEN (COALESCE(p.yards_gained, (0)::bigint) < 0) THEN true
                    ELSE false
                END AS is_tfl
           FROM (core.plays p
             JOIN core.games g ON ((p.game_id = g.id)))
          WHERE (p.defense IS NOT NULL)
        ), plays_agg AS (
         SELECT defensive_plays.team,
            defensive_plays.season,
            count(*) FILTER (WHERE defensive_plays.is_competitive) AS defensive_plays,
            round((avg(defensive_plays.ppa) FILTER (WHERE defensive_plays.is_competitive))::numeric, 4) AS opp_epa_per_play,
            round(avg(
                CASE
                    WHEN (defensive_plays.ppa > (0)::double precision) THEN 1.0
                    ELSE 0.0
                END) FILTER (WHERE defensive_plays.is_competitive), 4) AS opp_success_rate,
            (sum(
                CASE
                    WHEN defensive_plays.is_competitive THEN defensive_plays.is_sack
                    ELSE 0
                END))::integer AS sacks,
            (sum(
                CASE
                    WHEN defensive_plays.is_competitive THEN defensive_plays.is_interception
                    ELSE 0
                END))::integer AS interceptions,
            (sum(
                CASE
                    WHEN defensive_plays.is_competitive THEN defensive_plays.is_fumble
                    ELSE 0
                END))::integer AS fumbles,
            (sum(
                CASE
                    WHEN defensive_plays.is_competitive THEN (defensive_plays.is_interception + defensive_plays.is_fumble)
                    ELSE 0
                END))::integer AS turnovers_forced,
            (sum(
                CASE
                    WHEN (defensive_plays.is_competitive AND defensive_plays.is_stuff) THEN 1
                    ELSE 0
                END))::integer AS stuffs,
            round(((sum(
                CASE
                    WHEN (defensive_plays.is_competitive AND defensive_plays.is_stuff) THEN 1
                    ELSE 0
                END))::numeric / (NULLIF(count(*) FILTER (WHERE (defensive_plays.is_competitive AND (((defensive_plays.play_type)::text ~~* '%rush%'::text) OR ((defensive_plays.play_type)::text ~~* '%run%'::text)))), 0))::numeric), 4) AS stuff_rate,
            (sum(
                CASE
                    WHEN (defensive_plays.is_competitive AND defensive_plays.is_tfl) THEN 1
                    ELSE 0
                END))::integer AS tfls
           FROM defensive_plays
          GROUP BY defensive_plays.team, defensive_plays.season
        ), game_havoc_season AS (
         SELECT gh_1.team,
            gh_1.season,
            (round((sum(COALESCE((gh_1.defense__total_havoc_events)::double precision, gh_1.defense__total_havoc_events__v_double)))::numeric))::integer AS havoc_plays,
            round(((sum(COALESCE((gh_1.defense__total_havoc_events)::double precision, gh_1.defense__total_havoc_events__v_double)) / (NULLIF(sum(gh_1.defense__total_plays), (0)::numeric))::double precision))::numeric, 4) AS havoc_rate,
            round(((sum(COALESCE((gh_1.defense__front_seven_havoc_events)::double precision, gh_1.defense__front_seven_havoc_events__v_double)) / (NULLIF(sum(gh_1.defense__total_plays), (0)::numeric))::double precision))::numeric, 4) AS front_seven_havoc_rate,
            round(((sum((gh_1.defense__db_havoc_events)::double precision) / (NULLIF(sum(gh_1.defense__total_plays), (0)::numeric))::double precision))::numeric, 4) AS db_havoc_rate
           FROM stats.game_havoc gh_1
          GROUP BY gh_1.team, gh_1.season
        )
 SELECT pa.team,
    pa.season,
    pa.defensive_plays,
    pa.opp_epa_per_play,
    pa.opp_success_rate,
    gh.havoc_plays,
    gh.havoc_rate,
    pa.sacks,
    pa.interceptions,
    pa.fumbles,
    pa.turnovers_forced,
    pa.stuffs,
    pa.stuff_rate,
    pa.tfls,
    gh.front_seven_havoc_rate,
    gh.db_havoc_rate
   FROM (plays_agg pa
     LEFT JOIN game_havoc_season gh ON ((((pa.team)::text = (gh.team)::text) AND (pa.season = gh.season))))
  WITH NO DATA;


--
-- Name: team_adjusted_epa; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_adjusted_epa AS
 SELECT a.team,
    a.season,
    a.off_coef AS off_adj_epa,
    a.def_coef AS def_adj_epa,
    (a.off_coef - a.def_coef) AS net_adj_epa,
    a.hfa_coef,
    a.plays,
    a.lambda,
    rank() OVER (PARTITION BY a.season ORDER BY a.off_coef DESC) AS off_rank,
    rank() OVER (PARTITION BY a.season ORDER BY a.def_coef) AS def_rank,
    rank() OVER (PARTITION BY a.season ORDER BY (a.off_coef - a.def_coef) DESC) AS net_rank,
    w.epa_total AS wepa_total,
    w.epa_allowed_total AS wepa_allowed_total
   FROM (analytics.adjusted_epa_build a
     LEFT JOIN marts.team_wepa_season w ON ((((w.team)::text = (a.team)::text) AND (w.season = a.season))))
  WITH NO DATA;


