--
-- Name: epa_crossvalidation; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.epa_crossvalidation AS
 WITH house AS (
         SELECT a.season,
            a.team,
            a.net_adj_epa,
            a.off_adj_epa,
            a.def_adj_epa,
            a.plays AS house_plays,
            e.epa_per_play AS house_epa_per_play,
            e.games_played AS house_games
           FROM (marts.team_adjusted_epa a
             LEFT JOIN marts.team_epa_season e ON ((((e.team)::text = (a.team)::text) AND (e.season = a.season))))
        ), house_counts AS (
         SELECT house.season,
            count(*) AS house_teams
           FROM house
          GROUP BY house.season
        ), team_names AS (
         SELECT t.id,
            t.school
           FROM ref.teams t
          WHERE (t.school IS NOT NULL)
        ), sdv_final AS (
         SELECT DISTINCT ON (r_1.season, n.school) r_1.season,
            n.school AS team,
            r_1.team_id AS external_team_id,
            r_1.through_week AS external_through_week,
            r_1.adj_net AS external_value,
            r_1.net_rank AS external_rank_source
           FROM (ratings.sdv_ratings_weekly r_1
             JOIN team_names n ON ((n.id = r_1.team_id)))
          WHERE (r_1.adj_net IS NOT NULL)
          ORDER BY r_1.season, n.school, r_1.through_week DESC, r_1.games DESC NULLS LAST, r_1.team_id
        ), espn_final AS (
         SELECT DISTINCT ON (f.season, n.school) f.season,
            n.school AS team,
            f.team_id AS external_team_id,
                CASE
                    WHEN (f.season_type >= 3) THEN (100 + f.week)
                    ELSE f.week
                END AS external_through_week,
            f.fpi AS external_value,
            (f.fpirank)::bigint AS external_rank_source
           FROM (ratings.espn_fpi_weekly f
             JOIN team_names n ON ((n.id = f.team_id)))
          WHERE (f.fpi IS NOT NULL)
          ORDER BY f.season, n.school, f.season_type DESC, f.week DESC, f.team_id
        ), cfbd_fpi_final AS (
         SELECT DISTINCT ON (r_1.year, r_1.team) r_1.year AS season,
            r_1.team,
            NULL::bigint AS external_team_id,
            NULL::bigint AS external_through_week,
            r_1.fpi AS external_value,
            r_1.resume_ranks__fpi AS external_rank_source
           FROM ratings.fpi_ratings r_1
          WHERE (r_1.fpi IS NOT NULL)
          ORDER BY r_1.year, r_1.team, r_1.fpi DESC
        ), external_all AS (
         SELECT 'sdv_adj_net'::text AS external_system,
            'adj_net'::text AS external_metric,
            s.season,
            s.team,
            s.external_team_id,
            s.external_through_week,
            s.external_value,
            s.external_rank_source
           FROM sdv_final s
        UNION ALL
         SELECT 'espn_fpi_weekly'::text AS text,
            'fpi'::text AS text,
            e.season,
            e.team,
            e.external_team_id,
            e.external_through_week,
            e.external_value,
            e.external_rank_source
           FROM espn_final e
        UNION ALL
         SELECT 'cfbd_fpi_season'::text AS text,
            'fpi'::text AS text,
            c.season,
            c.team,
            c.external_team_id,
            c.external_through_week,
            c.external_value,
            c.external_rank_source
           FROM cfbd_fpi_final c
        ), external_counts AS (
         SELECT external_all.external_system,
            external_all.season,
            count(*) AS external_teams
           FROM external_all
          GROUP BY external_all.external_system, external_all.season
        ), matched AS (
         SELECT h.season,
            x.external_system,
            h.team,
            x.external_metric,
            x.external_team_id,
            x.external_through_week,
            h.net_adj_epa AS house_net_adj_epa,
            h.off_adj_epa AS house_off_adj_epa,
            h.def_adj_epa AS house_def_adj_epa,
            h.house_epa_per_play,
            h.house_plays,
            h.house_games,
            x.external_value,
            x.external_rank_source,
            hc.house_teams,
            xc.external_teams
           FROM (((house h
             JOIN external_all x ON (((x.season = h.season) AND ((x.team)::text = (h.team)::text))))
             LEFT JOIN house_counts hc ON ((hc.season = h.season)))
             LEFT JOIN external_counts xc ON (((xc.season = h.season) AND (xc.external_system = x.external_system))))
        ), ranked AS (
         SELECT m.season,
            m.external_system,
            m.team,
            m.external_metric,
            m.external_team_id,
            m.external_through_week,
            m.house_net_adj_epa,
            m.house_off_adj_epa,
            m.house_def_adj_epa,
            m.house_epa_per_play,
            m.house_plays,
            m.house_games,
            m.external_value,
            m.external_rank_source,
            m.house_teams,
            m.external_teams,
                CASE
                    WHEN (m.house_net_adj_epa IS NOT NULL) THEN rank() OVER (PARTITION BY m.season, m.external_system ORDER BY m.house_net_adj_epa DESC NULLS LAST)
                    ELSE NULL::bigint
                END AS house_net_rank,
                CASE
                    WHEN (m.house_epa_per_play IS NOT NULL) THEN rank() OVER (PARTITION BY m.season, m.external_system ORDER BY m.house_epa_per_play DESC NULLS LAST)
                    ELSE NULL::bigint
                END AS house_epa_rank,
            rank() OVER (PARTITION BY m.season, m.external_system ORDER BY m.external_value DESC) AS external_rank,
            (((m.house_net_adj_epa)::double precision - avg((m.house_net_adj_epa)::double precision) OVER w) / NULLIF(stddev_samp((m.house_net_adj_epa)::double precision) OVER w, (0)::double precision)) AS house_net_z,
            ((m.external_value - avg(m.external_value) OVER w) / NULLIF(stddev_samp(m.external_value) OVER w, (0)::double precision)) AS external_z
           FROM matched m
          WINDOW w AS (PARTITION BY m.season, m.external_system)
        )
 SELECT season,
    external_system,
    team,
    external_metric,
    external_team_id,
    external_through_week,
    house_net_adj_epa,
    house_off_adj_epa,
    house_def_adj_epa,
    house_epa_per_play,
    house_plays,
    house_games,
    round((external_value)::numeric, 4) AS external_value,
    external_rank_source,
    house_net_rank,
    house_epa_rank,
    external_rank,
    round((house_net_z)::numeric, 4) AS house_net_z,
    round((external_z)::numeric, 4) AS external_z,
    (external_rank - house_net_rank) AS rank_delta,
    count(*) OVER w AS matched_teams,
    count(house_net_rank) OVER w AS corr_pairs,
    house_teams,
    external_teams,
    round(((100.0 * (count(*) OVER w)::numeric) / (NULLIF(external_teams, 0))::numeric), 1) AS coverage_pct,
    round((corr((house_net_rank)::double precision, (external_rank)::double precision) OVER w)::numeric, 4) AS spearman_net_adj_epa,
    round((corr((house_epa_rank)::double precision, (external_rank)::double precision) OVER w)::numeric, 4) AS spearman_epa_per_play,
    round((corr((house_net_adj_epa)::double precision, external_value) OVER w)::numeric, 4) AS pearson_net_adj_epa,
    round(avg(abs((external_rank - house_net_rank))) OVER w, 2) AS mean_abs_rank_delta,
    round((corr((external_rank)::double precision, (external_rank_source)::double precision) OVER w)::numeric, 4) AS source_rank_agreement
   FROM ranked r
  WINDOW w AS (PARTITION BY season, external_system)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW epa_crossvalidation; Type: COMMENT; Schema: marts; Owner: -
--

COMMENT ON MATERIALIZED VIEW marts.epa_crossvalidation IS 'Descriptive plausibility harness for the historical play-stats refresh campaign: house adjusted EPA vs independent external ratings, compared by rank (Spearman) and z-score within each (season, external_system) matched set. Internal ops surface -- NOT a downstream contract, NOT a model input (it mixes season-final information and would leak if used as-of), and NOT a shipping gate (that is the walk-forward no-regression gate on marts.prediction_accuracy). See src/schemas/marts/044_epa_crossvalidation.sql for the before/after operator protocol and its fixed decision rule.';


--
-- Name: team_style_profile; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_style_profile AS
 WITH play_aggregates AS (
         SELECT p.offense AS team,
            g.season,
            count(*) FILTER (WHERE ((p.play_type)::text = ANY (ARRAY[('Rush'::character varying)::text, ('Rushing Touchdown'::character varying)::text]))) AS rush_plays,
            count(*) FILTER (WHERE ((p.play_type)::text = ANY (ARRAY[('Pass Reception'::character varying)::text, ('Pass Incompletion'::character varying)::text, ('Passing Touchdown'::character varying)::text, ('Pass Interception'::character varying)::text, ('Sack'::character varying)::text]))) AS pass_plays,
            count(*) AS total_plays,
            avg(p.ppa) FILTER (WHERE ((p.play_type)::text = ANY (ARRAY[('Rush'::character varying)::text, ('Rushing Touchdown'::character varying)::text]))) AS epa_rushing,
            avg(p.ppa) FILTER (WHERE ((p.play_type)::text = ANY (ARRAY[('Pass Reception'::character varying)::text, ('Pass Incompletion'::character varying)::text, ('Passing Touchdown'::character varying)::text, ('Pass Interception'::character varying)::text, ('Sack'::character varying)::text]))) AS epa_passing,
            count(DISTINCT p.game_id) AS games
           FROM (core.plays p
             JOIN core.games g ON ((p.game_id = g.id)))
          WHERE (p.ppa IS NOT NULL)
          GROUP BY p.offense, g.season
        ), defensive_aggregates AS (
         SELECT p.defense AS team,
            g.season,
            avg(p.ppa) FILTER (WHERE ((p.play_type)::text = ANY (ARRAY[('Rush'::character varying)::text, ('Rushing Touchdown'::character varying)::text]))) AS def_epa_vs_run,
            avg(p.ppa) FILTER (WHERE ((p.play_type)::text = ANY (ARRAY[('Pass Reception'::character varying)::text, ('Pass Incompletion'::character varying)::text, ('Passing Touchdown'::character varying)::text, ('Pass Interception'::character varying)::text, ('Sack'::character varying)::text]))) AS def_epa_vs_pass
           FROM (core.plays p
             JOIN core.games g ON ((p.game_id = g.id)))
          WHERE (p.ppa IS NOT NULL)
          GROUP BY p.defense, g.season
        )
 SELECT o.team,
    o.season,
    round(((o.rush_plays)::numeric / (NULLIF(o.total_plays, 0))::numeric), 3) AS run_rate,
    round(((o.pass_plays)::numeric / (NULLIF(o.total_plays, 0))::numeric), 3) AS pass_rate,
    round((o.epa_rushing)::numeric, 4) AS epa_rushing,
    round((o.epa_passing)::numeric, 4) AS epa_passing,
    round(((o.total_plays)::numeric / (NULLIF(o.games, 0))::numeric), 1) AS plays_per_game,
        CASE
            WHEN (((o.total_plays)::numeric / (NULLIF(o.games, 0))::numeric) >= (75)::numeric) THEN 'up_tempo'::text
            WHEN (((o.total_plays)::numeric / (NULLIF(o.games, 0))::numeric) >= (65)::numeric) THEN 'balanced'::text
            ELSE 'slow'::text
        END AS tempo_category,
        CASE
            WHEN (((o.rush_plays)::numeric / (NULLIF(o.total_plays, 0))::numeric) >= 0.55) THEN 'run_heavy'::text
            WHEN (((o.pass_plays)::numeric / (NULLIF(o.total_plays, 0))::numeric) >= 0.55) THEN 'pass_heavy'::text
            ELSE 'balanced'::text
        END AS offensive_identity,
    round((d.def_epa_vs_run)::numeric, 4) AS def_epa_vs_run,
    round((d.def_epa_vs_pass)::numeric, 4) AS def_epa_vs_pass
   FROM (play_aggregates o
     LEFT JOIN defensive_aggregates d ON ((((o.team)::text = (d.team)::text) AND (o.season = d.season))))
  WITH NO DATA;


--
-- Name: matchup_edges; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.matchup_edges AS
 WITH game_matchups AS (
         SELECT DISTINCT g.season,
            g.id AS game_id,
            g.home_team AS team_a,
            g.away_team AS team_b,
            g.home_points AS team_a_points,
            g.away_points AS team_b_points
           FROM core.games g
          WHERE ((g.season >= 2014) AND (g.completed = true))
        )
 SELECT gm.season,
    gm.game_id,
    gm.team_a,
    gm.team_b,
    gm.team_a_points,
    gm.team_b_points,
    sa.run_rate AS a_run_rate,
    sa.offensive_identity AS a_offensive_identity,
    sa.epa_rushing AS a_epa_rushing,
    sa.epa_passing AS a_epa_passing,
    sa.tempo_category AS a_tempo,
    sb.run_rate AS b_run_rate,
    sb.offensive_identity AS b_offensive_identity,
    sb.epa_rushing AS b_epa_rushing,
    sb.epa_passing AS b_epa_passing,
    sb.tempo_category AS b_tempo,
    ((sa.epa_rushing - sb.def_epa_vs_run))::numeric(6,4) AS a_rush_edge,
    ((sa.epa_passing - sb.def_epa_vs_pass))::numeric(6,4) AS a_pass_edge,
    ((sb.epa_rushing - sa.def_epa_vs_run))::numeric(6,4) AS b_rush_edge,
    ((sb.epa_passing - sa.def_epa_vs_pass))::numeric(6,4) AS b_pass_edge,
    (abs((sa.plays_per_game - sb.plays_per_game)))::numeric(5,1) AS tempo_mismatch,
    ((((((sa.epa_rushing - sb.def_epa_vs_run) * sa.run_rate) + ((sa.epa_passing - sb.def_epa_vs_pass) * sa.pass_rate)) - ((sb.epa_rushing - sa.def_epa_vs_run) * sb.run_rate)) - ((sb.epa_passing - sa.def_epa_vs_pass) * sb.pass_rate)))::numeric(6,4) AS net_edge_a,
        CASE
            WHEN (gm.team_a_points > gm.team_b_points) THEN 'team_a'::text
            WHEN (gm.team_b_points > gm.team_a_points) THEN 'team_b'::text
            ELSE 'tie'::text
        END AS actual_winner,
    (gm.team_a_points - gm.team_b_points) AS actual_margin
   FROM ((game_matchups gm
     JOIN marts.team_style_profile sa ON (((gm.season = sa.season) AND ((gm.team_a)::text = (sa.team)::text))))
     JOIN marts.team_style_profile sb ON (((gm.season = sb.season) AND ((gm.team_b)::text = (sb.team)::text))))
  WITH NO DATA;


--
-- Name: matchup_history; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.matchup_history AS
 WITH game_matchups AS (
         SELECT LEAST(games.home_team, games.away_team) AS team1,
            GREATEST(games.home_team, games.away_team) AS team2,
            games.season,
            games.start_date,
            games.home_team,
            games.away_team,
            games.home_points,
            games.away_points,
            games.venue,
                CASE
                    WHEN (games.home_points > games.away_points) THEN games.home_team
                    WHEN (games.away_points > games.home_points) THEN games.away_team
                    ELSE NULL::character varying
                END AS winner,
            abs((games.home_points - games.away_points)) AS margin
           FROM core.games
          WHERE ((games.completed = true) AND (games.home_points IS NOT NULL) AND (games.away_points IS NOT NULL))
        )
 SELECT team1,
    team2,
    count(*) AS total_games,
    (sum(
        CASE
            WHEN ((winner)::text = (team1)::text) THEN 1
            ELSE 0
        END))::integer AS team1_wins,
    (sum(
        CASE
            WHEN ((winner)::text = (team2)::text) THEN 1
            ELSE 0
        END))::integer AS team2_wins,
    (sum(
        CASE
            WHEN (winner IS NULL) THEN 1
            ELSE 0
        END))::integer AS ties,
    min(season) AS first_meeting_year,
    max(season) AS last_meeting_year,
    min(start_date) AS first_meeting_date,
    max(start_date) AS last_meeting_date,
    round(avg(margin), 1) AS avg_margin,
    (max(margin))::integer AS largest_margin,
    round(avg(
        CASE
            WHEN ((home_team)::text = (team1)::text) THEN (home_points - away_points)
            ELSE (away_points - home_points)
        END), 1) AS team1_avg_margin,
    (sum(
        CASE
            WHEN ((home_team)::text = (team1)::text) THEN home_points
            ELSE away_points
        END))::integer AS team1_total_points,
    (sum(
        CASE
            WHEN ((home_team)::text = (team2)::text) THEN home_points
            ELSE away_points
        END))::integer AS team2_total_points,
    (sum(
        CASE
            WHEN (((winner)::text = (team1)::text) AND (season >= 2015)) THEN 1
            ELSE 0
        END))::integer AS team1_wins_last_10yr,
    (sum(
        CASE
            WHEN (((winner)::text = (team2)::text) AND (season >= 2015)) THEN 1
            ELSE 0
        END))::integer AS team2_wins_last_10yr,
    (count(*) FILTER (WHERE (season >= 2015)))::integer AS games_last_10yr,
    ( SELECT gm2.winner
           FROM game_matchups gm2
          WHERE (((gm2.team1)::text = (game_matchups.team1)::text) AND ((gm2.team2)::text = (game_matchups.team2)::text))
          ORDER BY gm2.start_date DESC
         LIMIT 1) AS last_winner
   FROM game_matchups
  GROUP BY team1, team2
  WITH NO DATA;


--
-- Name: play_stats; Type: TABLE; Schema: stats; Owner: -
--

CREATE TABLE stats.play_stats (
    game_id bigint NOT NULL,
    season bigint,
    week bigint,
    team character varying,
    conference character varying,
    opponent character varying,
    team_score bigint,
    opponent_score bigint,
    drive_id character varying,
    play_id character varying NOT NULL,
    period bigint,
    clock__minutes bigint,
    clock__seconds bigint,
