);


--
-- Name: player_game_epa; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.player_game_epa AS
 SELECT player_game_epa_build.game_id,
    player_game_epa_build.season,
    player_game_epa_build.team,
    player_game_epa_build.player_name,
    player_game_epa_build.athlete_id,
    player_game_epa_build.play_category,
    player_game_epa_build.plays,
    player_game_epa_build.total_epa,
    player_game_epa_build.epa_per_play,
    player_game_epa_build.success_rate,
    player_game_epa_build.explosive_plays,
    player_game_epa_build.total_yards
   FROM analytics.player_game_epa_build
  WHERE (player_game_epa_build.season <= 2025)
UNION ALL
 SELECT live_current_season.game_id,
    live_current_season.season,
    live_current_season.team,
    live_current_season.player_name,
    live_current_season.athlete_id,
    live_current_season.play_category,
    live_current_season.plays,
    live_current_season.total_epa,
    live_current_season.epa_per_play,
    live_current_season.success_rate,
    live_current_season.explosive_plays,
    live_current_season.total_yards
   FROM ( WITH stat_type_roles(stat_type, play_category) AS (
                 VALUES ('Completion'::text,'passing'::text), ('Incompletion'::text,'passing'::text), ('Interception Thrown'::text,'passing'::text), ('Sack Taken'::text,'passing'::text), ('Rush'::text,'rushing'::text), ('Reception'::text,'receiving'::text), ('Target'::text,'receiving'::text)
                ), role_athletes AS (
                 SELECT DISTINCT ps.game_id,
                    ps.play_id,
                    ps.athlete_id,
                    ps.team,
                    r.play_category
                   FROM (stats.play_stats ps
                     JOIN stat_type_roles r ON ((r.stat_type = (ps.stat_type)::text)))
                  WHERE (ps.season >= 2026)
                ), role_plays AS (
                 SELECT pe.game_id,
                    pe.season,
                    pe.offense AS team,
                    ra.athlete_id,
                    ra.play_category,
                    ra.play_id,
                    pe.epa,
                    pe.success,
                    pe.explosive,
                    pe.yards_gained
                   FROM (role_athletes ra
                     JOIN marts.play_epa pe ON (((pe.game_id = ra.game_id) AND ((pe.play_id)::text = (ra.play_id)::text))))
                  WHERE (((ra.team)::text = (pe.offense)::text) AND (NOT pe.is_garbage_time) AND (pe.season >= 2026))
                ), athlete_names AS (
                 SELECT play_stats.game_id,
                    play_stats.athlete_id,
                    max((play_stats.athlete_name)::text) AS player_name
                   FROM stats.play_stats
                  WHERE (play_stats.season >= 2026)
                  GROUP BY play_stats.game_id, play_stats.athlete_id
                )
         SELECT rp.game_id,
            rp.season,
            rp.team,
            max(an.player_name) AS player_name,
            rp.athlete_id,
            rp.play_category,
            count(*) AS plays,
            (sum(rp.epa))::numeric(8,2) AS total_epa,
            (avg(rp.epa))::numeric(6,4) AS epa_per_play,
            (avg(rp.success))::numeric(5,3) AS success_rate,
            sum(rp.explosive) AS explosive_plays,
            sum(rp.yards_gained) AS total_yards
           FROM (role_plays rp
             LEFT JOIN athlete_names an ON (((an.game_id = rp.game_id) AND ((an.athlete_id)::text = (rp.athlete_id)::text))))
          GROUP BY rp.game_id, rp.season, rp.team, rp.athlete_id, rp.play_category
         HAVING (count(*) >= 3)) live_current_season
  WITH NO DATA;


