--
-- Name: TABLE fct_player_seasons; Type: COMMENT; Schema: rp; Owner: -
--

COMMENT ON TABLE rp.fct_player_seasons IS 'Player-season grain. One row per (player_id, season). Populated by rp.refresh_fct_player_seasons() in U2.';


--
-- Name: COLUMN fct_player_seasons.player_id; Type: COMMENT; Schema: rp; Owner: -
