COMMENT ON COLUMN rp.fct_player_seasons.player_id IS 'core.roster.id (VARCHAR, not BIGINT). All cross-schema joins must respect varchar typing.';


--
-- Name: COLUMN fct_player_seasons.position_group; Type: COMMENT; Schema: rp; Owner: -
