    severity character varying,
    target_season_status character varying,
    source_url character varying,
    source_date date,
    loaded_at timestamp with time zone DEFAULT now()
);


--
-- Name: TABLE injuries_season_ending; Type: COMMENT; Schema: rp; Owner: -
--

COMMENT ON TABLE rp.injuries_season_ending IS 'Hand-curated season-ender list. Drives health_factor in marts.player_returning_value. Loaded from seeds/injuries_season_ending.csv in U8.';


--
-- Name: player_returning_value; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.player_returning_value AS
 WITH base_data AS (
         SELECT fpm.player_id,
            fpm.transition_season AS target_season,
            (fpm.transition_season - 1) AS source_season,
            fpm.destination_team AS target_team,
            fpm.movement_type,
            fpm.match_confidence,
            fpm.match_method,
            COALESCE(fps_source."position", fps_target."position") AS "position",
            COALESCE(fps_source.position_group, fps_target.position_group) AS position_group,
            fps_source.team AS source_team_for_schedule,
            1.00 AS base_production,
            ((fpm.match_method)::text = 'roster_continuity'::text) AS is_returning,
            (((fpm.match_method)::text ~~ 'portal_%'::text) OR ((fpm.match_method)::text = 'unmatched'::text)) AS is_portal_in,
            ((fpm.match_method)::text = 'recruit'::text) AS is_recruit
           FROM ((rp.fct_player_movements fpm
             LEFT JOIN rp.fct_player_seasons fps_source ON ((((fps_source.player_id)::text = (fpm.player_id)::text) AND (fps_source.season = (fpm.transition_season - 1)))))
             LEFT JOIN rp.fct_player_seasons fps_target ON ((((fps_target.player_id)::text = (fpm.player_id)::text) AND (fps_target.season = fpm.transition_season))))
          WHERE (fpm.destination_team IS NOT NULL)
        ), schedule AS (
         SELECT games.season,
            games.home_team AS team,
            games.away_team AS opponent
           FROM core.games
          WHERE (games.completed = true)
        UNION ALL
         SELECT games.season,
            games.away_team AS team,
            games.home_team AS opponent
           FROM core.games
          WHERE (games.completed = true)
        ), team_competition AS (
         SELECT s.team,
            s.season,
            avg(sp.ranking) AS avg_opp_rank
           FROM (schedule s
             JOIN ratings.sp_ratings sp ON ((((sp.team)::text = (s.opponent)::text) AND (sp.year = s.season))))
          GROUP BY s.team, s.season
        ), combined AS (
         SELECT bd.player_id,
            bd.target_team,
            bd.target_season,
            bd.source_season,
            bd."position",
            bd.position_group,
            bd.movement_type,
            bd.match_confidence,
            bd.is_returning,
            bd.is_portal_in,
            bd.is_recruit,
            bd.base_production,
            COALESCE(dpw.position_weight, 0.000) AS position_weight,
            dcf.continuity_factor,
            (GREATEST(0.70, LEAST(1.30, COALESCE((1.0 + (((67.0 - tc.avg_opp_rank) / 67.0) * 0.3)), 1.00))))::numeric(4,2) AS competition_factor,
            (COALESCE(
                CASE inj.severity
                    WHEN 'season'::text THEN 0.40
                    WHEN 'partial'::text THEN 0.70
                    ELSE 1.00
                END, 1.00))::numeric(4,2) AS health_factor
           FROM ((((base_data bd
             LEFT JOIN rp.dim_position_weights dpw ON ((((dpw."position")::text = (bd."position")::text) AND ((dpw.scheme_archetype)::text = 'static'::text))))
             LEFT JOIN rp.dim_continuity_factors dcf ON (((dcf.movement_type)::text = (bd.movement_type)::text)))
             LEFT JOIN team_competition tc ON ((((tc.team)::text = (bd.source_team_for_schedule)::text) AND (tc.season = bd.source_season))))
             LEFT JOIN rp.injuries_season_ending inj ON ((((inj.player_id)::text = (bd.player_id)::text) AND (inj.injury_season = bd.source_season))))
        )
 SELECT player_id,
    target_team,
    target_season,
    source_season,
    "position",
    position_group,
    movement_type,
    (base_production)::numeric(6,3) AS base_production,
    (position_weight)::numeric(5,3) AS position_weight,
    continuity_factor,
    competition_factor,
    health_factor,
    (((((base_production * position_weight) * continuity_factor) * competition_factor) * health_factor))::numeric(6,3) AS returning_value,
    is_returning,
    is_portal_in,
    is_recruit,
    match_confidence,
    now() AS generated_at
   FROM combined
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW player_returning_value; Type: COMMENT; Schema: marts; Owner: -
--

COMMENT ON MATERIALIZED VIEW marts.player_returning_value IS 'Player-grain returning value, one row per (player_id, target_team, target_season). Five-factor decomposition: base * position * continuity * competition * health. v1 base_production is a placeholder (1.0 for prior-roster movements, 0.0 for recruits); U10 replaces it with z-score quality formulas. Refresh via REFRESH MATERIALIZED VIEW CONCURRENTLY; depends on rp.fct_player_seasons + rp.fct_player_movements being current.';


--
-- Name: player_season_epa; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.player_season_epa AS
 SELECT season,
    team,
    max((player_name)::text) AS player_name,
    athlete_id,
    play_category,
    count(DISTINCT game_id) AS games,
    sum(plays) AS total_plays,
    (sum(total_epa))::numeric(8,2) AS total_epa,
    ((sum(total_epa) / NULLIF(sum(plays), (0)::numeric)))::numeric(6,4) AS epa_per_play,
    ((sum(((plays)::numeric * success_rate)) / NULLIF(sum(plays), (0)::numeric)))::numeric(5,3) AS success_rate,
    sum(explosive_plays) AS explosive_plays,
    sum(total_yards) AS total_yards,
    ((sum(plays) / (count(DISTINCT game_id))::numeric))::numeric(5,1) AS plays_per_game,
    rank() OVER (PARTITION BY season, play_category ORDER BY (sum(total_epa)) DESC) AS epa_rank
   FROM marts.player_game_epa
  GROUP BY season, team, athlete_id, play_category
 HAVING (sum(plays) >= (20)::numeric)
  WITH NO DATA;


--
-- Name: scoring_opportunities; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.scoring_opportunities AS
 SELECT offense AS team,
    season,
    count(*) AS total_drives,
    count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('FG'::character varying)::text, ('Touchdown'::character varying)::text, ('Field Goal'::character varying)::text]))) AS scoring_drives,
    round(((count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('FG'::character varying)::text, ('Touchdown'::character varying)::text, ('Field Goal'::character varying)::text]))))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS scoring_rate,
    count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('Touchdown'::character varying)::text]))) AS td_drives,
    round(((count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('Touchdown'::character varying)::text]))))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS td_rate,
    round(((((count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('Touchdown'::character varying)::text]))))::numeric * 7.0) + ((count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('FG'::character varying)::text, ('Field Goal'::character varying)::text]))))::numeric * 3.0)) / (NULLIF(count(*), 0))::numeric), 3) AS points_per_drive,
    count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('INT'::character varying)::text, ('FUMBLE'::character varying)::text, ('Interception'::character varying)::text, ('Fumble'::character varying)::text, ('Fumble Lost'::character varying)::text, ('Interception Return'::character varying)::text]))) AS turnover_drives,
    round(((count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('INT'::character varying)::text, ('FUMBLE'::character varying)::text, ('Interception'::character varying)::text, ('Fumble'::character varying)::text, ('Fumble Lost'::character varying)::text, ('Interception Return'::character varying)::text]))))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS turnover_rate,
    count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('PUNT'::character varying)::text, ('Punt'::character varying)::text]))) AS punt_drives,
    round(((count(*) FILTER (WHERE ((drive_result)::text = ANY (ARRAY[('PUNT'::character varying)::text, ('Punt'::character varying)::text]))))::numeric / (NULLIF(count(*), 0))::numeric), 4) AS punt_rate,
    round(avg(plays), 1) AS avg_plays_per_drive,
    round(avg(yards), 1) AS avg_yards_per_drive,
    round(avg(elapsed__minutes), 2) AS avg_time_per_drive,
    count(*) FILTER (WHERE (start_yards_to_goal <= 20)) AS red_zone_drives,
    count(*) FILTER (WHERE ((start_yards_to_goal <= 20) AND ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('FG'::character varying)::text, ('Touchdown'::character varying)::text, ('Field Goal'::character varying)::text])))) AS red_zone_scores,
    round(((count(*) FILTER (WHERE ((start_yards_to_goal <= 20) AND ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('FG'::character varying)::text, ('Touchdown'::character varying)::text, ('Field Goal'::character varying)::text])))))::numeric / (NULLIF(count(*) FILTER (WHERE (start_yards_to_goal <= 20)), 0))::numeric), 4) AS red_zone_scoring_rate,
    round(((count(*) FILTER (WHERE ((start_yards_to_goal <= 20) AND ((drive_result)::text = ANY (ARRAY[('TD'::character varying)::text, ('Touchdown'::character varying)::text])))))::numeric / (NULLIF(count(*) FILTER (WHERE (start_yards_to_goal <= 20)), 0))::numeric), 4) AS red_zone_td_rate
   FROM core.drives d
  WHERE (offense IS NOT NULL)
  GROUP BY offense, season
  WITH NO DATA;


--
-- Name: situational_splits; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.situational_splits AS
 WITH play_situations AS (
         SELECT p.offense AS team,
            g.season,
            p.ppa,
            p.play_type,
            p.down,
            p.distance,
            p.yards_to_goal,
            p.period,
            p.clock__minutes,
            p.clock__seconds,
            p.score_diff,
            (NOT (((p.period = 4) AND (abs(COALESCE(p.score_diff, 0)) > 28)) OR ((p.period >= 3) AND (abs(COALESCE(p.score_diff, 0)) > 35)))) AS is_competitive,
                CASE
                    WHEN (p.down = 1) THEN 'first'::text
                    WHEN ((p.down = 2) AND (p.distance <= 4)) THEN 'second_short'::text
                    WHEN ((p.down = 2) AND (p.distance > 4)) THEN 'second_long'::text
                    WHEN ((p.down = 3) AND (p.distance <= 3)) THEN 'third_short'::text
                    WHEN ((p.down = 3) AND ((p.distance >= 4) AND (p.distance <= 7))) THEN 'third_medium'::text
                    WHEN ((p.down = 3) AND (p.distance > 7)) THEN 'third_long'::text
                    WHEN (p.down = 4) THEN 'fourth'::text
                    ELSE 'other'::text
                END AS down_situation,
                CASE
                    WHEN (((p.down = 2) AND (p.distance >= 8)) OR ((p.down = 3) AND (p.distance >= 5))) THEN true
                    ELSE false
                END AS is_passing_down,
                CASE
                    WHEN (p.yards_to_goal <= 20) THEN 'red_zone'::text
                    WHEN (p.yards_to_goal <= 40) THEN 'scoring_position'::text
                    WHEN (p.yards_to_goal >= 80) THEN 'backed_up'::text
                    ELSE 'between_20s'::text
                END AS field_zone,
                CASE
                    WHEN ((p.period = 4) AND (abs(COALESCE(p.score_diff, 0)) <= 8)) THEN true
                    ELSE false
                END AS is_late_and_close,
                CASE
                    WHEN (((p.period = 2) OR (p.period = 4)) AND (COALESCE(p.clock__minutes, (0)::bigint) < 2)) THEN true
                    ELSE false
                END AS is_two_minute,
                CASE
                    WHEN (((p.play_type)::text ~~* '%rush%'::text) OR ((p.play_type)::text ~~* '%run%'::text)) THEN 'rush'::text
                    WHEN (((p.play_type)::text ~~* '%pass%'::text) OR ((p.play_type)::text ~~* '%sack%'::text)) THEN 'pass'::text
                    ELSE 'other'::text
                END AS play_category
           FROM (core.plays p
             JOIN core.games g ON ((p.game_id = g.id)))
          WHERE (p.ppa IS NOT NULL)
        )
 SELECT team,
    season,
    count(*) FILTER (WHERE is_competitive) AS total_plays,
    round((avg(ppa) FILTER (WHERE is_competitive))::numeric, 4) AS epa_per_play,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE is_competitive), 4) AS success_rate,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (down = 1))))::numeric, 4) AS first_down_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (down = 1))), 4) AS first_down_success,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (down = 2))))::numeric, 4) AS second_down_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (down = 2))), 4) AS second_down_success,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (down = 3))))::numeric, 4) AS third_down_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (down = 3))), 4) AS third_down_success,
    count(*) FILTER (WHERE (is_competitive AND (down = 3))) AS third_down_attempts,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (down_situation = 'third_short'::text))), 4) AS third_short_success,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (down_situation = 'third_medium'::text))), 4) AS third_medium_success,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (down_situation = 'third_long'::text))), 4) AS third_long_success,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (NOT is_passing_down))))::numeric, 4) AS standard_down_epa,
    round((avg(ppa) FILTER (WHERE (is_competitive AND is_passing_down)))::numeric, 4) AS passing_down_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (NOT is_passing_down))), 4) AS standard_down_success,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND is_passing_down)), 4) AS passing_down_success,
    count(*) FILTER (WHERE (is_competitive AND (field_zone = 'red_zone'::text))) AS red_zone_plays,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (field_zone = 'red_zone'::text))))::numeric, 4) AS red_zone_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (field_zone = 'red_zone'::text))), 4) AS red_zone_success,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (field_zone = 'backed_up'::text))))::numeric, 4) AS backed_up_epa,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (field_zone = 'scoring_position'::text))))::numeric, 4) AS scoring_position_epa,
    count(*) FILTER (WHERE (is_competitive AND is_late_and_close)) AS late_close_plays,
    round((avg(ppa) FILTER (WHERE (is_competitive AND is_late_and_close)))::numeric, 4) AS late_close_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND is_late_and_close)), 4) AS late_close_success,
    count(*) FILTER (WHERE (is_competitive AND is_two_minute)) AS two_minute_plays,
    round((avg(ppa) FILTER (WHERE (is_competitive AND is_two_minute)))::numeric, 4) AS two_minute_epa,
    count(*) FILTER (WHERE (is_competitive AND (play_category = 'rush'::text))) AS rush_plays,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (play_category = 'rush'::text))))::numeric, 4) AS rush_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (play_category = 'rush'::text))), 4) AS rush_success,
    count(*) FILTER (WHERE (is_competitive AND (play_category = 'pass'::text))) AS pass_plays,
    round((avg(ppa) FILTER (WHERE (is_competitive AND (play_category = 'pass'::text))))::numeric, 4) AS pass_epa,
    round(avg(
        CASE
            WHEN (ppa > (0)::double precision) THEN 1.0
            ELSE 0.0
        END) FILTER (WHERE (is_competitive AND (play_category = 'pass'::text))), 4) AS pass_success,
    round(((count(*) FILTER (WHERE (is_competitive AND (play_category = 'rush'::text))))::numeric / (NULLIF(count(*) FILTER (WHERE (is_competitive AND (play_category = ANY (ARRAY['rush'::text, 'pass'::text])))), 0))::numeric), 4) AS rush_rate
   FROM play_situations
  GROUP BY team, season
  WITH NO DATA;


--
-- Name: team_returning_production; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_returning_production AS
 WITH prv_proj AS (
         SELECT player_returning_value.target_team,
            player_returning_value.target_season,
            player_returning_value.position_group,
            player_returning_value.returning_value,
            player_returning_value.is_returning,
            player_returning_value.is_portal_in,
            player_returning_value.is_recruit
           FROM marts.player_returning_value
        ), team_player_rollup AS (
         SELECT prv_proj.target_team AS team,
            prv_proj.target_season AS season,
            (sum(prv_proj.returning_value))::numeric(8,3) AS returning_production_total,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = ANY (ARRAY[('QB'::character varying)::text, ('RB'::character varying)::text, ('WR_TE'::character varying)::text, ('OL'::character varying)::text]))))::numeric(8,3) AS returning_production_offense,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = ANY (ARRAY[('DL'::character varying)::text, ('LB'::character varying)::text, ('DB'::character varying)::text]))))::numeric(8,3) AS returning_production_defense,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'QB'::text)))::numeric(7,3) AS rp_qb,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'RB'::text)))::numeric(7,3) AS rp_rb,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'WR_TE'::text)))::numeric(7,3) AS rp_wr_te,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'OL'::text)))::numeric(7,3) AS rp_ol,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'DL'::text)))::numeric(7,3) AS rp_dl,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'LB'::text)))::numeric(7,3) AS rp_lb,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'DB'::text)))::numeric(7,3) AS rp_db,
            (sum(prv_proj.returning_value) FILTER (WHERE ((prv_proj.position_group)::text = 'ST'::text)))::numeric(7,3) AS rp_st,
            (count(*) FILTER (WHERE (prv_proj.is_returning = true)))::integer AS n_returners,
            (count(*) FILTER (WHERE (prv_proj.is_portal_in = true)))::integer AS n_portal_in,
            (count(*) FILTER (WHERE ((prv_proj.is_recruit = true) AND (prv_proj.returning_value > 0.10))))::integer AS n_recruits_contributing,
            (count(*) FILTER (WHERE (prv_proj.position_group IS NULL)))::integer AS n_unknown_position
           FROM prv_proj
          GROUP BY prv_proj.target_team, prv_proj.target_season
        ), portal_out AS (
         SELECT fct_player_movements.source_team AS team,
            fct_player_movements.transition_season AS season,
            (count(*))::integer AS n_portal_out
           FROM rp.fct_player_movements
          WHERE ((fct_player_movements.source_team IS NOT NULL) AND ((fct_player_movements.match_method)::text ~~ 'portal_%'::text) AND ((fct_player_movements.destination_team IS NULL) OR ((fct_player_movements.destination_team)::text <> (fct_player_movements.source_team)::text)))
          GROUP BY fct_player_movements.source_team, fct_player_movements.transition_season
        ), portal_trench_in AS (
         SELECT player_returning_value.target_team AS team,
            player_returning_value.target_season AS season,
            (sum(player_returning_value.returning_value))::numeric(7,3) AS portal_trench_in_value
           FROM marts.player_returning_value
          WHERE (((player_returning_value.position_group)::text = ANY (ARRAY[('OL'::character varying)::text, ('DL'::character varying)::text])) AND player_returning_value.is_portal_in)
          GROUP BY player_returning_value.target_team, player_returning_value.target_season
        ), portal_trench_out AS (
         SELECT fpm.source_team AS team,
            prv.target_season AS season,
            (sum(prv.returning_value))::numeric(7,3) AS portal_trench_out_value
           FROM (marts.player_returning_value prv
             JOIN rp.fct_player_movements fpm ON ((((fpm.player_id)::text = (prv.player_id)::text) AND (fpm.transition_season = prv.target_season))))
          WHERE (((prv.position_group)::text = ANY (ARRAY[('OL'::character varying)::text, ('DL'::character varying)::text])) AND ((fpm.match_method)::text ~~ 'portal_%'::text) AND (fpm.source_team IS NOT NULL) AND ((fpm.source_team)::text <> (prv.target_team)::text))
          GROUP BY fpm.source_team, prv.target_season
        ), cfbd_calibration AS (
         SELECT player_returning.team,
            (player_returning.season)::integer AS season,
            player_returning.percent_ppa AS cfbd_returning_production_pct
           FROM stats.player_returning
        ), season_max AS (
         SELECT team_player_rollup.season,
            max(team_player_rollup.returning_production_total) AS season_max_total
           FROM team_player_rollup
          GROUP BY team_player_rollup.season
        )
 SELECT tpr.team,
    tpr.season,
    tpr.returning_production_total,
    (COALESCE(tpr.returning_production_offense, (0)::numeric))::numeric(8,3) AS returning_production_offense,
    (COALESCE(tpr.returning_production_defense, (0)::numeric))::numeric(8,3) AS returning_production_defense,
    (COALESCE(tpr.rp_qb, (0)::numeric))::numeric(7,3) AS rp_qb,
    (COALESCE(tpr.rp_rb, (0)::numeric))::numeric(7,3) AS rp_rb,
    (COALESCE(tpr.rp_wr_te, (0)::numeric))::numeric(7,3) AS rp_wr_te,
    (COALESCE(tpr.rp_ol, (0)::numeric))::numeric(7,3) AS rp_ol,
    (COALESCE(tpr.rp_dl, (0)::numeric))::numeric(7,3) AS rp_dl,
    (COALESCE(tpr.rp_lb, (0)::numeric))::numeric(7,3) AS rp_lb,
    (COALESCE(tpr.rp_db, (0)::numeric))::numeric(7,3) AS rp_db,
    (COALESCE(tpr.rp_st, (0)::numeric))::numeric(7,3) AS rp_st,
    COALESCE(tpr.n_returners, 0) AS n_returners,
    COALESCE(tpr.n_portal_in, 0) AS n_portal_in,
    COALESCE(po.n_portal_out, 0) AS n_portal_out,
    COALESCE(tpr.n_recruits_contributing, 0) AS n_recruits_contributing,
    COALESCE(tpr.n_unknown_position, 0) AS n_unknown_position,
    (COALESCE(pti.portal_trench_in_value, (0)::numeric))::numeric(7,3) AS portal_trench_in_value,
    (COALESCE(pto.portal_trench_out_value, (0)::numeric))::numeric(7,3) AS portal_trench_out_value,
    ((COALESCE(pti.portal_trench_in_value, (0)::numeric) - COALESCE(pto.portal_trench_out_value, (0)::numeric)))::numeric(7,3) AS net_portal_trench_value,
    cal.cfbd_returning_production_pct,
        CASE
            WHEN ((sm.season_max_total IS NULL) OR (sm.season_max_total = (0)::numeric)) THEN NULL::numeric
            ELSE ((tpr.returning_production_total / sm.season_max_total))::numeric(5,4)
        END AS our_pct_normalized,
        CASE
            WHEN ((cal.cfbd_returning_production_pct IS NULL) OR (sm.season_max_total IS NULL) OR (sm.season_max_total = (0)::numeric)) THEN NULL::numeric
            ELSE ((((tpr.returning_production_total / sm.season_max_total))::double precision - cal.cfbd_returning_production_pct))::numeric(5,4)
        END AS delta_vs_cfbd,
    now() AS generated_at
   FROM (((((team_player_rollup tpr
     LEFT JOIN portal_out po ON ((((po.team)::text = (tpr.team)::text) AND (po.season = tpr.season))))
     LEFT JOIN portal_trench_in pti ON ((((pti.team)::text = (tpr.team)::text) AND (pti.season = tpr.season))))
     LEFT JOIN portal_trench_out pto ON ((((pto.team)::text = (tpr.team)::text) AND (pto.season = tpr.season))))
     LEFT JOIN cfbd_calibration cal ON ((((cal.team)::text = (tpr.team)::text) AND (cal.season = tpr.season))))
     LEFT JOIN season_max sm ON ((sm.season = tpr.season)))
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW team_returning_production; Type: COMMENT; Schema: marts; Owner: -
--

COMMENT ON MATERIALIZED VIEW marts.team_returning_production IS 'Team-grain returning production rollup, one row per (team, season). SUM over marts.player_returning_value with offense/defense partition, per-position-group breakdown (rp_qb..rp_st), and portal/recruit counts. Includes calibration columns (cfbd_returning_production_pct from stats.player_returning, our_pct_normalized = total / season_max, delta_vs_cfbd). 2026 has NULL CFBD calibration until CFBD publishes. Refresh via REFRESH MATERIALIZED VIEW CONCURRENTLY; depends on marts.player_returning_value being current.';


--
-- Name: team_season_trajectory; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_season_trajectory AS
 WITH team_season_class AS (
         SELECT x.team,
            x.season,
            max((x.classification)::text) AS classification
           FROM ( SELECT g.home_team AS team,
                    g.season,
                    g.home_classification AS classification
                   FROM core.games g
                  WHERE (g.home_classification IS NOT NULL)
                UNION ALL
                 SELECT g.away_team,
                    g.season,
                    g.away_classification
                   FROM core.games g
                  WHERE (g.away_classification IS NOT NULL)) x
          GROUP BY x.team, x.season
        ), teams_deduped AS (
         SELECT DISTINCT ON (teams.school) teams.school,
            teams.classification
           FROM ref.teams
          ORDER BY teams.school, teams.classification
        ), team_metrics AS (
         SELECT t.team,
            t.season,
            t.epa_per_play,
            t.success_rate,
            t.epa_tier,
            t.total_plays,
            t.games_played,
            s.wins AS total_wins,
            s.losses AS total_losses,
            s.conf_wins,
            s.conf_losses,
            r.rank AS recruiting_rank,
            r.points AS recruiting_points,
            (rank() OVER (PARTITION BY t.season, COALESCE(tsc.classification, (td.classification)::text) ORDER BY t.epa_per_play DESC))::integer AS off_epa_rank,
            (rank() OVER (PARTITION BY t.season, COALESCE(tsc.classification, (td.classification)::text) ORDER BY COALESCE(d.opp_epa_per_play, (999)::numeric)))::integer AS def_epa_rank
           FROM (((((marts.team_epa_season t
             LEFT JOIN marts.team_season_summary s ON ((((t.team)::text = (s.team)::text) AND (t.season = s.season))))
             LEFT JOIN marts.defensive_havoc d ON ((((t.team)::text = (d.team)::text) AND (t.season = d.season))))
             LEFT JOIN team_season_class tsc ON ((((tsc.team)::text = (t.team)::text) AND (tsc.season = t.season))))
             LEFT JOIN teams_deduped td ON (((td.school)::text = (t.team)::text)))
             LEFT JOIN recruiting.team_recruiting r ON ((((t.team)::text = (r.team)::text) AND (t.season = r.year))))
        )
 SELECT team,
    season,
    epa_per_play,
    success_rate,
    epa_tier,
    total_plays,
    games_played,
    games_played AS games,
    total_wins,
    total_wins AS wins,
    total_losses,
        CASE
            WHEN ((COALESCE(total_wins, 0) + COALESCE(total_losses, 0)) > 0) THEN round(((total_wins)::numeric / ((total_wins + total_losses))::numeric), 3)
            ELSE NULL::numeric
        END AS win_pct,
    conf_wins,
    conf_losses,
    recruiting_rank,
    recruiting_points,
    off_epa_rank,
    def_epa_rank,
    ( SELECT e.era_code
           FROM ref.get_era((m.season)::integer) e(era_code, era_name)
          ORDER BY e.era_code
         LIMIT 1) AS era_code,
    ( SELECT e.era_name
           FROM ref.get_era((m.season)::integer) e(era_code, era_name)
          ORDER BY e.era_code
         LIMIT 1) AS era_name,
    lag(epa_per_play) OVER (PARTITION BY team ORDER BY season) AS prev_epa,
    (epa_per_play - lag(epa_per_play) OVER (PARTITION BY team ORDER BY season)) AS epa_delta,
    lag(((total_wins)::numeric / (NULLIF((total_wins + total_losses), 0))::numeric)) OVER (PARTITION BY team ORDER BY season) AS prev_win_pct,
        CASE
            WHEN ((COALESCE(total_wins, 0) + COALESCE(total_losses, 0)) > 0) THEN (round(((total_wins)::numeric / ((total_wins + total_losses))::numeric), 3) - lag(((total_wins)::numeric / (NULLIF((total_wins + total_losses), 0))::numeric)) OVER (PARTITION BY team ORDER BY season))
            ELSE NULL::numeric
        END AS win_pct_delta,
    lag(recruiting_rank) OVER (PARTITION BY team ORDER BY season) AS prev_recruiting_rank,
    (lag(recruiting_rank) OVER (PARTITION BY team ORDER BY season) - recruiting_rank) AS recruiting_rank_improvement
   FROM team_metrics m
  WITH NO DATA;


--
-- Name: team_talent_composite; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_talent_composite AS
 WITH roster_talent AS (
         SELECT r.team,
            r.year AS season,
            count(*) AS roster_size,
            count(*) FILTER (WHERE (rec.stars = 5)) AS five_stars,
            count(*) FILTER (WHERE (rec.stars = 4)) AS four_stars,
            count(*) FILTER (WHERE (rec.stars = 3)) AS three_stars,
            count(*) FILTER (WHERE ((rec.stars <= 2) OR (rec.stars IS NULL))) AS low_stars,
            round((avg(rec.rating))::numeric, 4) AS avg_recruit_rating,
            round(((count(*) FILTER (WHERE (rec.stars >= 4)))::numeric / (NULLIF(count(*), 0))::numeric), 3) AS blue_chip_ratio
           FROM (core.roster r
             LEFT JOIN recruiting.recruits rec ON ((((r.id)::text = (rec.athlete_id)::text) AND ((rec.year >= (r.year - 5)) AND (rec.year <= r.year)))))
          GROUP BY r.team, r.year
        ), transfer_impact AS (
         SELECT transfer_portal.destination AS team,
            transfer_portal.season,
            count(*) AS transfers_in,
            round(avg(transfer_portal.stars), 2) AS avg_transfer_stars
           FROM recruiting.transfer_portal
          WHERE (transfer_portal.destination IS NOT NULL)
          GROUP BY transfer_portal.destination, transfer_portal.season
        )
 SELECT rt.team,
    rt.season,
    rt.roster_size,
    rt.five_stars,
    rt.four_stars,
    rt.three_stars,
    rt.low_stars,
    rt.blue_chip_ratio,
    rt.avg_recruit_rating,
    COALESCE(ti.transfers_in, (0)::bigint) AS transfers_in,
    ti.avg_transfer_stars,
    round(((((((COALESCE(rt.five_stars, (0)::bigint) * 5) + (COALESCE(rt.four_stars, (0)::bigint) * 4)) + (COALESCE(rt.three_stars, (0)::bigint) * 3)) + (COALESCE(rt.low_stars, (0)::bigint) * 2)))::numeric / (NULLIF(rt.roster_size, 0))::numeric), 2) AS talent_score
   FROM (roster_talent rt
     LEFT JOIN transfer_impact ti ON ((((rt.team)::text = (ti.team)::text) AND (rt.season = ti.season))))
  WHERE (rt.roster_size > 0)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW team_talent_composite; Type: COMMENT; Schema: marts; Owner: -
--

COMMENT ON MATERIALIZED VIEW marts.team_talent_composite IS 'Team roster talent composition by season. Combines recruiting ratings with current rosters.';


--
-- Name: team_tempo_metrics; Type: MATERIALIZED VIEW; Schema: marts; Owner: -
--

CREATE MATERIALIZED VIEW marts.team_tempo_metrics AS
 WITH game_plays AS (
         SELECT p.season,
            p.offense AS team,
            g.id AS game_id,
            count(*) AS plays
           FROM (core.plays p
             JOIN core.games g ON ((p.game_id = g.id)))
          WHERE ((g.season >= 2014) AND ((p.play_type)::text <> ALL (ARRAY[('Timeout'::character varying)::text, ('End Period'::character varying)::text, ('End of Half'::character varying)::text, ('End of Game'::character varying)::text, ('Kickoff'::character varying)::text])) AND (NOT (((p.period = 4) AND (abs(COALESCE(p.score_diff, 0)) > 28)) OR ((p.period >= 3) AND (abs(COALESCE(p.score_diff, 0)) > 35)))))
          GROUP BY p.season, p.offense, g.id
        ), team_tempo AS (
         SELECT game_plays.season,
            game_plays.team,
            count(DISTINCT game_plays.game_id) AS games,
            sum(game_plays.plays) AS total_plays,
            round(avg(game_plays.plays), 1) AS plays_per_game,
                CASE
                    WHEN (avg(game_plays.plays) >= (75)::numeric) THEN 'up_tempo'::text
                    WHEN (avg(game_plays.plays) >= (65)::numeric) THEN 'balanced'::text
                    ELSE 'slow'::text
                END AS tempo_tier
           FROM game_plays
          GROUP BY game_plays.season, game_plays.team
        )
 SELECT t.season,
    t.team,
    t.games,
    t.total_plays,
    t.plays_per_game,
    t.tempo_tier,
    e.epa_per_play,
    e.success_rate,
    e.explosiveness
   FROM (team_tempo t
     LEFT JOIN marts.team_epa_season e ON (((t.season = e.season) AND ((t.team)::text = (e.team)::text))))
  WHERE (t.games >= 5)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW team_tempo_metrics; Type: COMMENT; Schema: marts; Owner: -
--

COMMENT ON MATERIALIZED VIEW marts.team_tempo_metrics IS 'Team tempo metrics joining plays per game with EPA. Grain: team × season.';


--
-- Name: fanout_misses; Type: TABLE; Schema: meta; Owner: -
--

CREATE TABLE meta.fanout_misses (
    source text NOT NULL,
    key text NOT NULL,
    status_code integer NOT NULL,
    attempts integer DEFAULT 1 NOT NULL,
    last_attempt_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE fanout_misses; Type: COMMENT; Schema: meta; Owner: -
--

COMMENT ON TABLE meta.fanout_misses IS 'Misses from per-entity fan-out drainers: terminal (400/404) responses, plus 5xx failures and network faults (timeouts/connect errors, status_code 0) that survived api_client''s full retry budget (player_overview.py records these so one flaky gateway response or transient CFBD instability window cannot kill a multi-thousand-call dispatch). Keyed by (source, key) so a set-difference drainer (src/pipelines/run.py) can exclude a recently-attempted miss instead of re-spending its API call every run. source: ''coach_profiles'' | ''player_season_overview''. key: str(coach_id) for coach_profiles, ''{season}:{player_id}'' for player_season_overview. 30-day re-eligibility is enforced in run.py (FANOUT_MISS_RETRY_DAYS), not here, so late-published CFBD data -- and a transient 5xx or network-fault skip -- self-heals instead of being excluded forever. PR #75 review finding A.';


--
-- Name: COLUMN fanout_misses.status_code; Type: COMMENT; Schema: meta; Owner: -
--

COMMENT ON COLUMN meta.fanout_misses.status_code IS 'HTTP status code of the miss (400/404/5xx), or the sentinel 0 for a network fault (read/connect timeout, connection error) that survived api_client''s full retry budget with no HTTP response to report -- this column is NOT NULL, so 0 documents "no HTTP status" rather than a real server response.';


--
-- Name: COLUMN fanout_misses.attempts; Type: COMMENT; Schema: meta; Owner: -
--

COMMENT ON COLUMN meta.fanout_misses.attempts IS 'Incremented (not overwritten) on every re-encountered miss via the ON CONFLICT (source, key) DO UPDATE upsert in run.py::_record_fanout_misses -- a rising count is the operator signal that a given id keeps missing (400/404, 5xx, or network fault) rather than having been hit once.';


