--
-- Name: team_epa_season; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.team_epa_season WITH (security_invoker='true') AS
 WITH team_season_class AS (
         SELECT x.team,
            x.season,
            mode() WITHIN GROUP (ORDER BY x.classification) AS classification
           FROM ( SELECT g.home_team AS team,
                    g.season,
                    g.home_classification AS classification
                   FROM core.games g
                  WHERE (g.home_classification IS NOT NULL)
                UNION ALL
                 SELECT g.away_team,
                    g.season,
                    g.away_classification
                   FROM core.games g
                  WHERE (g.away_classification IS NOT NULL)) x
          GROUP BY x.team, x.season
        ), teams_deduped AS (
         SELECT DISTINCT ON (teams.school) teams.school,
            teams.classification
           FROM ref.teams
          ORDER BY teams.school, teams.classification
        )
 SELECT e.team,
    e.season,
    e.games_played AS games,
    e.total_plays,
    round((e.epa_per_play * (e.total_plays)::numeric), 2) AS total_epa,
    e.epa_per_play,
    e.success_rate,
    COALESCE(e.explosiveness, (0)::numeric) AS explosiveness,
    (rank() OVER (PARTITION BY e.season, COALESCE(tsc.classification, t.classification) ORDER BY e.epa_per_play DESC))::integer AS off_epa_rank,
    (rank() OVER (PARTITION BY e.season, COALESCE(tsc.classification, t.classification) ORDER BY COALESCE(d.opp_epa_per_play, (999)::numeric)))::integer AS def_epa_rank,
    COALESCE(tsc.classification, t.classification) AS classification
   FROM (((marts.team_epa_season e
     LEFT JOIN marts.defensive_havoc d ON ((((e.team)::text = (d.team)::text) AND (e.season = d.season))))
     LEFT JOIN team_season_class tsc ON ((((tsc.team)::text = (e.team)::text) AND (tsc.season = e.season))))
     LEFT JOIN teams_deduped t ON (((t.school)::text = (e.team)::text)));


--
-- Name: VIEW team_epa_season; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.team_epa_season IS 'Season-level EPA metrics per team with off_epa_rank/def_epa_rank scoped PARTITION BY season, classification. classification is season-accurate (core.games home_classification/away_classification per (team, season), ref.teams fallback) -- realignment teams (e.g. North Dakota State moving FCS -> FBS for 2026) keep their historical seasons in the correct classification partition instead of leaking into their current one.';


