 SELECT t.id,
    t.school,
    t.mascot,
    t.abbreviation,
    t.conference,
    t.classification,
    t.color,
    t.alternate_color AS alt_color,
    l.value AS logo,
    l_dark.value AS alt_logo,
    t.division
   FROM ((public.teams t
     LEFT JOIN ref.teams__logos l ON ((((l._dlt_parent_id)::text = (t._dlt_id)::text) AND ((l.value)::text !~~ '%dark%'::text))))
     LEFT JOIN ref.teams__logos l_dark ON ((((l_dark._dlt_parent_id)::text = (t._dlt_id)::text) AND ((l_dark.value)::text ~~ '%dark%'::text))));


