--
-- Name: player_mart; Type: MATERIALIZED VIEW; Schema: scouting; Owner: -
--

CREATE MATERIALIZED VIEW scouting.player_mart AS
 WITH passing_stats AS (
         SELECT player_season_stats.player_id,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'ATT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_att,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'COMPLETIONS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_cmp,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_yds,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_td,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'INT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_int,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'PCT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_pct
           FROM stats.player_season_stats
          WHERE (((player_season_stats.category)::text = 'passing'::text) AND (player_season_stats.season = 2024))
          GROUP BY player_season_stats.player_id
        ), rushing_stats AS (
         SELECT player_season_stats.player_id,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'CAR'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_car,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_yds,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_td,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YPC'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rush_ypc
           FROM stats.player_season_stats
          WHERE (((player_season_stats.category)::text = 'rushing'::text) AND (player_season_stats.season = 2024))
          GROUP BY player_season_stats.player_id
        ), receiving_stats AS (
         SELECT player_season_stats.player_id,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'REC'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YDS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec_yds,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec_td,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'YPR'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS rec_ypr
           FROM stats.player_season_stats
          WHERE (((player_season_stats.category)::text = 'receiving'::text) AND (player_season_stats.season = 2024))
          GROUP BY player_season_stats.player_id
        ), defensive_stats AS (
         SELECT player_season_stats.player_id,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TOT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS tackles,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'SACKS'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS sacks,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'TFL'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS tfl,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'PD'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS pass_def
           FROM stats.player_season_stats
          WHERE (((player_season_stats.category)::text = 'defensive'::text) AND (player_season_stats.season = 2024))
          GROUP BY player_season_stats.player_id
        ), interception_stats AS (
         SELECT player_season_stats.player_id,
            max(
                CASE
                    WHEN ((player_season_stats.stat_type)::text = 'INT'::text) THEN (player_season_stats.stat)::numeric
                    ELSE NULL::numeric
                END) AS def_int
           FROM stats.player_season_stats
          WHERE (((player_season_stats.category)::text = 'interceptions'::text) AND (player_season_stats.season = 2024))
          GROUP BY player_season_stats.player_id
        ), ppa_stats AS (
         SELECT ppa_players_season.id AS player_id,
            ppa_players_season.average_ppa__all AS ppa_avg,
            ppa_players_season.total_ppa__all AS ppa_total
           FROM metrics.ppa_players_season
          WHERE (ppa_players_season.season = 2024)
        )
 SELECT DISTINCT ON (r.id) r.id AS player_id,
    (((r.first_name)::text || ' '::text) || (r.last_name)::text) AS name,
    r.team,
    r."position",
    r.year AS roster_year,
    r.height,
    r.weight,
    r.jersey,
    r.home_city,
    r.home_state,
    rec.stars,
    rec.rating AS recruit_rating,
    rec.ranking AS national_ranking,
    rec.year AS recruit_class,
    rec.school AS high_school,
    sp.id AS scouting_id,
    sp.composite_grade,
    sp.traits,
    sp.draft_projection,
    sp.comps,
    sp.current_status AS scouting_status,
    latest_te.event_type AS portal_status,
    latest_te.to_team AS portal_destination,
    latest_te.event_date AS portal_date,
    ps.pass_att,
    ps.pass_cmp,
    ps.pass_yds,
    ps.pass_td,
    ps.pass_int,
    ps.pass_pct,
    rs.rush_car,
    rs.rush_yds,
    rs.rush_td,
    rs.rush_ypc,
    rv.rec,
    rv.rec_yds,
    rv.rec_td,
    rv.rec_ypr,
    ds.tackles,
    ds.sacks,
    ds.tfl,
    ds.pass_def,
    ints.def_int,
    ppa.ppa_avg,
    ppa.ppa_total
   FROM (((((((((core.roster r
     LEFT JOIN recruiting.recruits rec ON (((rec.athlete_id)::text = (r.id)::text)))
     LEFT JOIN scouting.players sp ON ((sp.roster_player_id = (r.id)::bigint)))
     LEFT JOIN LATERAL ( SELECT te.event_type,
            te.to_team,
            te.event_date
           FROM scouting.transfer_events te
          WHERE (te.player_id = sp.id)
          ORDER BY te.event_date DESC
         LIMIT 1) latest_te ON (true))
     LEFT JOIN passing_stats ps ON (((ps.player_id)::text = (r.id)::text)))
     LEFT JOIN rushing_stats rs ON (((rs.player_id)::text = (r.id)::text)))
     LEFT JOIN receiving_stats rv ON (((rv.player_id)::text = (r.id)::text)))
     LEFT JOIN defensive_stats ds ON (((ds.player_id)::text = (r.id)::text)))
     LEFT JOIN interception_stats ints ON (((ints.player_id)::text = (r.id)::text)))
     LEFT JOIN ppa_stats ppa ON (((ppa.player_id)::text = (r.id)::text)))
  WHERE (r.year = ( SELECT max(roster.year) AS max
           FROM core.roster))
  ORDER BY r.id, r._dlt_load_id DESC
  WITH NO DATA;


