--
-- Name: rushing_team_games; Type: TABLE; Schema: stats; Owner: -
--

CREATE TABLE stats.rushing_team_games (
    game_id bigint NOT NULL,
    season bigint,
    week bigint,
    season_type character varying,
    team character varying NOT NULL,
    conference character varying,
    opponent character varying,
    defense__attempts bigint,
    defense__rushing_yards_available bigint,
    defense__total_rushing_yards bigint,
    defense__yards_per_carry double precision,
    defense__individual_attempts bigint,
    defense__unattributed_attempts bigint,
    defense__sacks bigint,
    defense__kneels bigint,
    defense__team_rushes bigint,
    defense__multi_carrier_attempts bigint,
    defense__direction_eligible_attempts bigint,
    defense__direction_available_attempts bigint,
    defense__success_rate double precision,
    defense__ppa double precision,
    defense__total_ppa double precision,
    defense__line_yards double precision,
    defense__line_yards_total double precision,
    defense__second_level_yards bigint,
    defense__second_level_yards_total bigint,
    defense__open_field_yards double precision,
    defense__open_field_yards_total bigint,
    defense__stuff_rate double precision,
    defense__power_success double precision,
    defense__explosiveness double precision,
    defense__touchdown_status_available bigint,
    defense__rushing_touchdowns bigint,
    defense__directions__unknown__carries bigint,
